window.DB_QUIZ = {"meta":{"title":"数据库原理与应用","subtitle":"专升本分章刷题","total":589,"baseTotal":238,"baseSourceTotal":240,"baseDuplicatesRemoved":2,"addedTotal":351,"skippedDuplicates":0,"chapterCount":14,"kindCounts":{"choice":193,"judge":115,"open":281}},"chapters":[{"id":1,"title":"第一章 数据库系统与关系模型","shortTitle":"数据库系统与关系模型","count":81},{"id":2,"title":"第二章 完整性约束与数据库设计基础","shortTitle":"完整性约束与数据库设计基础","count":28},{"id":3,"title":"第三章 SQL 基础与数据定义","shortTitle":"SQL 基础与数据定义","count":63},{"id":4,"title":"第四章 单表查询","shortTitle":"单表查询","count":53},{"id":5,"title":"第五章 聚合、分组与排序","shortTitle":"聚合、分组与排序","count":43},{"id":6,"title":"第六章 多表连接与子查询","shortTitle":"多表连接与子查询","count":71},{"id":7,"title":"第七章 视图与索引","shortTitle":"视图与索引","count":52},{"id":8,"title":"第八章 E-R 图与数据库概念设计","shortTitle":"E-R 图与数据库概念设计","count":37},{"id":9,"title":"第九章 E-R 图到关系模式的转换","shortTitle":"E-R 图到关系模式的转换","count":23},{"id":10,"title":"第十章 函数依赖与规范化","shortTitle":"函数依赖与规范化","count":28},{"id":11,"title":"第十一章 存储过程与游标","shortTitle":"存储过程与游标","count":22},{"id":12,"title":"第十二章 触发器","shortTitle":"触发器","count":33},{"id":13,"title":"第十三章 综合设计案例","shortTitle":"综合设计案例","count":13},{"id":14,"title":"第十四章 综合 SQL 练习","shortTitle":"综合 SQL 练习","count":42}],"questions":[{"id":"1-01","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":1,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"下列概念中，负责定义、操纵、控制和维护数据库的软件系统是（ ）。","options":["数据库","数据库管理系统","数据库应用系统","数据库管理员"],"answer":["B"],"explanation":"数据库 DB 存放数据；数据库管理系统 DBMS 是管理数据库的软件；数据库系统 DBS 是由数据库、DBMS、应用程序、人员和规范等构成的整体。题目强调“软件系统”和“管理数据库”，对应 DBMS。DBA 是负责规划、维护和管理数据库的人员，不是软件。"},{"id":"1-02","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":2,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"某学校使用 SQL Server 建立教务数据库，教师和学生通过教务网页查询成绩。该网页、数据库、SQL Server、服务器和教务管理员共同构成（ ）。","options":["数据库","数据库管理系统","数据库系统","数据文件"],"answer":["C"],"explanation":"数据库系统 DBS 是引入数据库后的完整计算机系统，通常包含数据库、DBMS、应用程序、数据库管理员、用户和运行环境。题目列出了数据库、DBMS、应用和人员，已经构成数据库系统，而不是单一的数据库。"},{"id":"1-03","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":3,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"数据库就是数据库管理系统。","options":[],"answer":"错","explanation":"数据库是被组织、存储和共享的数据集合；数据库管理系统是用于建立、使用和维护数据库的软件。数据库是 DBMS 管理的对象，二者层次和职责不同。类似“仓库里的货物”和“仓库管理系统”的区别。"},{"id":"1-04","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":4,"title":"填空题","kind":"open","answerKind":"open","typeName":"填空","stem":"数据库系统通常由数据库、数据库管理系统、应用程序、________ 和用户等组成。","options":[],"answer":"数据库管理员（DBA）","explanation":"DBS 是人机系统，人员是重要组成部分。数据库管理员负责数据库的规划、设计、安全、备份、恢复和性能维护。答题时若题目把“运行环境”或“规范”也列入组成，也应结合教材表述接受。"},{"id":"1-05","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":5,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"数据库系统与文件系统相比，最本质的区别是（ ）。","options":["数据库中的数据可以长期保存","数据库系统的数据整体结构化","数据库系统需要使用磁盘","数据库系统中的数据一定没有冗余"],"answer":["B"],"explanation":"文件系统也能长期保存数据，也会使用磁盘，所以 A、C 不是本质区别。数据库系统按统一数据模型组织整个组织的数据，具有整体结构性；而文件系统通常只是记录内部有结构，文件之间缺乏统一联系。D 也错误，数据库允许受控冗余。"},{"id":"1-06","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":6,"title":"多项选择题","kind":"choice","answerKind":"choice","typeName":"多项选择","stem":"下列属于数据库系统特点的是（ ）。","options":["数据结构化","数据共享性高、冗余度低","数据独立性较高","由 DBMS 统一管理和控制"],"answer":["A","B","C","D"],"explanation":"四项均是数据库系统的主要特点。DBMS 还提供安全性控制、完整性控制、并发控制和恢复能力。需要注意，“冗余度低”不等于“绝对没有冗余”；为实现连接和性能优化，外键或派生字段可能形成受控冗余。"},{"id":"1-07","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":7,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"当数据库的存储结构由普通磁盘改为更快的存储设备，而应用程序基本不改动，这主要体现（ ）。","options":["逻辑独立性","物理独立性","位置独立性","数据完整性"],"answer":["B"],"explanation":"物理独立性表示数据的物理存储结构或存取方式改变时，不必修改应用程序；逻辑独立性表示数据库逻辑结构改变时，应用程序尽量不受影响。题目改变的是存储结构，因此是物理独立性。"},{"id":"1-08","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":8,"title":"简答题","kind":"open","answerKind":"open","typeName":"简答","stem":"简述三级模式结构中外模式、模式和内模式的含义及数量关系。","options":[],"answer":"外模式是用户能看见和使用的局部数据逻辑结构，可以多个；模式是全体数据的逻辑结构和特征，通常一个；内模式是数据的物理存储结构，通常一个。","explanation":"可记为“外模多、模式一、内模一”。外模式通常与视图、用户视图对应；模式对应整个数据库的逻辑结构；内模式对应存储文件、索引和存储组织。两级映像中，外模式/模式映像支持逻辑独立性，模式/内模式映像支持物理独立性。"},{"id":"1-09","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":9,"title":"填空题","kind":"open","answerKind":"open","typeName":"填空","stem":"数据模型按抽象层次通常分为概念模型、________ 和物理模型。","options":[],"answer":"逻辑模型","explanation":"概念模型面向用户和业务，典型形式是 E-R 模型；逻辑模型面向数据库系统组织数据，如关系模型、层次模型和网状模型；物理模型描述数据在存储介质上的组织方式。概念模型与具体 DBMS 无关，物理模型与具体 DBMS 和存储技术关系密切。"},{"id":"1-10","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":10,"title":"简答题","kind":"open","answerKind":"open","typeName":"简答","stem":"数据模型的三要素是什么？分别描述什么特性？","options":[],"answer":"数据结构、数据操作和完整性约束。数据结构描述系统的静态特性；数据操作描述动态特性；完整性约束规定数据必须满足的语义规则。","explanation":"关系模型中，数据结构是二维表；数据操作包括查询、插入、更新、删除以及关系代数运算；完整性约束包括实体完整性、参照完整性和用户定义完整性。三要素缺一不可，不能把“数据类型”单独当作数据模型三要素之一。"},{"id":"1-11","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":11,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"在关系模型中，表中的一行称为（ ）。","options":["属性","元组","域","关系模式"],"answer":["B"],"explanation":"一张二维表称为关系，表中的一行称为元组或记录，一列称为属性或字段，属性允许取值的集合称为域。关系模式描述表名和属性结构，是“型”；某一时刻的具体表内容是关系实例，是“值”。"},{"id":"1-12","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":12,"title":"填空题","kind":"open","answerKind":"open","typeName":"填空","stem":"关系中属性的个数称为关系的 ________，元组的个数称为关系的 ________。","options":[],"answer":"目（度）；基数","explanation":"“目看列，基数看行”。例如 Student(StudentID, Name, Gender) 有 3 个属性，目为 3；若当前有 50 条学生记录，基数为 50。不要把这两个术语互换。"},{"id":"1-13","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":13,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"关系中元组的顺序和属性的顺序在理论上都不重要，但同一列的值必须来自同一个域。","options":[],"answer":"对","explanation":"关系是元组的集合，理论上行序无关；属性也构成集合，理论上列序无关。但每一列必须同质，即同一列的所有值来自同一个域。实际 DBMS 中为了输出稳定，常通过 `ORDER BY` 明确排序，但这不改变关系模型的理论性质。"},{"id":"1-14","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":14,"title":"多项选择题","kind":"choice","answerKind":"choice","typeName":"多项选择","stem":"下列属于关系基本性质的是（ ）。","options":["同一列中的值来自同一个域","不同列的属性名可以重复","元组不能完全重复","每个分量应是原子值"],"answer":["A","C","D"],"explanation":"关系的列同质、行序无关、列序无关、元组不重复、分量原子。B 错误，同一关系中的属性名不能重复。分量原子意味着一个单元格不能保存“多个电话号码”这样的多值集合；多值属性应拆成独立表。"},{"id":"1-15","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":15,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"给定关系 `R(A, B, C)`，函数依赖为 `A -> B`、`A -> C`。下列说法正确的是（ ）。","options":["A 是超键，但不是候选键","A 是候选键，也是主键的唯一候选","A 一定是主键","A 不能唯一标识元组"],"answer":["B"],"explanation":"A 能决定全部属性 A、B、C，且 A 是单个属性，不存在可去掉的多余属性，因此 A 是候选键。若该关系只有这一个候选键，则 A 是唯一候选键，可以被选为主键。但“候选键”是客观性质，“主键”是从候选键中选定用于实现的那一个，题目若未说明选定情况，不能仅由函数依赖断定它已被指定为主键。"},{"id":"1-16","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":16,"title":"多项选择题","kind":"choice","answerKind":"choice","typeName":"多项选择","stem":"关于主键和外键，下列说法正确的是（ ）。","options":["主键不能为 NULL","一个表只能有一个主键约束","外键可以重复","外键在任何情况下都不能为 NULL"],"answer":["A","B","C"],"explanation":"主键用于唯一标识元组，不能重复且不能为空；一个表只有一个主键约束，但主键可由多列组成。外键用于表示参照关系，允许多行引用同一个父键，也可以在未附加 `NOT NULL` 时取 NULL，表示“暂时没有对应引用”。因此 D 错误。"},{"id":"1-17","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":17,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"关系代数中，“从学生关系中只取出计算机学院学生的姓名和学号”需要组合使用（ ）。","options":["选择和投影","投影和笛卡尔积","并和差","除和连接"],"answer":["A"],"explanation":"“只取计算机学院学生”是按条件筛选行，使用选择运算；“只显示姓名和学号”是选取列，使用投影运算。关系代数的投影通常自动消除重复元组；SQL 中若不希望出现重复，需要写 `SELECT DISTINCT`。"},{"id":"1-18","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":18,"title":"综合应用题","kind":"open","answerKind":"open","typeName":"综合题","stem":"关系 `R(A, B)` 有 3 个元组，关系 `S(C, D)` 有 4 个元组。分别回答：\n\n（1）`R × S` 的属性数和元组数各是多少？\n（2）`R ∪ S` 能否直接执行？为什么？\n（3）自然连接与笛卡尔积的主要区别是什么？","options":[],"answer":"（1）属性数 4，元组数 12。（2）不能直接执行，因为 R 和 S 的属性结构不兼容，并运算要求属性个数相同且对应属性域兼容。（3）自然连接先按同名属性相等进行匹配，再合并同名属性；笛卡尔积无条件组合全部元组。","explanation":"笛卡尔积的属性数为两关系属性数之和，元组数为两关系元组数之积。并、差、交都要求关系结构兼容。自然连接结果保留同名属性的单一副本，并删除无法匹配的组合；若没有同名属性，自然连接会退化为笛卡尔积。"},{"id":"doc-001","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":1,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"区分不同实体的依据是（ ）。","options":["名称","属性","对象","概念"],"answer":["B"],"explanation":"正确答案：B。实体依靠属性组合来区分。名称只是属性之一，可能重复，不能单独作为唯一区分依据。","origin":"《数据库原理及应用》总复习"},{"id":"doc-132","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":1,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"关系必须有唯一的候选键。","options":[],"answer":"错","explanation":"答案：错。一个关系可以有多个候选键，但主键只能从候选键中选定一个。","origin":"《数据库原理及应用》总复习"},{"id":"doc-002","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":2,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"现实世界中客观存在并能相互区别的事物称为（ ）。","options":["实体","实体集","字段","记录"],"answer":["A"],"explanation":"正确答案：A。实体是现实世界中客观存在并能与其他对象相互区别的事物；实体集是同型实体的集合。","origin":"《数据库原理及应用》总复习"},{"id":"doc-133","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":2,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"现实世界中客观存在并能相互区别的事物称为属性。","options":[],"answer":"错","explanation":"答案：错。客观存在并能相互区别的事物是实体；属性用于描述实体特征。","origin":"《数据库原理及应用》总复习"},{"id":"doc-003","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":3,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"现实世界中事物的特性在信息世界中称为（ ）。","options":["实体","实体标识符","属性","关键码"],"answer":["C"],"explanation":"正确答案：C。现实事物的特性在信息世界中抽象为属性。属性描述实体某一方面，并受域约束。","origin":"《数据库原理及应用》总复习"},{"id":"doc-134","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":3,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"关系中不同的属性可来自同一个域。","options":[],"answer":"对","explanation":"答案：对。不同属性可以来自同一个域，例如姓名和课程名都可以使用字符型域。","origin":"《数据库原理及应用》总复习"},{"id":"doc-135","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":4,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"关系中每一列的分量必须是同类型的数据。","options":[],"answer":"对","explanation":"答案：对。关系的每一列必须同质，同一列中的分量属于同一域并具有相同类型。","origin":"《数据库原理及应用》总复习"},{"id":"doc-136","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":5,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"任何一个关系模式一定有候选键。","options":[],"answer":"对","explanation":"答案：对。有限关系总能找到能够唯一确定全部属性的最小属性组，因此至少存在一个候选键。","origin":"《数据库原理及应用》总复习"},{"id":"doc-137","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":6,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"如果在一个关系中，存在多个属性(或属性组)都能用来唯一标识该关系的元组，且其任何子集都不具有这一特性，则这些属性(或属性组)被称为该关系的候选键，简称为键。","options":[],"answer":"对","explanation":"答案：对。候选键必须能唯一标识元组且满足极小性，简称键。","origin":"《数据库原理及应用》总复习"},{"id":"doc-138","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":7,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"如果在一个关系中，存在多个属性(或属性组)都能用来唯一标识该关系的元组，且其任何子集都不具有这一特性，则这些属性(或属性组)被称为该关系的外键。","options":[],"answer":"错","explanation":"答案：错。能唯一标识本关系元组且满足极小性的属性组是候选键，不是外键。","origin":"《数据库原理及应用》总复习"},{"id":"doc-009","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":9,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"概念模型是现实世界的第一层抽象，这一类最著名的模型是（ ）。","options":["层次模型","关系模型","网状模型","实体-联系模型"],"answer":["D"],"explanation":"正确答案：D。概念模型最常用的表示是实体-联系模型。层次、网状和关系模型属于逻辑数据模型。","origin":"《数据库原理及应用》总复习"},{"id":"doc-140","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":9,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"一个关系中可以有两个完全相同的元组。","options":[],"answer":"错","explanation":"答案：错。关系是元组集合，不允许出现两个完全相同的元组。","origin":"《数据库原理及应用》总复习"},{"id":"doc-010","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":10,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"采用二维表格结构表达实体类型及实体间联系的数据模型是（ ）。","options":["层次模型","关系模型","网状模型","实体-联系模型"],"answer":["B"],"explanation":"正确答案：B。关系模型用二维表表达实体及实体间联系，表与表通过公共属性建立联系。","origin":"《数据库原理及应用》总复习"},{"id":"doc-141","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":10,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"三级模式和两级映像提高了数据库系统的数据独立性。","options":[],"answer":"对","explanation":"答案：对。三级模式与两级映像提高了数据独立性，用户和应用程序不必了解底层存储细节。","origin":"《数据库原理及应用》总复习"},{"id":"doc-011","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":11,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"不同的数据库管理系统支持不同的数据模型。在常用的数据模型中，不包括（ ）","options":["网状模型","链状模型","层次模型","关系模型"],"answer":["B"],"explanation":"正确答案：B。常见逻辑数据模型包括层次、网状、关系和面向对象模型，没有“链状模型”。","origin":"《数据库原理及应用》总复习"},{"id":"doc-012","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":12,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"关系数据模型的3个要素是（ ）。","options":["关系数据结构、关系操作集合和关系规范化理论","关系数据结构、关系规范化理论和关系的完整性约束","关系规范化理论、关系操作集合和关系的完整性约束","关系数据结构、关系操作集合和关系的完整性约束"],"answer":["D"],"explanation":"正确答案：D。关系数据模型由关系数据结构、关系操作集合和关系完整性约束三部分组成。","origin":"《数据库原理及应用》总复习"},{"id":"doc-013","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":13,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"在数据库技术中，独立于计算机系统的模型是（ ）。","options":["E-R模型","关系模型","层次模型","面向对象的模型"],"answer":["A"],"explanation":"正确答案：A。E-R 模型描述业务概念结构，独立于具体计算机系统和 DBMS，是概念模型。","origin":"《数据库原理及应用》总复习"},{"id":"doc-014","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":14,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"如果在一个关系中，存在多个属性(或属性组)都能用来唯一标识该关系的元组，且其任何子集都不具有这一特性，则这些属性(或属性组)被称为该关系的（ ）。","options":["候选键","主键","外键","连接键"],"answer":["A"],"explanation":"正确答案：A。能唯一标识元组且任何真子集都不能唯一标识元组的属性组是候选键。","origin":"《数据库原理及应用》总复习"},{"id":"doc-145","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":14,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"数据独立性表示数据结构变化时尽量不修改应用程序。","options":[],"answer":"对","explanation":"答案：对。数据独立性表示数据结构变化时尽量不修改应用程序，分为逻辑独立性和物理独立性。","origin":"《数据库原理及应用》总复习"},{"id":"doc-015","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":15,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"一个关系模式中的键（ ）。","options":["可以由多个任意属性组成","至多由一个属性组成","由一个或多个属性组成，其值能够惟一标识关系中一个元组","以上都不是"],"answer":["C"],"explanation":"正确答案：C。键由一个或多个属性组成，其值能唯一标识元组；主键是选定的候选键。","origin":"《数据库原理及应用》总复习"},{"id":"doc-146","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":15,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"关系代数的运算对象是关系，运算结果也为关系。","options":[],"answer":"对","explanation":"答案：对。关系代数以关系为运算对象，运算结果仍是关系，因此具有封闭性。","origin":"《数据库原理及应用》总复习"},{"id":"doc-016","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":16,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"候选键的属性可以有（ ）。","options":["多个","0个","1个","1个或多个"],"answer":["D"],"explanation":"正确答案：D。候选键可由一个属性或属性组构成，因此属性个数可以是 1 个或多个。","origin":"《数据库原理及应用》总复习"},{"id":"doc-147","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":16,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"关系代数中的选择运算是从行的角度进行运算，而投影运算是从列的角度进行运算。","options":[],"answer":"对","explanation":"答案：对。选择按行筛选，投影按列选取，这是关系代数中最基本的两个专门运算。","origin":"《数据库原理及应用》总复习"},{"id":"doc-017","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":17,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"候选键中的属性称为（ ）。","options":["非主属性","主属性","复合属性","关键属性"],"answer":["B"],"explanation":"正确答案：B。包含在任意候选键中的属性称为主属性，不包含在任何候选键中的属性称为非主属性。","origin":"《数据库原理及应用》总复习"},{"id":"doc-148","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":17,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"DBS是采用了数据库技术的计算机系统。DBS是一个集合体，包含计算机硬件、DB、DBMS、数据库应用系统等软件和用户。","options":[],"answer":"对","explanation":"答案：对。DBS 是引入数据库后的计算机系统，包含硬件、数据库、DBMS、应用、人员和规范。","origin":"《数据库原理及应用》总复习"},{"id":"doc-018","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":18,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"下面的选项不是关系数据库基本特征的是（ ）。","options":["不同的列应有不同的数据类型","不同的列应有不同的列名","与行的次序无关","与列的次序无关"],"answer":["A"],"explanation":"正确答案：A。关系要求同一列同域、列名不同、行列次序无关；不同列允许使用相同数据类型。","origin":"《数据库原理及应用》总复习"},{"id":"doc-149","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":18,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"ORACLE是大型数据库管理系统。","options":[],"answer":"对","explanation":"答案：对。Oracle 是常见的大型关系数据库管理系统，支持事务、高并发和企业级管理。","origin":"《数据库原理及应用》总复习"},{"id":"doc-019","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":19,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"设关系R和S具有相同的目，且它们相对应的属性的值取自同一个域，则R-(R-S)等于（ ）。","options":["R∪S","R∩S","R×S","R÷S"],"answer":["B"],"explanation":"正确答案：B。由集合恒等式 R-(R-S)=R∩S，差运算两次的结果正好是交集。","origin":"《数据库原理及应用》总复习"},{"id":"doc-150","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":19,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"数据库管理系统DBMS是操作系统的一部分。","options":[],"answer":"错","explanation":"答案：错。DBMS 是位于用户和操作系统之间的系统软件，不是操作系统的一部分。","origin":"《数据库原理及应用》总复习"},{"id":"doc-020","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":20,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"从一个关系中取出满足某个条件的所有记录形成一个新的关系的操作是（ ）操作 。","options":["投影","连接","选择","复制"],"answer":["C"],"explanation":"正确答案：C。选择运算按条件筛选行，对应 SQL 的 WHERE；投影按属性选列。","origin":"《数据库原理及应用》总复习"},{"id":"doc-151","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":20,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"数据库管理员的缩写为DBA。","options":[],"answer":"对","explanation":"答案：对。数据库管理员的英文缩写是 DBA。","origin":"《数据库原理及应用》总复习"},{"id":"doc-152","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":21,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"数据库管理员的缩写为DMA。","options":[],"answer":"错","explanation":"答案：错。DBA 表示数据库管理员；DMA 不是该概念的标准缩写。","origin":"《数据库原理及应用》总复习"},{"id":"doc-022","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":22,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"关系数据库中的投影操作是指从关系中（ ）。","options":["抽出特定记录","抽出特定字段","建立相应的影像","建立相应的图形"],"answer":["B"],"explanation":"正确答案：B。投影从关系中选取指定属性列，并自动消除结果中的重复元组。","origin":"《数据库原理及应用》总复习"},{"id":"doc-153","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":22,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"数据库是数据库系统的核心。","options":[],"answer":"对","explanation":"答案：对。DBMS 是数据库系统的核心，负责定义、操纵、控制、维护和恢复数据库。","origin":"《数据库原理及应用》总复习"},{"id":"doc-023","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":23,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"在关系代数的连接操作中，哪一种连接操作需要取消重复列？（ ）","options":["自然连接","笛卡儿积","等值连接","θ连接"],"answer":["A"],"explanation":"正确答案：A。自然连接会合并同名属性并取消重复列，等值连接和 θ 连接通常保留两表全部属性。","origin":"《数据库原理及应用》总复习"},{"id":"doc-154","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":23,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"数据库系统避免了一切冗余。","options":[],"answer":"错","explanation":"答案：错。数据库系统减少并控制冗余，但不可能也没有必要避免一切冗余。","origin":"《数据库原理及应用》总复习"},{"id":"doc-024","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":24,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"在关系代数中，（ ）操作称为从两个关系的笛卡儿积中选取它们属性间满足一定条件的元组。","options":["投影","选择","自然连接","θ连接"],"answer":["D"],"explanation":"正确答案：D。θ 连接从两个关系的笛卡尔积中选取属性间满足给定条件的元组。","origin":"《数据库原理及应用》总复习"},{"id":"doc-155","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":24,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"数据库只存储业务数据，不保存元数据、索引和日志。","options":[],"answer":"错","explanation":"答案：错。数据库还保存元数据、索引、视图定义、日志和权限信息，不只是业务数据本身。","origin":"《数据库原理及应用》总复习"},{"id":"doc-025","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":25,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"DBS是采用了数据库技术的计算机系统。DBS是一个集合体，包含计算机硬件、数据库、DBMS、数据库应用系统等软件和（ ）。","options":["用户","网络操作系统","通信线路","交换机"],"answer":["A"],"explanation":"正确答案：A。数据库系统是人机系统，除硬件、数据库、DBMS 和应用外，还包括数据库管理员和用户。","origin":"《数据库原理及应用》总复习"},{"id":"doc-156","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":25,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"数据库中的数据可以共享。","options":[],"answer":"对","explanation":"答案：对。数据库中的数据可被多个用户和应用共享，是数据库系统的重要特点。","origin":"《数据库原理及应用》总复习"},{"id":"doc-026","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":26,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"逻辑数据独立性是指（ ）。","options":["概念模式改变，外模式和应用程序不变","概念模式改变，内模式不变","内模式改变，概念模式不变","内模式改变，外模式和应用程序不变"],"answer":["A"],"explanation":"正确答案：A。逻辑独立性由外模式/模式映像保证，使概念模式变化时外模式和应用程序尽量不变。","origin":"《数据库原理及应用》总复习"},{"id":"doc-157","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":26,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"当数据库的内模式发生改变时，用户编写的应用程序必须随之改变。","options":[],"answer":"错","explanation":"答案：错。内模式变化可通过模式/内模式映像维持概念模式不变，应用程序通常无需修改。","origin":"《数据库原理及应用》总复习"},{"id":"doc-027","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":27,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"数据库系统中，用（ ）描述全部数据的整体逻辑结构。","options":["外模式","存储模式","内模式","概念模式"],"answer":["D"],"explanation":"正确答案：D。概念模式也称模式，描述数据库全体数据的整体逻辑结构，一个数据库只有一个模式。","origin":"《数据库原理及应用》总复习"},{"id":"doc-158","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":27,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"一个应用可以使用多个外模式，同一外模式也可被多个应用使用。","options":[],"answer":"对","explanation":"答案：对。一个应用可使用多个外模式，同一外模式也可被多个应用或用户使用。","origin":"《数据库原理及应用》总复习"},{"id":"doc-028","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":28,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"物理数据独立性是指（ ）。","options":["概念模式改变，外模式和应用程序不变","概念模式改变，内模式不变","内模式改变，概念模式不变","内模式改变，外模式和应用程序不变"],"answer":["D"],"explanation":"正确答案：D。物理独立性由模式/内模式映像保证，使内模式变化时概念模式和应用尽量不变。","origin":"《数据库原理及应用》总复习"},{"id":"doc-159","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":28,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"三级模式和两级映像的主要作用是提高数据独立性。","options":[],"answer":"对","explanation":"答案：对。三级模式与两级映像的主要作用是屏蔽结构变化，提高数据库的数据独立性。","origin":"《数据库原理及应用》总复习"},{"id":"doc-160","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":29,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"外模式/模式映像保证逻辑独立性。","options":[],"answer":"对","explanation":"答案：对。外模式/模式映像保证逻辑独立性，使概念模式变化时外模式和应用程序尽量不变。","origin":"《数据库原理及应用》总复习"},{"id":"doc-161","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":30,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"内模式改变时，可通过调整模式/内模式映像保持概念模式不变。","options":[],"answer":"对","explanation":"答案：对。内模式改变时，可通过调整模式/内模式映像保持概念模式不变，从而保证物理独立性。","origin":"《数据库原理及应用》总复习"},{"id":"doc-162","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":31,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"在数据库的三级模式结构中，模式是描述数据库中数据的全局逻辑结构的。","options":[],"answer":"对","explanation":"答案：对。模式也称概念模式，描述数据库中全体数据的全局逻辑结构。","origin":"《数据库原理及应用》总复习"},{"id":"doc-164","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":33,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"在数据库的三级模式结构中，外模式是描述数据库中数据的全局逻辑结构的。","options":[],"answer":"错","explanation":"答案：错。外模式描述用户可见的局部逻辑结构；描述全局逻辑结构的是模式。","origin":"《数据库原理及应用》总复习"},{"id":"doc-190","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":59,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"事务在MySQL中相当于一个工作单元，也就是一条SQL语句。","options":[],"answer":"错","explanation":"答案：错。事务可以由多条 SQL 组成，是逻辑工作单元，不等于一条 SQL。","origin":"《数据库原理及应用》总复习"},{"id":"doc-191","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":60,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"事务是并发控制的基本单位。","options":[],"answer":"对","explanation":"答案：对。事务是并发控制和恢复的基本单位。","origin":"《数据库原理及应用》总复习"},{"id":"doc-192","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":61,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"两个或两个以上的事务分别申请封锁对方已经封锁的数据对象，导致长期等等待而无法继续运行下去的现象称为活锁。","options":[],"answer":"错","explanation":"答案：错。两个事务互相等待对方已封锁的数据对象属于死锁；活锁是事务长期得不到调度。","origin":"《数据库原理及应用》总复习"},{"id":"doc-193","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":62,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"事务的开始与结束可以由用户显式地控制，也可以由DBMS按照默认规则自动划分。","options":[],"answer":"对","explanation":"答案：对。事务边界可由用户显式控制，也可由 DBMS 按自动提交等默认规则划分。","origin":"《数据库原理及应用》总复习"},{"id":"doc-194","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":63,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"事务的原子性是指事务在执行时，应该遵守“要么全做，要么全不做”的原则，即不允许事务部分地完成。","options":[],"answer":"对","explanation":"答案：对。原子性要求事务中的操作要么全部生效，要么全部撤销。","origin":"《数据库原理及应用》总复习"},{"id":"doc-195","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":64,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"当同一数据库系统中有多个事务并发运行时，如果不加以适当控制，就可能产生数据的不一致性问题。","options":[],"answer":"对","explanation":"答案：对。并发事务若缺少适当隔离控制，会出现脏读、不可重复读或丢失更新。","origin":"《数据库原理及应用》总复习"},{"id":"doc-065","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":65,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"下面关于数据库中表的行和列的叙述正确的是（ ）。","options":["表中的行是有序的，列是无序的","表中的列是有序的，行是无序的","表中的行和列都是有序的","表中的行和列都是无序的"],"answer":["D"],"explanation":"正确答案：D。关系模型理论上把关系看作元组集合，行列顺序都无意义；显示顺序可用 ORDER BY 指定。","origin":"《数据库原理及应用》总复习"},{"id":"doc-114","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":114,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"“一个事务对数据库的所有操作，是一个不可分割的工作单元，这些操作要么全部执行要么什么也不做”，这是事务的（ ）。","options":["原子性","一致性","隔离性","持久性"],"answer":["A"],"explanation":"正确答案：A。事务的原子性要求事务中的操作要么全部提交，要么全部回滚。","origin":"《数据库原理及应用》总复习"},{"id":"doc-115","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":115,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"若事务T对数据R已经加了X锁，则其他事务对数据R（ ）。","options":["可以加S锁不能加X锁","不能加S锁可以加X锁","可以加S锁也可以加X锁","不能加任何锁"],"answer":["D"],"explanation":"正确答案：D。X 锁是排他锁，已在数据 R 上加 X 锁后，其他事务不能再加 S 锁或 X 锁。","origin":"《数据库原理及应用》总复习"},{"id":"doc-116","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":116,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"并发操作会带来哪些数据不一致性？（ ）","options":["丢失更新、不可重复读、“脏”读、死锁","不可重复读、“脏”读、死锁","丢失更新、不可重复读、“脏”读","丢失更新、不可重复读、死锁"],"answer":["C"],"explanation":"正确答案：C。并发控制主要防止丢失更新、不可重复读和脏读；死锁是并发控制的副作用之一，不是数据不一致类型。","origin":"《数据库原理及应用》总复习"},{"id":"doc-126","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":126,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"设关系R和S的元组个数分别为100和300，关系T是R与S的笛卡儿积，则T的元组个数为（ ）。","options":["400","10000","30000","90000"],"answer":["C"],"explanation":"正确答案：C。笛卡尔积元组数为两关系元组数之积，即 100×300=30000。","origin":"《数据库原理及应用》总复习"},{"id":"doc-127","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":127,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"以下不属于结构数据模型的是（ ）。","options":["关系模型","链状模型","网状模型","层次模型"],"answer":["B"],"explanation":"正确答案：B。结构化数据模型包括层次、网状和关系模型；“链状模型”不是常见结构数据模型。","origin":"《数据库原理及应用》总复习"},{"id":"doc-128","chapter":1,"chapterTitle":"第一章 数据库系统与关系模型","number":128,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"在关系R中，属性A不是主键，而是另一个关系S的主键，则在R中，属性A是（ ）。","options":["R的候选键","R的外键","S的候选键","S的外键"],"answer":["B"],"explanation":"正确答案：B。属性 A 在 R 中不是本关系主键，却引用 S 的主键，因此 A 是 R 的外键。","origin":"《数据库原理及应用》总复习"},{"id":"2-01","chapter":2,"chapterTitle":"第二章 完整性约束与数据库设计基础","number":1,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"保证关系中每一行都能被唯一区分的完整性约束是（ ）。","options":["实体完整性","参照完整性","域完整性","用户定义完整性"],"answer":["A"],"explanation":"实体完整性针对主键，要求主键非空且唯一，从而保证每个实体可区分。参照完整性针对外键；域完整性限制列的数据类型和取值范围；用户定义完整性用于实现具体业务规则。"},{"id":"2-02","chapter":2,"chapterTitle":"第二章 完整性约束与数据库设计基础","number":2,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"学生表 `Student(StudentID, Name)` 与选课表 `Enrollment(StudentID, CourseID, Score)` 中，`Enrollment.StudentID` 引用 `Student.StudentID`，这属于（ ）。","options":["实体完整性","参照完整性","域完整性","事务完整性"],"answer":["B"],"explanation":"外键值要么为 NULL，要么等于父表中已经存在的主键值，这样才能避免出现“引用了不存在的学生”。这就是参照完整性。若把 `Enrollment(StudentID, CourseID)` 设为主键，则其非空和唯一要求才属于实体完整性。"},{"id":"2-03","chapter":2,"chapterTitle":"第二章 完整性约束与数据库设计基础","number":3,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"`CHECK (Score BETWEEN 0 AND 100)` 主要体现域完整性或用户定义完整性。","options":[],"answer":"对","explanation":"`CHECK` 可以限制一个列或组合列的取值范围，属于域完整性或用户定义完整性的常用实现。不同教材对“域完整性”和“用户定义完整性”的边界表述可能略有差异，答题时应结合题目给出的分类。"},{"id":"2-04","chapter":2,"chapterTitle":"第二章 完整性约束与数据库设计基础","number":4,"title":"填空题","kind":"open","answerKind":"open","typeName":"填空","stem":"数据库的完整性约束中，专门用于规定具体业务规则的是 ________ 完整性。","options":[],"answer":"用户定义","explanation":"用户定义完整性针对具体应用语义，例如“订单金额不得小于 0”“员工入职日期不得晚于当前日期”。它可以用 `CHECK`、触发器或存储过程实现。实体完整性和参照完整性是关系模型中的通用约束。"},{"id":"2-05","chapter":2,"chapterTitle":"第二章 完整性约束与数据库设计基础","number":5,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"关于 `PRIMARY KEY` 和 `UNIQUE`，下列说法正确的是（ ）。","options":["两者都允许 NULL","`PRIMARY KEY` 不允许 NULL，`UNIQUE` 通常允许 NULL","一个表只能有一个 `UNIQUE` 约束","`UNIQUE` 不允许重复，所以等价于主键"],"answer":["B"],"explanation":"主键要求非空且唯一；唯一约束要求非 NULL 值不重复，但通常允许 NULL。不同 DBMS 对唯一索引中多个 NULL 的处理存在差异，例如 SQL Server 与 MySQL 的行为不完全相同。一个表可以有多个唯一约束，但只能有一个主键约束。"},{"id":"2-06","chapter":2,"chapterTitle":"第二章 完整性约束与数据库设计基础","number":6,"title":"多项选择题","kind":"choice","answerKind":"choice","typeName":"多项选择","stem":"删除父表中被外键引用的记录时，可能采用的处理策略有（ ）。","options":["`RESTRICT` 或 `NO ACTION`","`CASCADE`","`SET NULL`","忽略外键直接删除"],"answer":["A","B","C"],"explanation":"`RESTRICT` 或 `NO ACTION` 拒绝删除；`CASCADE` 级联删除子表记录；`SET NULL` 将子表外键置为空，前提是外键列允许 NULL。直接忽略外键会破坏参照完整性。部分 DBMS 还支持 `SET DEFAULT`，但并非所有 DBMS 都支持。"},{"id":"2-07","chapter":2,"chapterTitle":"第二章 完整性约束与数据库设计基础","number":7,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"建表时应先创建被引用的父表，再创建包含外键的子表。","options":[],"answer":"对","explanation":"外键引用的父表主键必须已经存在，因此先建父表、后建子表。删除时顺序相反，通常先处理子表或先删除外键约束，再删除父表，以免破坏参照关系。"},{"id":"2-08","chapter":2,"chapterTitle":"第二章 完整性约束与数据库设计基础","number":8,"title":"简答题","kind":"open","answerKind":"open","typeName":"简答","stem":"说明主键、唯一约束和外键在完整性控制中的不同作用。","options":[],"answer":"主键保证行唯一且非空；唯一约束保证指定列或列组在允许 NULL 的规则下不重复；外键保证子表引用值在父表中存在或为 NULL。","explanation":"主键和唯一约束都可能帮助查询唯一性判断，但主键是实体标识，一个表只能有一个；唯一约束可以有多个。外键维护表间参照关系，并且要考虑插入、更新和删除时的违约处理。三者不能互相替代。"},{"id":"2-09","chapter":2,"chapterTitle":"第二章 完整性约束与数据库设计基础","number":9,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"数据库设计流程中，绘制 E-R 图属于（ ）。","options":["需求分析","概念结构设计","逻辑结构设计","物理结构设计"],"answer":["B"],"explanation":"需求分析的产物通常是需求说明、数据字典和数据流图；概念设计的产物是 E-R 图；逻辑设计把 E-R 图转换为关系模式；物理设计选择存储方式、索引和数据类型等实现细节。概念设计通常独立于具体 DBMS。"},{"id":"2-10","chapter":2,"chapterTitle":"第二章 完整性约束与数据库设计基础","number":10,"title":"填空题","kind":"open","answerKind":"open","typeName":"填空","stem":"数据库设计的五个常见阶段是需求分析、________、逻辑结构设计、物理结构设计和实施维护。","options":[],"answer":"概念结构设计","explanation":"五阶段可用“需求定要求，概念画 E-R；逻辑转关系，物理选存储；实施维护跑起来”记忆。不同教材也可能把实施和维护拆成两个阶段，形成六阶段，但此顺序不变。"},{"id":"2-11","chapter":2,"chapterTitle":"第二章 完整性约束与数据库设计基础","number":11,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"表示金额、工资等精确小数时，较合适的数据类型是（ ）。","options":["`FLOAT`","`REAL`","`DECIMAL(10,2)`","`CHAR(10)`"],"answer":["C"],"explanation":"`DECIMAL(p,s)` 用十进制精确表示，`DECIMAL(10,2)` 表示最多 10 位有效数字，其中 2 位小数，适合金额。`FLOAT` 和 `REAL` 是近似数值类型，可能产生精度误差；`CHAR(10)` 是固定长度字符串，不适合进行金额运算。"},{"id":"2-12","chapter":2,"chapterTitle":"第二章 完整性约束与数据库设计基础","number":12,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"字段 `Email VARCHAR(100)` 需要保存 Unicode 字符，在 SQL Server 中更合适的类型是（ ）。","options":["`CHAR(100)`","`NVARCHAR(100)`","`INT`","`DATE`"],"answer":["B"],"explanation":"SQL Server 中 `VARCHAR` 受排序规则和代码页影响，`NVARCHAR` 支持 Unicode。MySQL 通常用 `utf8mb4` 字符集支持中文和其他 Unicode 字符，不能机械照搬 SQL Server 的 `N` 类型。"},{"id":"2-13","chapter":2,"chapterTitle":"第二章 完整性约束与数据库设计基础","number":13,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"一个表的主键可以由多个列组成，这种主键称为复合主键。","options":[],"answer":"对","explanation":"例如选课表可用 `(StudentID, CourseID)` 作为复合主键，保证同一学生同一课程只有一条选课记录。复合主键中的每一列都不能为 NULL，并且组合值必须唯一；数据库仍只允许该表有一个主键约束。"},{"id":"2-14","chapter":2,"chapterTitle":"第二章 完整性约束与数据库设计基础","number":14,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"创建部门表 `Department` 和员工表 `Employee`，要求：\n\n1. 部门号 `DeptID` 为主键，部门名 `DeptName` 非空。\n2. 员工号 `EmpID` 为主键，姓名 `EmpName` 非空，工资 `Salary` 使用精确小数，部门号 `DeptID` 为外键。","options":[],"answer":"```sql\nCREATE TABLE Department (\n    DeptID INT PRIMARY KEY,\n    DeptName NVARCHAR(50) NOT NULL\n);\n\nCREATE TABLE Employee (\n    EmpID INT PRIMARY KEY,\n    EmpName NVARCHAR(50) NOT NULL,\n    Salary DECIMAL(10,2),\n    DeptID INT,\n    CONSTRAINT FK_Employee_Department\n        FOREIGN KEY (DeptID) REFERENCES Department(DeptID)\n);\n```","explanation":"先建父表 Department，再建子表 Employee。`CONSTRAINT` 后的名称是约束名，便于以后修改或删除。外键列和父表主键列应类型兼容，否则可能建表失败或产生隐式转换。"},{"id":"2-15","chapter":2,"chapterTitle":"第二章 完整性约束与数据库设计基础","number":15,"title":"简答题","kind":"open","answerKind":"open","typeName":"简答","stem":"概念结构设计和物理结构设计分别是否依赖具体 DBMS？","options":[],"answer":"概念结构设计通常不依赖具体 DBMS；物理结构设计依赖具体 DBMS。","explanation":"概念设计关注实体、属性和联系，形成 E-R 图，是业务信息的抽象；物理设计关注数据类型、索引、存储引擎、分区和文件组织等具体实现，不同 DBMS 的语法和性能特征不同。"},{"id":"2-16","chapter":2,"chapterTitle":"第二章 完整性约束与数据库设计基础","number":16,"title":"综合应用题","kind":"open","answerKind":"open","typeName":"综合题","stem":"某系统要保存员工身份证号、姓名、电话和所属部门。身份证号唯一且必填，员工可暂时未分配部门。请说明主键、唯一约束和外键分别应如何设置。","options":[],"answer":"可用员工号作为主键，身份证号设置唯一且非空；部门号作为外键，并允许为 NULL。","explanation":"如果业务已经规定身份证号是唯一标识，也可采用身份证号作为主键，但通常会用较短的员工号作为主键，以减少被外键引用时的存储开销。员工可暂时无部门，因此外键列不能设为 `NOT NULL`。身份证号“唯一且必填”应通过 `UNIQUE NOT NULL` 实现。"},{"id":"doc-142","chapter":2,"chapterTitle":"第二章 完整性约束与数据库设计基础","number":11,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"数据库的完整性是指数据库中的数据的全面性。","options":[],"answer":"错","explanation":"答案：错。数据库完整性不只指数据的“全面性”，而是要求数据正确、有效并满足完整性约束。","origin":"《数据库原理及应用》总复习"},{"id":"doc-143","chapter":2,"chapterTitle":"第二章 完整性约束与数据库设计基础","number":12,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"数据库完整性要求数据正确并保持相容。","options":[],"answer":"对","explanation":"答案：对。数据库完整性要求数据正确并保持相容，通常由实体、参照和用户定义完整性共同保证。","origin":"《数据库原理及应用》总复习"},{"id":"doc-144","chapter":2,"chapterTitle":"第二章 完整性约束与数据库设计基础","number":13,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"实体完整性和参照完整性是关系模型必须满足的完整性约束条件，称为两个不变性。","options":[],"answer":"对","explanation":"答案：对。实体完整性和参照完整性是关系模型必须满足的两个不变性。","origin":"《数据库原理及应用》总复习"},{"id":"doc-166","chapter":2,"chapterTitle":"第二章 完整性约束与数据库设计基础","number":35,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"关系模式存取方法的选择是其物理设计阶段的任务。","options":[],"answer":"对","explanation":"答案：对。存取方法和存储结构的选择属于物理结构设计。","origin":"《数据库原理及应用》总复习"},{"id":"doc-170","chapter":2,"chapterTitle":"第二章 完整性约束与数据库设计基础","number":39,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"数据库设计完成即可以交付用户使用，不需要进行试运行。","options":[],"answer":"错","explanation":"答案：错。数据库设计完成后还需实施、试运行、测试和评估，不能直接跳过试运行交付。","origin":"《数据库原理及应用》总复习"},{"id":"doc-053","chapter":2,"chapterTitle":"第二章 完整性约束与数据库设计基础","number":53,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"在数据库的物理结构中，将具有相同值的元组集中存放在连续的物理块称为（ ）存储方法。","options":["HASH","B+树索引","聚簇","其他"],"answer":["C"],"explanation":"正确答案：C。聚簇把具有相同或相近聚簇键值的元组集中存放在连续物理块中，提高相关查询效率。","origin":"《数据库原理及应用》总复习"},{"id":"doc-054","chapter":2,"chapterTitle":"第二章 完整性约束与数据库设计基础","number":54,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"数据库设计可划分为六个阶段，每个阶段都有自己的设计内容，“为哪些关系在哪些属性上建什么样的索引”这一设计内容应该属于（ ）设计阶段。","options":["概念设计","逻辑设计","物理设计","全局设计"],"answer":["C"],"explanation":"正确答案：C。为关系选择索引和存取路径属于物理结构设计。","origin":"《数据库原理及应用》总复习"},{"id":"doc-055","chapter":2,"chapterTitle":"第二章 完整性约束与数据库设计基础","number":55,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"存取方法设计是数据库设计的（ ）阶段的任务。","options":["需求分析","概念结构设计","逻辑结构设计","物理结构设计"],"answer":["D"],"explanation":"正确答案：D。存取方法设计包括索引、聚簇和文件组织，是物理设计阶段任务。","origin":"《数据库原理及应用》总复习"},{"id":"doc-056","chapter":2,"chapterTitle":"第二章 完整性约束与数据库设计基础","number":56,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"下列关于数据库运行和维护的叙述中，（ ）是正确的。","options":["只要数据库正式投入运行，标志着数据库设计工作的结束","数据库的维护工作就是维护数据库系统的正常运行","数据库的维护工作就是发现问题、修改问题","数据库正式投入运行标志着数据库运行和维护工作的开始"],"answer":["D"],"explanation":"正确答案：D。数据库投入运行后进入运行维护阶段，仍需监控、调优、备份、恢复和结构维护。","origin":"《数据库原理及应用》总复习"},{"id":"doc-069","chapter":2,"chapterTitle":"第二章 完整性约束与数据库设计基础","number":69,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"“学生-选课-课程”数据库中的3个关系：\nS(S#,SNAME,SEX,DEPARTMENT)，主码是S#；\nC(C#,CNAME,TEACHER)，主码是C#；\nSC(S#,C#,GRADE)，主码是(S#，C#)。\n在下列关于保持数据库完整性的叙述中，哪一个是不正确的？（ ）","options":["向关系SC插入元组时，S#和C#都不能是空值(NULL)","可以任意删除关系SC中的元组","向任何一个关系插入元组时，必须保证该关系主码值的唯一性","可以任意删除关系C中的元组"],"answer":["D"],"explanation":"正确答案：D。关系 C 的主键被 SC 外键引用，任意删除 C 中元组可能破坏参照完整性。","origin":"《数据库原理及应用》总复习"},{"id":"doc-123","chapter":2,"chapterTitle":"第二章 完整性约束与数据库设计基础","number":123,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"数据的完整性是指（ ）。","options":["数据的存储和使用数据的程序无关","防止数据被非法使用","数据的正确性、一致性","减少重复数据"],"answer":["C"],"explanation":"正确答案：C。数据库完整性要求数据正确、有效并保持相容，通常由实体、参照和用户定义完整性共同保证。","origin":"《数据库原理及应用》总复习"},{"id":"doc-125","chapter":2,"chapterTitle":"第二章 完整性约束与数据库设计基础","number":125,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"设属性A是关系R的主属性，则属性A不能取空值(NULL)，这是（ ）。","options":["参照完整性规则","用户定义完整性规则","关系完整性规则","实体完整性规则"],"answer":["D"],"explanation":"正确答案：D。主属性不能取空值属于实体完整性，用于保证主键能够唯一标识元组。","origin":"《数据库原理及应用》总复习"},{"id":"3-01","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":1,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"下列语句中属于 DDL 的是（ ）。","options":["`SELECT`","`INSERT`","`CREATE TABLE`","`GRANT`"],"answer":["C"],"explanation":"DDL 是数据定义语言，常见语句有 `CREATE`、`ALTER`、`DROP`、`TRUNCATE`。`SELECT` 属于 DQL，`INSERT` 属于 DML，`GRANT` 属于 DCL。`TRUNCATE` 在教材中有时归入 DDL，有时单独说明，应结合课程口径作答。"},{"id":"3-02","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":2,"title":"填空题","kind":"open","answerKind":"open","typeName":"填空","stem":"SQL 中用于控制事务的语句主要包括 `COMMIT`、`ROLLBACK` 和 `SAVEPOINT`，它们属于 ________ 语言。","options":[],"answer":"TCL（事务控制）","explanation":"TCL 表示 Transaction Control Language。`COMMIT` 提交事务，`ROLLBACK` 回滚事务，`SAVEPOINT` 设置可回滚的位置。不要把 `GRANT` 和 `REVOKE` 误归为 TCL，它们属于 DCL。"},{"id":"3-03","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":3,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"`SELECT` 属于数据操纵语言 DML，因为它会读取和操作数据库中的数据。","options":[],"answer":"错","explanation":"在大纲常用的分类中，`SELECT` 通常单独归为 DQL 数据查询语言；`INSERT`、`UPDATE`、`DELETE` 属于 DML。也有教材把查询视为 DML 的一部分，但应试时要优先采用题目教材的分类。若题目只给 DDL、DML、DCL 三类，则需依据该教材的约定。"},{"id":"3-04","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":4,"title":"多项选择题","kind":"choice","answerKind":"choice","typeName":"多项选择","stem":"下列语句属于 DCL 的是（ ）。","options":["`GRANT`","`REVOKE`","`COMMIT`","`CREATE USER`"],"answer":["A","B"],"explanation":"DCL 是数据控制语言，主要用于授予和回收权限，核心语句是 `GRANT` 和 `REVOKE`。`COMMIT` 属于 TCL；`CREATE USER` 用于创建数据库用户，通常属于 DDL 或安全管理的语句，不能仅凭名称归入 DCL。"},{"id":"3-05","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":5,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"创建数据库 `CompanyDB` 的正确语句是（ ）。","options":["`CREATE DATABASE CompanyDB;`","`CREATE TABLE CompanyDB;`","`INSERT DATABASE CompanyDB;`","`ALTER DATABASE CompanyDB CREATE;`"],"answer":["A"],"explanation":"创建数据库使用 `CREATE DATABASE 数据库名;`。创建表使用 `CREATE TABLE 表名 (...)`。数据库名不要与已经存在的对象重名；部分 DBMS 支持 `IF NOT EXISTS`，但 SQL Server 和 MySQL 的具体写法存在差异。"},{"id":"3-06","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":6,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"创建学生表 `Student`，包含：\n\n- `StudentID INT` 主键；\n- `StudentName NVARCHAR(50)` 非空；\n- `Gender CHAR(1)`；\n- `BirthDate DATE`；\n- `Score DECIMAL(5,2)`，取值范围 0 到 100。","options":[],"answer":"```sql\nCREATE TABLE Student (\n    StudentID INT PRIMARY KEY,\n    StudentName NVARCHAR(50) NOT NULL,\n    Gender CHAR(1),\n    BirthDate DATE,\n    Score DECIMAL(5,2),\n    CONSTRAINT CK_Student_Score\n        CHECK (Score BETWEEN 0 AND 100)\n);\n```","explanation":"`INT` 适合整数编号；`NVARCHAR` 适合 SQL Server 中的 Unicode 字符串；`DATE` 保存日期；`DECIMAL(5,2)` 最多 5 位，其中 2 位小数，可表示 0.00 至 999.99。`CHECK` 进一步限制成绩在合理范围内。"},{"id":"3-07","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":7,"title":"填空题","kind":"open","answerKind":"open","typeName":"填空","stem":"SQL Server 中，`DECIMAL(10,2)` 表示最多共 ________ 位，其中小数点后 ________ 位。","options":[],"answer":"10；2","explanation":"`DECIMAL(p,s)` 中 p 是总精度，s 是小数位数。整数部分可用的位数为 `p - s`。因此 `DECIMAL(10,2)` 的整数部分最多 8 位，小数部分最多 2 位。"},{"id":"3-08","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":8,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"金额字段使用 `FLOAT` 可以完全避免精度问题。","options":[],"answer":"错","explanation":"`FLOAT` 属于近似数值类型，二进制浮点表示可能产生舍入误差，不适合要求精确的财务金额。金额通常使用 `DECIMAL` 或 `NUMERIC`。如果必须使用浮点数，也需要在结算层面规定舍入规则和精度。"},{"id":"3-09","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":9,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"向 `Student` 表增加列 `Email NVARCHAR(100)`。","options":[],"answer":"```sql\nALTER TABLE Student\nADD Email NVARCHAR(100);\n```","explanation":"`ALTER TABLE ... ADD` 用于增加列。新列若要求非空，通常需要提供默认值，否则已有记录无法满足非空约束。增加列后还要考虑是否建立唯一约束、检查约束或索引。"},{"id":"3-10","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":10,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"在 SQL Server 中把 `Student.Email` 的长度改为 150。","options":[],"answer":"```sql\nALTER TABLE Student\nALTER COLUMN Email NVARCHAR(150);\n```","explanation":"SQL Server 修改列定义使用 `ALTER COLUMN`；MySQL 通常使用 `MODIFY COLUMN`。修改类型前要检查现有数据能否转换、是否有索引依赖该列、是否影响外键和应用程序。减小长度或改变类型可能导致数据截断或语句失败。"},{"id":"3-11","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":11,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"若要求某列在没有显式提供值时自动填入 `GETDATE()`，应使用（ ）约束。","options":["`PRIMARY KEY`","`FOREIGN KEY`","`DEFAULT`","`UNIQUE`"],"answer":["C"],"explanation":"`DEFAULT` 为未提供值的列指定默认表达式。主键用于唯一标识；外键用于参照；唯一约束用于防止重复。默认值并不等于“自动更新”，只有插入语句省略该列或显式使用默认值时才会生效。"},{"id":"3-12","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":12,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"创建订单明细表 `OrderDetail`，要求订单号 `OrderID` 和图书编号 `ISBN` 组成复合主键，数量 `Quantity` 必须大于 0。","options":[],"answer":"```sql\nCREATE TABLE OrderDetail (\n    OrderID INT NOT NULL,\n    ISBN NVARCHAR(20) NOT NULL,\n    Quantity INT NOT NULL,\n    CONSTRAINT PK_OrderDetail PRIMARY KEY (OrderID, ISBN),\n    CONSTRAINT CK_OrderDetail_Quantity CHECK (Quantity > 0)\n);\n```","explanation":"复合主键用一个表级 `PRIMARY KEY (OrderID, ISBN)` 声明。`OrderID` 和 `ISBN` 虽然已经在主键中隐含非空，但显式写 `NOT NULL` 更容易阅读。数量必须大于 0 属于用户定义完整性或域完整性。"},{"id":"3-13","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":13,"title":"多项选择题","kind":"choice","answerKind":"choice","typeName":"多项选择","stem":"下列属于常见列级或表级约束的是（ ）。","options":["`PRIMARY KEY`","`FOREIGN KEY`","`CHECK`","`ORDER BY`"],"answer":["A","B","C"],"explanation":"`ORDER BY` 是查询排序子句，不是约束。`NOT NULL`、`UNIQUE`、`DEFAULT` 也是常见约束或列属性。约束既可以写在列定义后，也可以作为表级约束统一定义，特别是复合主键和复合外键通常使用表级写法。"},{"id":"3-14","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":14,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"外键列的数据类型必须与父表被引用列完全同名，否则不能建立外键。","options":[],"answer":"错","explanation":"外键列名称不必与父表列名相同，但数据类型应当兼容，且父表被引用列必须具有主键或唯一约束。列名不同完全合法，例如 `Employee.DeptID` 引用 `Department.DeptID`，也可以通过别名或角色名体现业务含义。"},{"id":"3-15","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":15,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"一次向 `Department` 表插入两行：`(1, '计算机学院')` 和 `(2, '软件学院')`。","options":[],"answer":"```sql\nINSERT INTO Department (DeptID, DeptName)\nVALUES (1, N'计算机学院'),\n       (2, N'软件学院');\n```","explanation":"多行插入用逗号分隔多个值元组。SQL Server 中 `N'...'` 表示 Unicode 字符串；MySQL 通常直接使用普通字符串，并由字符集设置保证中文存储。插入子表数据前，父表中必须已有相应主键，否则会违反参照完整性。"},{"id":"3-16","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":16,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"把部门 1 的所有员工工资提高 5%。","options":[],"answer":"```sql\nUPDATE Employee\nSET Salary = Salary * 1.05\nWHERE DeptID = 1;\n```","explanation":"`UPDATE` 修改已有行，`SET` 指定新值，`WHERE` 限定修改范围。若漏写 `WHERE`，会修改整张表。实际执行前应先用人查询核对受影响行数，并注意事务、备份和工资精度要求。"},{"id":"3-17","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":17,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"`DELETE FROM Employee;` 会删除 Employee 表的结构，因此之后不能再向该表插入数据。","options":[],"answer":"错","explanation":"`DELETE FROM Employee;` 删除表中全部数据，但保留表结构。删除结构和数据的是 `DROP TABLE Employee;`。`TRUNCATE TABLE Employee;` 快速清空数据并保留结构，但它在事务、外键和自增重置方面的行为依 DBMS 而异。"},{"id":"3-18","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":18,"title":"简答题","kind":"open","answerKind":"open","typeName":"简答","stem":"比较 `DELETE`、`TRUNCATE` 和 `DROP` 的作用。","options":[],"answer":"`DELETE` 删除行，可带 `WHERE`，可回滚，通常会触发删除触发器；`TRUNCATE` 快速清空全部行并保留结构，通常不能按条件删除；`DROP` 删除表结构、数据和相关对象。","explanation":"具体行为依赖 DBMS。例如某些环境中 `TRUNCATE` 也会记录日志并可回滚，外键引用可能阻止清空。SQL Server 中 `TRUNCATE` 通常比逐行 `DELETE` 快，但不能直接用于被外键引用的表。考试应抓住“删行、清空、删对象”三个层次。"},{"id":"doc-219","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":8,"title":"SQL 应用题","kind":"open","answerKind":"open","typeName":"SQL 应用题","stem":"根据关系 Student(Sno, Sname, Sex, Age, City, Class)，创建 Student 表，并满足：\n- Sno 为主键；\n- Sex 默认值为“男”；\n- Age 必须大于 13。","options":[],"answer":"```sql\nCREATE TABLE Student (\n Sno CHAR(10) PRIMARY KEY,\n Sname VARCHAR(30) NOT NULL,\n Sex CHAR(2) DEFAULT '男',\n Age INT,\n City VARCHAR(50),\n Class VARCHAR(30),\n CONSTRAINT CK_Student_Age CHECK (Age > 13)\n);\n```","explanation":"PRIMARY KEY 同时保证学号非空且唯一；DEFAULT 指定性别默认值；CHECK 把年龄限制为大于 13。主键、默认值和检查约束分别对应实体完整性、用户定义完整性或域完整性。","origin":"《数据库原理及应用》总复习"},{"id":"doc-220","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":9,"title":"SQL 应用题","kind":"open","answerKind":"open","typeName":"SQL 应用题","stem":"删除 Course 表中由“李梅”老师负责授课的课程记录。Course 与 Teacher 通过 Tno 关联。","options":[],"answer":"```sql\nDELETE FROM Course\nWHERE Tno IN (\n SELECT Tno\n FROM Teacher\n WHERE Tname = '李梅'\n);\n```","explanation":"先用子查询找出李梅的教师号，再删除对应课程。使用 IN 而不是 =，因为姓名不一定唯一，李梅可能对应一个或多个教师号。删除前还需考虑 SC 等子表是否引用了这些课程。","origin":"《数据库原理及应用》总复习"},{"id":"doc-221","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":10,"title":"SQL 应用题","kind":"open","answerKind":"open","typeName":"SQL 应用题","stem":"将选修“数据库”课程的所有成绩增加 5 分。关系为 Course(Cno,Cname,...)、SC(Sno,Cno,Score)。","options":[],"answer":"```sql\nUPDATE SC\nSET Score = Score + 5\nWHERE Cno IN (\n SELECT Cno\n FROM Course\n WHERE Cname = '数据库'\n);\n```","explanation":"课程名在 Course，成绩在 SC，因此先按课程名找到课程号，再更新 SC。使用 IN 可处理同名课程对应多个课程号的情况；若业务要求加分后不超过 100，还应增加范围约束或 CASE 表达式。","origin":"《数据库原理及应用》总复习"},{"id":"doc-171","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":40,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"数据定义语言的缩写为DML。","options":[],"answer":"错","explanation":"答案：错。数据定义语言缩写为 DDL；DML 是数据操纵语言。","origin":"《数据库原理及应用》总复习"},{"id":"doc-172","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":41,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"在MySQL5.5以上系统中，默认的存储引擎是InnoDB。","options":[],"answer":"对","explanation":"答案：对。MySQL 5.5 起默认存储引擎为 InnoDB，支持事务、行锁和外键。","origin":"《数据库原理及应用》总复习"},{"id":"doc-173","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":42,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"在创建数据库时，每个数据库都对应存放在一个与数据库同名的文件夹中。","options":[],"answer":"对","explanation":"答案：对。在 MySQL 数据目录中，每个数据库通常对应一个同名文件夹。","origin":"《数据库原理及应用》总复习"},{"id":"doc-174","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":43,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"在创建表时，不能为其某个字段指定默认值。","options":[],"answer":"错","explanation":"答案：错。创建表时可以使用 DEFAULT 为字段指定默认值。","origin":"《数据库原理及应用》总复习"},{"id":"doc-175","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":44,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"在创建表时，可以设定某个字段的取值允许为空值（NULL)。","options":[],"answer":"对","explanation":"答案：对。字段默认允许 NULL，使用 NOT NULL 可以禁止空值。","origin":"《数据库原理及应用》总复习"},{"id":"doc-176","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":45,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"在创建表时，指定某字段为主键的关键字是FOREIGN KEY。","options":[],"answer":"错","explanation":"答案：错。指定主键使用 PRIMARY KEY；FOREIGN KEY 用于定义外键。","origin":"《数据库原理及应用》总复习"},{"id":"doc-177","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":46,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"在MySQL中，一旦某个表创建完成，它的结构就不能再更改。","options":[],"answer":"错","explanation":"答案：错。表结构创建后可通过 ALTER TABLE 增加、修改或删除列及约束。","origin":"《数据库原理及应用》总复习"},{"id":"doc-178","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":47,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"DROP TABLE 和 TRUNCATE TABLE 的作用相同。","options":[],"answer":"错","explanation":"答案：错。DROP TABLE 删除表结构和数据；TRUNCATE TABLE 只清空数据并保留表结构。","origin":"《数据库原理及应用》总复习"},{"id":"doc-179","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":48,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"在MySQL表中执行删除操作时，可以删除指定的记录，也可以删除表中所有的记录。","options":[],"answer":"对","explanation":"答案：对。DELETE 可配合 WHERE 删除指定行，省略 WHERE 时删除所有行。","origin":"《数据库原理及应用》总复习"},{"id":"doc-180","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":49,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"创建唯一性索引的列可以有一些重复的值。","options":[],"answer":"错","explanation":"答案：错。唯一索引要求索引键在非空值上不能重复，只允许按 DBMS 规则处理 NULL。","origin":"《数据库原理及应用》总复习"},{"id":"doc-057","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":57,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"下列选项中属于创建数据库的语句是（ ）。","options":["CREATE DATABASE","ALTER DATABASE","DROP DATABASE","以上都不是"],"answer":["A"],"explanation":"正确答案：A。CREATE DATABASE 用于创建数据库；ALTER 修改，DROP 删除。","origin":"《数据库原理及应用》总复习"},{"id":"doc-058","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":58,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"在 MySQL 中，每个数据库通常对应存放在一个与数据库同名的（ ）中。","options":["文件","文件夹","路径","以上都不是"],"answer":["B"],"explanation":"正确答案：B。在 MySQL 数据目录中，每个数据库通常对应一个与数据库同名的文件夹。","origin":"《数据库原理及应用》总复习"},{"id":"doc-059","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":59,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"显示当前所有数据库的命令是（ ）。","options":["SHOW DATABASES","SHOW DATABASE","LIST DATABASES","LIST DATABASE"],"answer":["A"],"explanation":"正确答案：A。MySQL 使用 SHOW DATABASES 查看当前服务器上的数据库列表。","origin":"《数据库原理及应用》总复习"},{"id":"doc-060","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":60,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"在MySQL5.5以上系统中，默认的存储引擎是（ ）。","options":["MyISAM","MEMORY","InnoDB","ARCHIVE"],"answer":["C"],"explanation":"正确答案：C。MySQL 5.5 起默认存储引擎为 InnoDB，支持事务、行锁和外键。","origin":"《数据库原理及应用》总复习"},{"id":"doc-061","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":61,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"在MySQL 8.0中，默认的MySQL服务的服务名称是（ ）。","options":["mysql","mysql57","mysql80","mysql8.0"],"answer":["C"],"explanation":"正确答案：C。Windows 版 MySQL 8.0 的默认服务名通常为 MySQL80。","origin":"《数据库原理及应用》总复习"},{"id":"doc-062","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":62,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"MySQL使用（ ）文件中的配置参数。","options":["my-larger.ini","my-small.ini","my-huge.ini","my.ini"],"answer":["D"],"explanation":"正确答案：D。MySQL 在 Windows 上常从 my.ini 读取服务器和客户端配置参数。","origin":"《数据库原理及应用》总复习"},{"id":"doc-063","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":63,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"下列选项中属于删除数据库的语句是（ ）。","options":["CREATE DATABASE","USE DATABASE","DROP DATABASE","以上都不"],"answer":["C"],"explanation":"正确答案：C。DROP DATABASE 用于删除整个数据库及其对象。","origin":"《数据库原理及应用》总复习"},{"id":"doc-064","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":64,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"选择要执行操作的数据库，应该哪个SQL命令？（ ）","options":["USE","GO","EXEC","DB"],"answer":["A"],"explanation":"正确答案：A。USE 数据库名 用于把已有数据库切换为当前数据库。","origin":"《数据库原理及应用》总复习"},{"id":"doc-292","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":69,"title":"数据更新","kind":"open","answerKind":"open","typeName":"数据更新","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n使用 SELECT INTO 或 CREATE TABLE AS SELECT 备份 student、sc、course 三个表。","options":[],"answer":"```sql\nCREATE TABLE student_bak AS SELECT * FROM student;\nCREATE TABLE sc_bak AS SELECT * FROM sc;\nCREATE TABLE course_bak AS SELECT * FROM course;\n```","explanation":"本题要求“使用 SELECT INTO 或 CREATE TABLE AS SELECT 备份 student、sc、course 三个表”。本题包含 3 条语句，应分别返回或修改对应对象；数据来源为 student、sc、course；使用 * 返回目标表的全部列。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-293","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":70,"title":"数据更新","kind":"open","answerKind":"open","typeName":"数据更新","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n向 student 表插入记录：学号 2005010203、姓名张静、女、1981-03-21、软件工程系、软件技术。","options":[],"answer":"```sql\nINSERT INTO student(sno, sname, ssex, sbirthday, sdept, speciality) VALUES ('2005010203', '张静', '女', '1981-03-21', '软件工程系', '软件技术');\n```","explanation":"本题要求“向 student 表插入记录：学号 2005010203、姓名张静、女、1981-03-21、软件工程系、软件技术”。本题属于数据更新，必须明确目标表、更新值和 WHERE 范围，避免误改整表。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-071","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":71,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"若要删除数据库中已经存在的表S，可用（ ）。","options":["DELETE TABLE S","DELETE S","DROP TABLE S","DROP S"],"answer":["C"],"explanation":"正确答案：C。删除表对象使用 DROP TABLE；DELETE 只删除表中的行。","origin":"《数据库原理及应用》总复习"},{"id":"doc-294","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":71,"title":"数据更新","kind":"open","answerKind":"open","typeName":"数据更新","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n插入学号为 2005010302、姓名为李四的学生信息。","options":[],"answer":"```sql\nINSERT INTO student(sno, sname) VALUES ('2005010302', '李四');\n```","explanation":"本题要求“插入学号为 2005010302、姓名为李四的学生信息”。本题属于数据更新，必须明确目标表、更新值和 WHERE 范围，避免误改整表。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-072","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":72,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"在下列SQL语句中，修改表结构的语句是（ ）。","options":["ALTER","CREATE","UPDATE","INSERT"],"answer":["A"],"explanation":"正确答案：A。ALTER 用于修改表结构，CREATE 创建对象，UPDATE 和 INSERT 操作数据。","origin":"《数据库原理及应用》总复习"},{"id":"doc-295","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":72,"title":"数据更新","kind":"open","answerKind":"open","typeName":"数据更新","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n把计算机工程系的学生记录保存到结构相同的 TS 表中。","options":[],"answer":"```sql\nINSERT INTO TS SELECT * FROM student WHERE sdept = '计算机工程系';\n```","explanation":"本题要求“把计算机工程系的学生记录保存到结构相同的 TS 表中”。数据来源为 student；使用 * 返回目标表的全部列；WHERE 条件负责在分组或排序前筛选行：sdept = '计算机工程系'；本题属于数据更新，必须明确目标表、更新值和 WHERE 范围，避免误改整表。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-296","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":73,"title":"数据更新","kind":"open","answerKind":"open","typeName":"数据更新","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n将学号 2005010202 的学生姓名改为张华，系别改为电子工程系，专业改为电子应用技术。","options":[],"answer":"```sql\nUPDATE student SET sname = '张华', sdept = '电子工程系', speciality = '电子应用技术' WHERE sno = '2005010202';\n```","explanation":"本题要求“将学号 2005010202 的学生姓名改为张华，系别改为电子工程系，专业改为电子应用技术”。WHERE 条件负责在分组或排序前筛选行：sno = '2005010202'；本题属于数据更新，必须明确目标表、更新值和 WHERE 范围，避免误改整表。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-297","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":74,"title":"数据更新","kind":"open","answerKind":"open","typeName":"数据更新","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n将“李勇”同学的专业改为计算机信息管理。","options":[],"answer":"```sql\nUPDATE student SET speciality = '计算机信息管理' WHERE sname = '李勇';\n```","explanation":"本题要求“将“李勇”同学的专业改为计算机信息管理”。WHERE 条件负责在分组或排序前筛选行：sname = '李勇'；本题属于数据更新，必须明确目标表、更新值和 WHERE 范围，避免误改整表。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-298","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":75,"title":"数据更新","kind":"open","answerKind":"open","typeName":"数据更新","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n删除学号为 2005010302 的学生记录。","options":[],"answer":"```sql\nDELETE FROM student WHERE sno = '2005010302';\n```","explanation":"本题要求“删除学号为 2005010302 的学生记录”。数据来源为 student；WHERE 条件负责在分组或排序前筛选行：sno = '2005010302'；本题属于数据更新，必须明确目标表、更新值和 WHERE 范围，避免误改整表。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-299","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":76,"title":"数据更新","kind":"open","answerKind":"open","typeName":"数据更新","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n删除计算机工程系所有学生的选课记录。","options":[],"answer":"```sql\nDELETE FROM sc WHERE sno IN (SELECT sno FROM student WHERE sdept = '计算机工程系');\n```","explanation":"本题要求“删除计算机工程系所有学生的选课记录”。数据来源为 sc、student；SELECT 列表为 sno；WHERE 条件负责在分组或排序前筛选行：sno IN (SELECT sno FROM student WHERE sdept = '计算机工程系')；子查询先给出候选集合、极值或存在性判断，外层查询再据此筛选；本题属于数据更新，必须明确目标表、更新值和 WHERE 范围，避免误改整表。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-300","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":77,"title":"数据更新","kind":"open","answerKind":"open","typeName":"数据更新","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n删除 sc 表中尚无成绩的选课记录。","options":[],"answer":"```sql\nDELETE FROM sc WHERE degree IS NULL;\n```","explanation":"本题要求“删除 sc 表中尚无成绩的选课记录”。数据来源为 sc；WHERE 条件负责在分组或排序前筛选行：degree IS NULL；本题属于数据更新，必须明确目标表、更新值和 WHERE 范围，避免误改整表。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-301","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":78,"title":"数据更新","kind":"open","answerKind":"open","typeName":"数据更新","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n删除“刘晨”同学的全部选修记录。","options":[],"answer":"```sql\nDELETE FROM sc WHERE sno IN (SELECT sno FROM student WHERE sname = '刘晨');\n```","explanation":"本题要求“删除“刘晨”同学的全部选修记录”。数据来源为 sc、student；SELECT 列表为 sno；WHERE 条件负责在分组或排序前筛选行：sno IN (SELECT sno FROM student WHERE sname = '刘晨')；子查询先给出候选集合、极值或存在性判断，外层查询再据此筛选；本题属于数据更新，必须明确目标表、更新值和 WHERE 范围，避免误改整表。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-092","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":92,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"如下面的数据库的表所示，若职工表的主关键字是职工号，部门表的主关键字是部门号，SQL操作（ ）不能执行。","options":["从职工表中删除行('025'，'王芳'，'03'，7200)","将行('005'，'乔兴'， '04'，7200)插入到职工表中","将职工号为'001'的工资改为7000","将职工号为'038'的部门号改为'03'"],"answer":["B"],"explanation":"正确答案：B。职工号 005 已存在，插入新行会违反主键唯一性，因此该操作不能执行。","origin":"《数据库原理及应用》总复习"},{"id":"doc-093","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":93,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"若用如下的SQL语句创建了一个表SC：\nCREATE TABLE SC\n（S# CHAR（6） NOT NULL，\nC# CHAR（3） NOT NULL，\nSCORE INTEGER，\nNOTE CHAR（20））；\n向SC表插入如下行时，（ ）行可以被插入 。","options":["('201009','111',60)","('200823','101',NULL,NULL)","(NULL,'103',80,'选修')","('201132',NULL,86,' ')"],"answer":["B"],"explanation":"正确答案：B。只有 B 的列数正确且两个 NOT NULL 列都提供了非空值；其他选项缺列或违反非空约束。","origin":"《数据库原理及应用》总复习"},{"id":"doc-094","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":94,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"若用如下的SQL语句创建一个STUDENT表。\nCREATE TABLE STUDENT\n(NO char(4) NOT NULL,\nNAME char(8) NOT NULL,\nSEX char(2),\nAGE int)\n可以插入到STUDENT表中的是（ ）。","options":["(1031,'曾华','男',23)","('1031','曾华',NULL,NULL)","(NULL,'曾华','男','23')","('1031',NULL,'男',23)"],"answer":["B"],"explanation":"正确答案：B。NO 与 NAME 为 NOT NULL；B 提供非空值，允许其他可空字段为 NULL。","origin":"《数据库原理及应用》总复习"},{"id":"doc-095","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":95,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"设关系数据库中一个表S的结构为S（SN，CN，grade），其中SN为学生名，CN为课程名，二者均为字符型；grade为成绩，数值型，取值范围0－100。若要把“张二的化学成绩80分”插入S中，则可用（ ）。","options":["ADD INTO S VALUES（'张二','化学','80'）","INSERT INTO S VALUES（'张二','化学','80'）","ADD INTO S VALUES（'张二','化学',80）","INSERT INTO S VALUES（'张二','化学',80）"],"answer":["D"],"explanation":"正确答案：D。插入整行使用 INSERT INTO ... VALUES；字符串加引号，数值成绩不加引号。","origin":"《数据库原理及应用》总复习"},{"id":"doc-318","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":95,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n如何从备份表恢复 student、sc、course 三个表？","options":[],"answer":"清空目标表后，使用 INSERT INTO 目标表 SELECT * FROM 备份表 恢复数据；表结构丢失时需先按原结构重建。","explanation":"恢复前应关闭外键检查或按父表到子表顺序恢复，完成后再开启检查。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-096","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":96,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"设关系数据库中有一个表S的关系模式为S(SN,CN,GRADE)，其中SN为学生名，CN为课程名，二者为字符型；GRADE为成绩，数值型，取值范围0～100。若要更正“王二”的化学成绩为85分，则可用（ ）。","options":["UPDATE S SET GRADE=85 WHERE SN='王二' AND CN='化学'","UPDATE S SET GRADE='85' WHERE SN='王二' AND CN='化学'","UPDATE GRADE=85 WHERE SN='王二' AND CN='化学'","UPDATE GRADE='85' WHERE SN='王二' AND CN='化学'"],"answer":["A"],"explanation":"正确答案：A。修改数据使用 UPDATE ... SET ... WHERE；成绩为数值类型，应赋值为 85。","origin":"《数据库原理及应用》总复习"},{"id":"doc-319","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":96,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\nDROP 与 DELETE 的本质区别是什么？","options":[],"answer":"DROP TABLE 删除表结构和数据；DELETE FROM 只删除表中记录并保留表结构。","explanation":"TRUNCATE TABLE 也会保留结构，但通常不能按条件删除，并与 DELETE 的事务和触发器行为不同。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-097","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":97,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"SQL语言的数据操作语句包括SELECT、INSERT、UPDATE和DELETE等。其中最重要的，也是使用最频繁的语句是（ ）。","options":["SELECT","INSERT","UPDATE","DELETE"],"answer":["A"],"explanation":"正确答案：A。SELECT 是查询语句，也是最常用、最重要的 SQL 数据操作语句。","origin":"《数据库原理及应用》总复习"},{"id":"doc-320","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":97,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\nINSERT、UPDATE、DELETE 能否同时对多个表操作？","options":[],"answer":"一次 INSERT 只能写入一个目标表；MySQL 支持多表 UPDATE 和多表 DELETE。涉及多表的一致性操作建议放在事务中。","explanation":"不同 DBMS 对多表 DML 语法支持不同，应按题目指定的数据库作答。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-098","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":98,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"SQL语言集数据查询、数据操纵、数据定义和数据控制功能于一体，其中，CREATE、DROP、ALTER语句是实现哪种功能（ ）。","options":["数据查询","数据操纵","数据定义","数据控制"],"answer":["C"],"explanation":"正确答案：C。CREATE、DROP、ALTER 属于 DDL，用于定义和修改数据库对象。","origin":"《数据库原理及应用》总复习"},{"id":"doc-129","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":129,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"SQL语言又称为（ ）。","options":["结构化定义语言","结构化控制语言","结构化查询语言","结构化操纵语言"],"answer":["C"],"explanation":"正确答案：C。SQL 的英文全称是 Structured Query Language，即结构化查询语言。","origin":"《数据库原理及应用》总复习"},{"id":"doc-130","chapter":3,"chapterTitle":"第三章 SQL 基础与数据定义","number":130,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"在MySQL中，通常用来指定一个已有数据库作为当前数据库的语句是（ ）。","options":["USING","USED","USE","USER"],"answer":["C"],"explanation":"正确答案：C。USE 数据库名 用于切换当前数据库。","origin":"《数据库原理及应用》总复习"},{"id":"4-01","chapter":4,"chapterTitle":"第四章 单表查询","number":1,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"单表查询中，用于筛选满足条件的行的子句是（ ）。","options":["`SELECT`","`FROM`","`WHERE`","`ORDER BY`"],"answer":["C"],"explanation":"`SELECT` 指定要返回的列或表达式；`FROM` 指定数据来源；`WHERE` 筛选分组前的行；`ORDER BY` 对最终结果排序。关系代数中的选择对应 SQL 的 `WHERE`，投影主要对应 `SELECT` 列列表。"},{"id":"4-02","chapter":4,"chapterTitle":"第四章 单表查询","number":2,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询 Employee 表中所有员工的员工号、姓名和工资。","options":[],"answer":"```sql\nSELECT EmpID, EmpName, Salary\nFROM Employee;\n```","explanation":"正式查询应明确写出所需列，避免使用 `SELECT *` 返回无关字段。明确列名可以减少网络传输、降低表结构变化对程序的影响，也有助于覆盖索引优化。题目若要求“所有信息”，才考虑 `SELECT *`。"},{"id":"4-03","chapter":4,"chapterTitle":"第四章 单表查询","number":3,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询员工姓名和工资，并把结果列显示为“姓名”和“月工资”。","options":[],"answer":"```sql\nSELECT EmpName AS 姓名,\n       Salary AS 月工资\nFROM Employee;\n```","explanation":"`AS` 为列设置别名。含中文或空格的别名在不同 DBMS 中可能需要引号或方括号。别名主要影响结果集显示，不改变原表列名。`WHERE` 通常不能直接使用 SELECT 中定义的别名，因为逻辑执行顺序中 `WHERE` 早于 `SELECT`。"},{"id":"4-04","chapter":4,"chapterTitle":"第四章 单表查询","number":4,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"`SELECT *` 总能获得比明确列名更好的查询性能。","options":[],"answer":"错","explanation":"`SELECT *` 可能返回不需要的列，增加 I/O 和网络传输，并妨碍覆盖索引。它还使应用程序依赖表的列顺序和全部结构，一旦新增列可能产生兼容问题。只在检查数据或确实需要全部列时使用。"},{"id":"4-05","chapter":4,"chapterTitle":"第四章 单表查询","number":5,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"`SELECT DISTINCT DeptID, Gender FROM Employee;` 的去重对象是（ ）。","options":["只对 DeptID 去重","只对 Gender 去重","对 `(DeptID, Gender)` 整个组合去重","对 Employee 表的所有列去重"],"answer":["C"],"explanation":"`DISTINCT` 作用于整个 SELECT 结果行，不是只作用于最后一列。若 `(1, '男')` 出现多次只保留一行，但 `(1, '男')` 与 `(1, '女')` 属于不同组合，都会保留。"},{"id":"4-06","chapter":4,"chapterTitle":"第四章 单表查询","number":6,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询工资不低于 8000 且部门号不等于 3 的员工。","options":[],"answer":"```sql\nSELECT *\nFROM Employee\nWHERE Salary >= 8000\n  AND DeptID <> 3;\n```","explanation":"`>=` 表示包含等于，`<>` 表示不等于。若 DeptID 为 NULL，`DeptID <> 3` 的结果为未知而不是真，因此该行不会被返回。涉及 NULL 的业务条件要单独考虑。"},{"id":"4-07","chapter":4,"chapterTitle":"第四章 单表查询","number":7,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"条件 `Salary <> NULL` 可以找出工资列不为空的员工。","options":[],"answer":"错","explanation":"NULL 表示未知或缺失，任何普通比较 `= NULL`、`<> NULL` 通常都得到 UNKNOWN，不会筛选出结果。判断空值必须使用 `IS NULL` 或 `IS NOT NULL`。例如查询工资未知的员工应写 `WHERE Salary IS NULL`。"},{"id":"4-08","chapter":4,"chapterTitle":"第四章 单表查询","number":8,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询工资在 5000 到 10000 之间（包含端点）的员工姓名和工资。","options":[],"answer":"```sql\nSELECT EmpName, Salary\nFROM Employee\nWHERE Salary BETWEEN 5000 AND 10000;\n```","explanation":"`BETWEEN a AND b` 通常等价于 `>= a AND <= b`，包含端点。若工资为 NULL，则不满足范围条件。日期范围使用 BETWEEN 时要注意日期列是否包含时间部分，例如 `2026-01-01 12:00` 不属于只到 `2026-01-01 00:00` 的区间条件。"},{"id":"4-09","chapter":4,"chapterTitle":"第四章 单表查询","number":9,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询部门号为 1、2 或 5 的员工。","options":[],"answer":"```sql\nSELECT *\nFROM Employee\nWHERE DeptID IN (1, 2, 5);\n```","explanation":"`IN` 适合多值等值判断，可读性通常优于多个 `OR`。若候选集合来自子查询，也常用 `IN (子查询)`。注意 `NOT IN` 的子查询如果返回 NULL，可能使整个条件无法得到预期结果，实际业务中常改用 `NOT EXISTS`。"},{"id":"4-10","chapter":4,"chapterTitle":"第四章 单表查询","number":10,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询姓“张”的所有员工姓名。","options":[],"answer":"```sql\nSELECT EmpName\nFROM Employee\nWHERE EmpName LIKE N'张%';\n```","explanation":"`%` 表示任意长度字符序列，可以包含零个字符，因此 `张%` 匹配“张”以及以张开头的字符串。SQL Server 中 `N` 前缀用于 Unicode 字符串；MySQL 中通常直接写普通字符串，数据库字符集为 `utf8mb4` 时可保存中文。"},{"id":"4-11","chapter":4,"chapterTitle":"第四章 单表查询","number":11,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"模式 `N'李_'` 通常匹配（ ）。","options":["所有姓李的员工","以“李_”结尾的姓名","以“李”开头且后面恰好一个字符的姓名","只有“李”一个字"],"answer":["C"],"explanation":"下划线 `_` 表示恰好一个任意字符。若要匹配真正的下划线，需要使用转义字符。不同 DBMS 对转义语法略有差异，例如 SQL Server 可使用 `LIKE N'李\\_' ESCAPE '\\'`。"},{"id":"4-12","chapter":4,"chapterTitle":"第四章 单表查询","number":12,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询没有填写部门的员工姓名。","options":[],"answer":"```sql\nSELECT EmpName\nFROM Employee\nWHERE DeptID IS NULL;\n```","explanation":"“未填写”对应 NULL，应使用 `IS NULL`。空字符串 `''` 和 NULL 在数据库中不是同一概念；有的系统允许空字符串，有的系统或应用层会统一转成 NULL，所以业务层必须规定统一的缺失值规则。"},{"id":"4-13","chapter":4,"chapterTitle":"第四章 单表查询","number":13,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"条件 `WHERE DeptID = 1 OR DeptID = 2 AND Salary > 8000` 的等价写法通常是（ ）。","options":["`(DeptID = 1 OR DeptID = 2) AND Salary > 8000`","`DeptID = 1 OR (DeptID = 2 AND Salary > 8000)`","`(DeptID = 1 AND DeptID = 2) OR Salary > 8000`","`DeptID IN (1, 2) AND Salary > 8000`"],"answer":["B"],"explanation":"`AND` 的优先级通常高于 `OR`，所以原条件等价于 B。业务含义是“部门 1 的所有员工，或者部门 2 中工资大于 8000 的员工”。若想表达“部门 1 或 2 且工资都大于 8000”，必须显式加括号，如 A。"},{"id":"4-14","chapter":4,"chapterTitle":"第四章 单表查询","number":14,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"按工资降序排列员工；工资相同时按姓名升序排列。","options":[],"answer":"```sql\nSELECT EmpName, Salary\nFROM Employee\nORDER BY Salary DESC, EmpName ASC;\n```","explanation":"多列排序从左到右依次生效：先比较 Salary，只有 Salary 相等时才比较 EmpName。`ASC` 是默认值，可以不写，但考试中明确写出可以避免歧义。排序放在结果生成之后，因此可以使用 SELECT 中的别名。"},{"id":"4-15","chapter":4,"chapterTitle":"第四章 单表查询","number":15,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"在 SQL Server 中查询工资最高的前 5 名员工。","options":[],"answer":"```sql\nSELECT TOP 5 EmpName, Salary\nFROM Employee\nORDER BY Salary DESC;\n```","explanation":"`TOP` 必须和明确的排序规则配合，否则“前 5 行”没有稳定业务含义。MySQL 常写 `ORDER BY Salary DESC LIMIT 5`。如果存在工资并列，`TOP 5` 只按排序返回固定行数，不一定返回所有并列者。"},{"id":"4-16","chapter":4,"chapterTitle":"第四章 单表查询","number":16,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"在 MySQL 中查询第 11 至 20 条员工记录，按员工号升序。","options":[],"answer":"```sql\nSELECT *\nFROM Employee\nORDER BY EmpID\nLIMIT 10, 10;\n```","explanation":"MySQL 的 `LIMIT offset, count` 中 offset 从 0 开始。第 11 至 20 条需要跳过 10 条，再取 10 条。SQL Server 通常写 `ORDER BY EmpID OFFSET 10 ROWS FETCH NEXT 10 ROWS ONLY`。分页查询必须有稳定排序，否则页面之间可能重复或遗漏记录。"},{"id":"4-17","chapter":4,"chapterTitle":"第四章 单表查询","number":17,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询工资高于 8000、部门号不为空，并按工资从高到低排列的员工姓名、工资和部门号。","options":[],"answer":"```sql\nSELECT EmpName, Salary, DeptID\nFROM Employee\nWHERE Salary > 8000\n  AND DeptID IS NOT NULL\nORDER BY Salary DESC;\n```","explanation":"条件中同时包含普通比较和空值判断，使用 `AND` 连接。因为要求只返回部分列，因此不能写 `SELECT *`。排序只影响显示顺序，不改变表中记录的物理顺序。"},{"id":"4-18","chapter":4,"chapterTitle":"第四章 单表查询","number":18,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"在大多数标准 SQL 执行顺序中，`WHERE` 可以引用同一层 `SELECT` 中定义的别名。","options":[],"answer":"错","explanation":"逻辑执行顺序通常理解为 `FROM`、`WHERE`、`GROUP BY`、`HAVING`、`SELECT`、`DISTINCT`、`ORDER BY`。`WHERE` 在 `SELECT` 之前执行，因此通常不能引用 SELECT 别名；`ORDER BY` 在 SELECT 之后执行，通常可以使用别名。部分 DBMS 可能做语法扩展，但应试应按标准顺序理解。"},{"id":"4-19","chapter":4,"chapterTitle":"第四章 单表查询","number":19,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询 2026 年 1 月 1 日以后入职且姓名以“王”开头的员工。","options":[],"answer":"```sql\nSELECT EmpID, EmpName, HireDate\nFROM Employee\nWHERE HireDate >= '2026-01-01'\n  AND EmpName LIKE N'王%';\n```","explanation":"日期字面量通常用单引号包围。若 HireDate 为 DATETIME，`>= '2026-01-01'` 表示从该日零时起；若业务要求“1 月 1 日当天及以后”与“严格晚于某时刻”不同，应写明确时间。模式 `王%` 以王开头，可能使用相关索引，但 `%王` 这类前置通配通常不利于普通 B+ 树索引。"},{"id":"4-20","chapter":4,"chapterTitle":"第四章 单表查询","number":20,"title":"简答题","kind":"open","answerKind":"open","typeName":"简答","stem":"写出单表查询的答题步骤。","options":[],"answer":"先确定表和所需列，再写筛选条件，判断是否需要去重，最后按题目要求排序或限制行数并检查语法。","explanation":"可按“FROM 找表、SELECT 找列、WHERE 找条件、DISTINCT 看重复、ORDER BY 看顺序、TOP/LIMIT 看数量”完成。写完后还要检查：表名和列名是否与题目一致，字符串和日期是否加引号，NULL 是否使用 `IS NULL`，排序方向是否正确。"},{"id":"doc-224","chapter":4,"chapterTitle":"第四章 单表查询","number":1,"title":"单表查询","kind":"open","answerKind":"open","typeName":"单表查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询所有学生的基本信息、所有课程的基本信息和所有学生的成绩信息，用 3 条 SQL 语句完成。","options":[],"answer":"```sql\nSELECT * FROM student;\nSELECT * FROM course;\nSELECT * FROM sc;\n```","explanation":"本题要求“查询所有学生的基本信息、所有课程的基本信息和所有学生的成绩信息，用 3 条 SQL 语句完成”。本题包含 3 条语句，应分别返回或修改对应对象；数据来源为 student、course、sc；使用 * 返回目标表的全部列。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-225","chapter":4,"chapterTitle":"第四章 单表查询","number":2,"title":"单表查询","kind":"open","answerKind":"open","typeName":"单表查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询所有学生的学号、姓名、性别和出生日期。","options":[],"answer":"```sql\nSELECT sno, sname, ssex, sbirthday FROM student;\n```","explanation":"本题要求“查询所有学生的学号、姓名、性别和出生日期”。数据来源为 student；SELECT 列表为 sno, sname, ssex, sbirthday。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-226","chapter":4,"chapterTitle":"第四章 单表查询","number":3,"title":"单表查询","kind":"open","answerKind":"open","typeName":"单表查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询所有课程的课程名称。","options":[],"answer":"```sql\nSELECT cname FROM course;\n```","explanation":"本题要求“查询所有课程的课程名称”。数据来源为 course；SELECT 列表为 cname。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-227","chapter":4,"chapterTitle":"第四章 单表查询","number":4,"title":"单表查询","kind":"open","answerKind":"open","typeName":"单表查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询前 10 门课程的课程号及课程名称。","options":[],"answer":"```sql\nSELECT cno, cname FROM course ORDER BY cno LIMIT 10;\n```","explanation":"本题要求“查询前 10 门课程的课程号及课程名称”。数据来源为 course；SELECT 列表为 cno, cname；ORDER BY cno LIMIT 10; 只控制结果顺序。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-228","chapter":4,"chapterTitle":"第四章 单表查询","number":5,"title":"单表查询","kind":"open","answerKind":"open","typeName":"单表查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询所有学生的姓名及年龄。","options":[],"answer":"```sql\nSELECT sname, YEAR(CURDATE()) - YEAR(sbirthday) AS age FROM student;\n```","explanation":"本题要求“查询所有学生的姓名及年龄”。数据来源为 student；SELECT 列表为 sname, YEAR(CURDATE()) - YEAR(sbirthday) AS age。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-229","chapter":4,"chapterTitle":"第四章 单表查询","number":6,"title":"单表查询","kind":"open","answerKind":"open","typeName":"单表查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询所有年龄大于 18 岁的女生的学号和姓名。","options":[],"answer":"```sql\nSELECT sno, sname FROM student WHERE YEAR(CURDATE()) - YEAR(sbirthday) > 18 AND ssex = '女';\n```","explanation":"本题要求“查询所有年龄大于 18 岁的女生的学号和姓名”。数据来源为 student；SELECT 列表为 sno, sname；WHERE 条件负责在分组或排序前筛选行：YEAR(CURDATE()) - YEAR(sbirthday) > 18 AND ssex = '女'。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-230","chapter":4,"chapterTitle":"第四章 单表查询","number":7,"title":"单表查询","kind":"open","answerKind":"open","typeName":"单表查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询所有男生的信息。","options":[],"answer":"```sql\nSELECT * FROM student WHERE ssex = '男';\n```","explanation":"本题要求“查询所有男生的信息”。数据来源为 student；使用 * 返回目标表的全部列；WHERE 条件负责在分组或排序前筛选行：ssex = '男'。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-231","chapter":4,"chapterTitle":"第四章 单表查询","number":8,"title":"单表查询","kind":"open","answerKind":"open","typeName":"单表查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询所有任课教师的姓名和所在系别。","options":[],"answer":"```sql\nSELECT tname, sdept FROM teacher;\n```","explanation":"本题要求“查询所有任课教师的姓名和所在系别”。数据来源为 teacher；SELECT 列表为 tname, sdept。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-232","chapter":4,"chapterTitle":"第四章 单表查询","number":9,"title":"单表查询","kind":"open","answerKind":"open","typeName":"单表查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询“电子商务”专业学生的姓名、性别和出生日期。","options":[],"answer":"```sql\nSELECT sname, ssex, sbirthday FROM student WHERE speciality = '电子商务';\n```","explanation":"本题要求“查询“电子商务”专业学生的姓名、性别和出生日期”。数据来源为 student；SELECT 列表为 sname, ssex, sbirthday；WHERE 条件负责在分组或排序前筛选行：speciality = '电子商务'。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-233","chapter":4,"chapterTitle":"第四章 单表查询","number":10,"title":"单表查询","kind":"open","answerKind":"open","typeName":"单表查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询 student 表中的所有系名，并去除重复值。","options":[],"answer":"```sql\nSELECT DISTINCT sdept FROM student;\n```","explanation":"本题要求“查询 student 表中的所有系名，并去除重复值”。数据来源为 student；SELECT 列表为 DISTINCT sdept。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-234","chapter":4,"chapterTitle":"第四章 单表查询","number":11,"title":"单表查询","kind":"open","answerKind":"open","typeName":"单表查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询“C01”课程的开课学期。","options":[],"answer":"```sql\nSELECT cterm FROM teaching WHERE cno = 'C01';\n```","explanation":"本题要求“查询“C01”课程的开课学期”。数据来源为 teaching；SELECT 列表为 cterm；WHERE 条件负责在分组或排序前筛选行：cno = 'C01'。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-235","chapter":4,"chapterTitle":"第四章 单表查询","number":12,"title":"单表查询","kind":"open","answerKind":"open","typeName":"单表查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询成绩在 80～90 分的学生学号及课程号。","options":[],"answer":"```sql\nSELECT sno, cno FROM sc WHERE degree BETWEEN 80 AND 90;\n```","explanation":"本题要求“查询成绩在 80～90 分的学生学号及课程号”。数据来源为 sc；SELECT 列表为 sno, cno；WHERE 条件负责在分组或排序前筛选行：degree BETWEEN 80 AND 90。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-236","chapter":4,"chapterTitle":"第四章 单表查询","number":13,"title":"单表查询","kind":"open","answerKind":"open","typeName":"单表查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询在 1970 年 1 月 1 日之前出生的男教师信息。","options":[],"answer":"```sql\nSELECT * FROM teacher WHERE tbirthday < '1970-01-01' AND tsex = '男';\n```","explanation":"本题要求“查询在 1970 年 1 月 1 日之前出生的男教师信息”。数据来源为 teacher；使用 * 返回目标表的全部列；WHERE 条件负责在分组或排序前筛选行：tbirthday < '1970-01-01' AND tsex = '男'。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-237","chapter":4,"chapterTitle":"第四章 单表查询","number":14,"title":"单表查询","kind":"open","answerKind":"open","typeName":"单表查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n输出有成绩的学生学号。","options":[],"answer":"```sql\nSELECT DISTINCT sno FROM sc WHERE degree IS NOT NULL;\n```","explanation":"本题要求“输出有成绩的学生学号”。数据来源为 sc；SELECT 列表为 DISTINCT sno；WHERE 条件负责在分组或排序前筛选行：degree IS NOT NULL。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-238","chapter":4,"chapterTitle":"第四章 单表查询","number":15,"title":"单表查询","kind":"open","answerKind":"open","typeName":"单表查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询所有姓“刘”的学生信息。","options":[],"answer":"```sql\nSELECT * FROM student WHERE sname LIKE '刘%';\n```","explanation":"本题要求“查询所有姓“刘”的学生信息”。数据来源为 student；使用 * 返回目标表的全部列；WHERE 条件负责在分组或排序前筛选行：sname LIKE '刘%'；LIKE 中 % 表示任意长度字符，_ 表示单个字符，必要时使用 ESCAPE 转义。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-239","chapter":4,"chapterTitle":"第四章 单表查询","number":16,"title":"单表查询","kind":"open","answerKind":"open","typeName":"单表查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询生源地不是山东省的学生信息。","options":[],"answer":"```sql\nSELECT * FROM student WHERE saddress NOT LIKE '%山东%';\n```","explanation":"本题要求“查询生源地不是山东省的学生信息”。数据来源为 student；使用 * 返回目标表的全部列；WHERE 条件负责在分组或排序前筛选行：saddress NOT LIKE '%山东%'；LIKE 中 % 表示任意长度字符，_ 表示单个字符，必要时使用 ESCAPE 转义。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-240","chapter":4,"chapterTitle":"第四章 单表查询","number":17,"title":"单表查询","kind":"open","answerKind":"open","typeName":"单表查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询成绩为 79 分、89 分或 99 分的记录。","options":[],"answer":"```sql\nSELECT * FROM sc WHERE degree IN (79, 89, 99);\n```","explanation":"本题要求“查询成绩为 79 分、89 分或 99 分的记录”。数据来源为 sc；使用 * 返回目标表的全部列；WHERE 条件负责在分组或排序前筛选行：degree IN (79, 89, 99)；子查询先给出候选集合、极值或存在性判断，外层查询再据此筛选。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-241","chapter":4,"chapterTitle":"第四章 单表查询","number":18,"title":"单表查询","kind":"open","answerKind":"open","typeName":"单表查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询名字中第 2 个字是“小”的男生姓名和地址。","options":[],"answer":"```sql\nSELECT sname, saddress FROM student WHERE sname LIKE '_小%' AND ssex = '男';\n```","explanation":"本题要求“查询名字中第 2 个字是“小”的男生姓名和地址”。数据来源为 student；SELECT 列表为 sname, saddress；WHERE 条件负责在分组或排序前筛选行：sname LIKE '_小%' AND ssex = '男'；LIKE 中 % 表示任意长度字符，_ 表示单个字符，必要时使用 ESCAPE 转义。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-242","chapter":4,"chapterTitle":"第四章 单表查询","number":19,"title":"单表查询","kind":"open","answerKind":"open","typeName":"单表查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询名称以“计算机_”开头的课程名称，下划线按普通字符匹配。","options":[],"answer":"```sql\nSELECT cname FROM course WHERE cname LIKE '计算机\\_%' ESCAPE '\\';\n```","explanation":"本题要求“查询名称以“计算机_”开头的课程名称，下划线按普通字符匹配”。数据来源为 course；SELECT 列表为 cname；WHERE 条件负责在分组或排序前筛选行：cname LIKE '计算机\\_%' ESCAPE '\\'；LIKE 中 % 表示任意长度字符，_ 表示单个字符，必要时使用 ESCAPE 转义。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-243","chapter":4,"chapterTitle":"第四章 单表查询","number":20,"title":"单表查询","kind":"open","answerKind":"open","typeName":"单表查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询计算机工程系和软件工程系的学生信息。","options":[],"answer":"```sql\nSELECT * FROM student WHERE sdept IN ('计算机工程系', '软件工程系');\n```","explanation":"本题要求“查询计算机工程系和软件工程系的学生信息”。数据来源为 student；使用 * 返回目标表的全部列；WHERE 条件负责在分组或排序前筛选行：sdept IN ('计算机工程系', '软件工程系')；子查询先给出候选集合、极值或存在性判断，外层查询再据此筛选。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-068","chapter":4,"chapterTitle":"第四章 单表查询","number":68,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"在SQL中，下列涉及空值的操作，不正确的是（ ）。","options":["AGE IS NULL","AGE IS NOT NULL","AGE=NULL","NOT(AGE IS NULL)"],"answer":["C"],"explanation":"正确答案：C。NULL 不能用 = 判断，必须使用 IS NULL 或 IS NOT NULL。","origin":"《数据库原理及应用》总复习"},{"id":"doc-070","chapter":4,"chapterTitle":"第四章 单表查询","number":70,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"已知学生选课信息表：sc(sno,cno,grade)。查询“至少选修了一门课程，但没有学习成绩的学生学号和课程号”的SQL语句是（ ）。","options":["SELECT sno,cno FROM sc WHERE grade=NULL","SELECT sno,cno FROM sc WHERE grade IS ‘’","SELECT sno,cno FROM sc WHERE grade IS NULL","SELECT sno,cno FROM sc WHERE grade=’’"],"answer":["C"],"explanation":"正确答案：C。无成绩表示 grade 为 NULL，应使用 IS NULL；空字符串与 NULL 语义不同。","origin":"《数据库原理及应用》总复习"},{"id":"doc-073","chapter":4,"chapterTitle":"第四章 单表查询","number":73,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"SELECT语句中，（ ）子句用于选择满足给定条件的元组。","options":["WHERE","HAVING","GROUP BY","ORDER BY"],"answer":["A"],"explanation":"正确答案：A。WHERE 在分组前筛选满足条件的行；HAVING 筛选分组后的组。","origin":"《数据库原理及应用》总复习"},{"id":"doc-074","chapter":4,"chapterTitle":"第四章 单表查询","number":74,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"SELECT语句中，若希望将查询结果排序，则应在SELECT语句中使用（ ）子句。","options":["WHERE","HAVING","GROUP BY","ORDER BY"],"answer":["D"],"explanation":"正确答案：D。ORDER BY 用于对查询结果排序，可指定 ASC 或 DESC。","origin":"《数据库原理及应用》总复习"},{"id":"doc-075","chapter":4,"chapterTitle":"第四章 单表查询","number":75,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"设关系R(A,B,C)与SQL语句“SELECT DISTINCT A FROM R WHERE B=17”等价的关系代数表达式是（ ）。","options":["πA(σB=17(R))","σB=17(πA(R))","σB=17(πA,C(R))","πA,C(σB=17(R))"],"answer":["A"],"explanation":"正确答案：A。SQL 先按 B=17 选择行，再投影 A 并去重，对应 πA(σB=17(R))。","origin":"《数据库原理及应用》总复习"},{"id":"doc-076","chapter":4,"chapterTitle":"第四章 单表查询","number":76,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"“学生-选课-课程”数据库中：\nS(S#,SNAME,SEX,DEPARTMENT)，主码为 S#；\nC(C#,CNAME,TEACHER)，主码为 C#；\nSC(S#,C#,GRADE)，主码为（S#,C#）。\n\n查找姓“王”的学生学号和姓名，下列哪些写法正确？（ ）\n\nⅠ. SELECT S#,SNAME FROM S WHERE SNAME='王%'\nⅡ. SELECT S#,SNAME FROM S WHERE SNAME LIKE '王%'\nⅢ. SELECT S#,SNAME FROM S WHERE SNAME LIKE '王_'","options":["Ⅰ","Ⅱ","Ⅲ","全部"],"answer":["B"],"explanation":"正确答案：B。字符常量必须加引号；查找姓王的学生应写 SNAME LIKE '王%'，% 表示任意长度字符。","origin":"《数据库原理及应用》总复习"},{"id":"doc-077","chapter":4,"chapterTitle":"第四章 单表查询","number":77,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"在SQL语言中，条件“年龄 BETWEEN 20 AND 30”表示年龄在20～30之间，且（ ）。","options":["包括20岁和30岁","不包括20岁和30岁","包括20岁但不包括30岁","包括30岁但不包括20岁"],"answer":["A"],"explanation":"正确答案：A。BETWEEN 20 AND 30 等价于 age>=20 AND age<=30，包含两个端点。","origin":"《数据库原理及应用》总复习"},{"id":"doc-302","chapter":4,"chapterTitle":"第四章 单表查询","number":79,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\nLIKE 的通配符有哪些？分别代表什么含义？","options":[],"answer":"% 表示任意长度的字符序列；_ 表示任意一个字符。","explanation":"LIKE 用于字符串模式匹配。需要匹配真正的 % 或 _ 时，应使用 ESCAPE 指定转义字符。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-303","chapter":4,"chapterTitle":"第四章 单表查询","number":80,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n知道学生的出生日期，如何求出其年龄？","options":[],"answer":"可用当前年份减去出生年份，例如 YEAR(CURDATE()) - YEAR(sbirthday)；更精确的年龄还需比较月和日。","explanation":"YEAR 只比较年份，生日尚未到达时可能多算一岁。严格计算年龄应结合 DATE_FORMAT 或 TIMESTAMPDIFF。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-304","chapter":4,"chapterTitle":"第四章 单表查询","number":81,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n关键字 ALL 和 DISTINCT 有什么不同？","options":[],"answer":"ALL 保留查询结果中的重复行；DISTINCT 对结果行去重。","explanation":"DISTINCT 作用于整个 SELECT 结果行组合，不是只作用于最后一列。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-305","chapter":4,"chapterTitle":"第四章 单表查询","number":82,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\nIS 能用 = 代替来判断 NULL 吗？","options":[],"answer":"不能。判断空值应使用 IS NULL 或 IS NOT NULL。","explanation":"NULL 表示未知，使用 = NULL 得到 UNKNOWN，不会筛选出预期记录。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-306","chapter":4,"chapterTitle":"第四章 单表查询","number":83,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n除 BETWEEN … AND 外，还能用什么方法表示数据范围？","options":[],"answer":"可使用 >= 和 <= 组合，例如 age >= 20 AND age <= 30。","explanation":"BETWEEN 本身包含端点，改写为两个比较条件时应保留等于关系。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-088","chapter":4,"chapterTitle":"第四章 单表查询","number":88,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"有如下的SQL语句。\nⅠ. SELECT sname FROM s, sc WHERE grade<60\nⅡ. SELECT sname FROM s WHERE sno IN(SELECT sno FROM sc WHERE grade<60)\nⅢ. SELECT sname FROM s, sc WHERE s.sno=sc.sno AND grade<60\n若要查找分数(grade)不及格的学生姓名(sname)，则以上正确的有哪些？（ ）","options":["Ⅰ和Ⅱ","Ⅰ和Ⅲ","Ⅱ和Ⅲ","Ⅰ、Ⅱ和Ⅲ"],"answer":["C"],"explanation":"正确答案：C。Ⅱ使用子查询，Ⅲ包含连接条件，均正确；Ⅰ缺少 S 与 SC 的连接条件，会产生错误组合。","origin":"《数据库原理及应用》总复习"},{"id":"5-01","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":1,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"下列函数中，用于统计行数的是（ ）。","options":["`SUM`","`COUNT`","`AVG`","`MAX`"],"answer":["B"],"explanation":"`COUNT` 统计数据行数或某列非 NULL 值数量；`SUM` 求和；`AVG` 求平均；`MAX`、`MIN` 求最大值和最小值。聚合函数通常把多行压缩为一个汇总值，除非与 `GROUP BY` 一起使用。"},{"id":"5-02","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":2,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"表中有 10 行，列 `Bonus` 中有 3 行是 NULL。执行 `SELECT COUNT(*) FROM Employee;` 的结果是（ ）。","options":["3","7","10","NULL"],"answer":["C"],"explanation":"`COUNT(*)` 统计结果行数，不判断某列值是否为 NULL。因此即使 Bonus 有 NULL，仍然统计全部 10 行。若执行 `COUNT(Bonus)`，结果才是 7。这个差异在外连接统计中尤其重要。"},{"id":"5-03","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":3,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"承上题，执行 `SELECT COUNT(Bonus) FROM Employee;` 的结果是（ ）。","options":["3","7","10","NULL"],"answer":["B"],"explanation":"`COUNT(列名)` 只统计该列非 NULL 的行数。10 行中有 3 个 NULL，因此得到 7。进行左连接统计时，右表没有匹配会补 NULL，若要得到“0 个关联记录”的部门，应使用 `COUNT(右表.非空列)`，不要使用 `COUNT(*)`。"},{"id":"5-04","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":4,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"`SUM` 和 `AVG` 都会忽略输入为 NULL 的行。","options":[],"answer":"对","explanation":"聚合函数一般忽略 NULL。例如工资为 `[6000, NULL, 9000]`，`SUM(Salary)` 得 15000，`AVG(Salary)` 得 7500，而不是按 3 行平均得到的 5000。如果业务要求把 NULL 当 0，必须显式写 `COALESCE(Salary, 0)` 或 `IFNULL(Salary, 0)`。"},{"id":"5-05","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":5,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"统计员工总人数和平均工资。","options":[],"answer":"```sql\nSELECT COUNT(*) AS 员工人数,\n       AVG(Salary) AS 平均工资\nFROM Employee;\n```","explanation":"`COUNT(*)` 统计员工记录数，`AVG(Salary)` 只基于非 NULL 工资求平均。如果希望“没有工资记录也按 0 参与平均”，要明确业务规则并显式处理 NULL，否则两种平均口径会不同。"},{"id":"5-06","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":6,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"按部门统计员工人数。","options":[],"answer":"```sql\nSELECT DeptID, COUNT(*) AS 员工人数\nFROM Employee\nGROUP BY DeptID;\n```","explanation":"`GROUP BY DeptID` 把相同部门号的行归为一组，每组产生一行统计结果。SELECT 中只有分组列和聚合函数是稳定合法的；如果把 EmpName 等非分组普通列也写进 SELECT，在严格模式下会报错，在其他模式下可能得到不确定值。"},{"id":"5-07","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":7,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"`GROUP BY DeptID, Gender` 的结果是“每个部门一行”。","options":[],"answer":"错","explanation":"多列分组按 `(DeptID, Gender)` 的组合分组，“每个部门 + 性别”各得到一行。例如部门 1 有男、女两组，就会产生两行。多列分组时，只有这些组合相同才属于同一组。"},{"id":"5-08","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":8,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询平均工资高于 8000 的部门号及平均工资。","options":[],"answer":"```sql\nSELECT DeptID, AVG(Salary) AS AvgSalary\nFROM Employee\nGROUP BY DeptID\nHAVING AVG(Salary) > 8000;\n```","explanation":"平均工资属于分组后的聚合结果，不能用 `WHERE AVG(Salary) > 8000` 筛选，应使用 `HAVING`。`HAVING` 在分组后执行，可以引用聚合函数和分组列。"},{"id":"5-09","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":9,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"`WHERE` 和 `HAVING` 完全等价，可以任意互换。","options":[],"answer":"错","explanation":"`WHERE` 在分组前筛选原始行，通常不能使用聚合函数；`HAVING` 在分组后筛选组，可以使用聚合函数。原始列条件放在 WHERE 中通常更高效，因为能在分组前减少行数。分组列条件按逻辑也可以放在 HAVING，但能放 WHERE 时优先放 WHERE。"},{"id":"5-10","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":10,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询工资不低于 5000 的员工中，人数至少为 3 人的部门号和人数，并按人数从高到低排列。","options":[],"answer":"```sql\nSELECT DeptID, COUNT(*) AS 人数\nFROM Employee\nWHERE Salary >= 5000\nGROUP BY DeptID\nHAVING COUNT(*) >= 3\nORDER BY 人数 DESC;\n```","explanation":"SQL 处理顺序可理解为：先用 WHERE 筛掉工资低于 5000 的员工，再按部门分组，随后用 HAVING 保留人数至少 3 的组，最后排序。不要在 WHERE 中写 `COUNT(*) >= 3`。"},{"id":"5-11","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":11,"title":"填空题","kind":"open","answerKind":"open","typeName":"填空","stem":"聚合查询的常见逻辑执行顺序是：`FROM` → `WHERE` → `________` → `HAVING` → `SELECT` → `ORDER BY`。","options":[],"answer":"`GROUP BY`","explanation":"先确定数据来源，再筛选行，然后分组，再筛选组，之后生成 SELECT 列表并排序。实际优化器可能重排执行计划，但这一逻辑顺序有助于判断别名和聚合函数能否使用。"},{"id":"5-12","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":12,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询每个部门的最高工资、最低工资和平均工资。","options":[],"answer":"```sql\nSELECT DeptID,\n       MAX(Salary) AS MaxSalary,\n       MIN(Salary) AS MinSalary,\n       AVG(Salary) AS AvgSalary\nFROM Employee\nGROUP BY DeptID;\n```","explanation":"每个聚合函数独立计算同一组内的汇总值。若某部门所有工资均为 NULL，`MAX`、`MIN`、`AVG` 可能返回 NULL；若某部门没有员工，它根本不会出现在 Employee 表的分组结果中，需要从 Department 表出发做左连接。"},{"id":"5-13","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":13,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询每个部门的名称、员工人数和平均工资，并保留没有员工的部门。","options":[],"answer":"```sql\nSELECT d.DeptName,\n       COUNT(e.EmpID) AS 员工人数,\n       AVG(e.Salary) AS 平均工资\nFROM Department d\nLEFT JOIN Employee e\n  ON d.DeptID = e.DeptID\nGROUP BY d.DeptID, d.DeptName\nORDER BY 员工人数 DESC;\n```","explanation":"从 Department 出发做左连接，才能保留无员工的部门。对无匹配部门，`e.EmpID` 为 NULL，因此 `COUNT(e.EmpID)` 得到 0；如果写 `COUNT(*)`，由于左连接仍产生一行，会错误地统计为 1。平均工资此时为 NULL，可根据业务决定是否用 `COALESCE` 显示为 0。"},{"id":"5-14","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":14,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"`SELECT DeptID, EmpName, COUNT(*) FROM Employee GROUP BY DeptID;` 在所有严格 SQL 模式下都合法。","options":[],"answer":"错","explanation":"`EmpName` 既不是分组列，也不是聚合函数。一个部门有多个员工时，数据库无法确定应该显示哪一个姓名。MySQL 某些配置可能容忍这种写法并返回不确定值，但标准 SQL 和严格模式通常报错。应把姓名移除，或改用窗口函数、子查询等明确取一行的规则。"},{"id":"5-15","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":15,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"统计员工表中工资的最大值、最小值和平均值，不分组。","options":[],"answer":"```sql\nSELECT MAX(Salary) AS 最高工资,\n       MIN(Salary) AS 最低工资,\n       AVG(Salary) AS 平均工资\nFROM Employee;\n```","explanation":"没有 GROUP BY 时，整张表被视为一个组，产生一行汇总结果。即使表中没有行，不带 GROUP BY 的聚合查询通常仍返回一行，其中 COUNT 为 0，其他聚合可能为 NULL。具体结果取决于函数和 DBMS。"},{"id":"5-16","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":16,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询计算机学院中平均工资高于 7000 的部门号、平均工资和最高工资。","options":[],"answer":"```sql\nSELECT e.DeptID,\n       AVG(e.Salary) AS AvgSalary,\n       MAX(e.Salary) AS MaxSalary\nFROM Employee e\nJOIN Department d\n  ON e.DeptID = d.DeptID\nWHERE d.DeptName = N'计算机学院'\nGROUP BY e.DeptID\nHAVING AVG(e.Salary) > 7000;\n```","explanation":"部门名称条件属于原始行过滤，放在 WHERE；平均工资条件属于组过滤，放在 HAVING。因为结果需要部门号且题目限定一个学院，按 DeptID 分组更稳妥。实际系统可能按 DeptID 和 DeptName 共同分组，以防止同名部门造成语义歧义。"},{"id":"5-17","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":17,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"按部门和性别统计人数，只保留人数大于 2 的组合。","options":[],"answer":"```sql\nSELECT DeptID, Gender, COUNT(*) AS 人数\nFROM Employee\nGROUP BY DeptID, Gender\nHAVING COUNT(*) > 2\nORDER BY DeptID, Gender;\n```","explanation":"SELECT 中出现的两个普通列 DeptID、Gender 都必须出现在 GROUP BY 中。结果为每个“部门 + 性别”组合一行。HAVING 中使用 `COUNT(*)` 筛选组合，排序只影响输出顺序。"},{"id":"5-18","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":18,"title":"简答题","kind":"open","answerKind":"open","typeName":"简答","stem":"聚合查询写完后，应按哪些项目自检？","options":[],"answer":"检查聚合函数是否正确、SELECT 中普通列是否都在 GROUP BY 中、聚合条件是否放在 HAVING、原始行条件是否放在 WHERE、NULL 统计口径是否正确、排序别名和方向是否正确。","explanation":"高频错误包括：把 `COUNT(*)` 用在左连接统计、把聚合条件写进 WHERE、漏掉 GROUP BY 普通列、用 `SUM` 代替 `COUNT`、忽略 NULL 对 AVG 分母的影响。自检时应从业务语义出发，而不只是看 SQL 是否报错。"},{"id":"doc-244","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":21,"title":"聚合与分组","kind":"open","answerKind":"open","typeName":"聚合与分组","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n统计有学生选修的课程门数。","options":[],"answer":"```sql\nSELECT COUNT(DISTINCT cno) AS course_count FROM sc;\n```","explanation":"本题要求“统计有学生选修的课程门数”。数据来源为 sc；SELECT 列表为 COUNT(DISTINCT cno) AS course_count。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-245","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":22,"title":"聚合与分组","kind":"open","answerKind":"open","typeName":"聚合与分组","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n计算“C01”课程的平均成绩。","options":[],"answer":"```sql\nSELECT AVG(degree) AS avg_degree FROM sc WHERE cno = 'C01';\n```","explanation":"本题要求“计算“C01”课程的平均成绩”。数据来源为 sc；SELECT 列表为 AVG(degree) AS avg_degree；WHERE 条件负责在分组或排序前筛选行：cno = 'C01'。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-246","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":23,"title":"聚合与分组","kind":"open","answerKind":"open","typeName":"聚合与分组","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询选修“C03”课程的学生学号及成绩，按成绩降序排列。","options":[],"answer":"```sql\nSELECT sno, degree FROM sc WHERE cno = 'C03' ORDER BY degree DESC;\n```","explanation":"本题要求“查询选修“C03”课程的学生学号及成绩，按成绩降序排列”。数据来源为 sc；SELECT 列表为 sno, degree；WHERE 条件负责在分组或排序前筛选行：cno = 'C03'；ORDER BY degree DESC; 只控制结果顺序。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-247","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":24,"title":"聚合与分组","kind":"open","answerKind":"open","typeName":"聚合与分组","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询各个课程号及相应的选课人数。","options":[],"answer":"```sql\nSELECT cno, COUNT(*) AS student_count FROM sc GROUP BY cno;\n```","explanation":"本题要求“查询各个课程号及相应的选课人数”。数据来源为 sc；SELECT 列表为 cno, COUNT(*) AS student_count；按 cno; 分组，组内再使用聚合函数统计。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-248","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":25,"title":"聚合与分组","kind":"open","answerKind":"open","typeName":"聚合与分组","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n统计每门课程的选课人数和最高分。","options":[],"answer":"```sql\nSELECT cno, COUNT(*) AS student_count, MAX(degree) AS max_degree FROM sc GROUP BY cno;\n```","explanation":"本题要求“统计每门课程的选课人数和最高分”。数据来源为 sc；SELECT 列表为 cno, COUNT(*) AS student_count, MAX(degree) AS max_degree；按 cno; 分组，组内再使用聚合函数统计。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-249","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":26,"title":"聚合与分组","kind":"open","answerKind":"open","typeName":"聚合与分组","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n统计每个学生的选课门数和考试总成绩，并按选课门数降序排列。","options":[],"answer":"```sql\nSELECT sno, COUNT(*) AS course_count, SUM(degree) AS total_degree FROM sc GROUP BY sno ORDER BY course_count DESC;\n```","explanation":"本题要求“统计每个学生的选课门数和考试总成绩，并按选课门数降序排列”。数据来源为 sc；SELECT 列表为 sno, COUNT(*) AS course_count, SUM(degree) AS total_degree；按 sno 分组，组内再使用聚合函数统计；ORDER BY course_count DESC; 只控制结果顺序。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-250","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":27,"title":"聚合与分组","kind":"open","answerKind":"open","typeName":"聚合与分组","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询选修了 3 门以上课程的学生学号。","options":[],"answer":"```sql\nSELECT sno FROM sc GROUP BY sno HAVING COUNT(*) > 3;\n```","explanation":"本题要求“查询选修了 3 门以上课程的学生学号”。数据来源为 sc；SELECT 列表为 sno；按 sno 分组，组内再使用聚合函数统计；HAVING 在分组后保留满足 COUNT(*) > 3; 的组。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-251","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":28,"title":"聚合与分组","kind":"open","answerKind":"open","typeName":"聚合与分组","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询成绩不及格的学生学号及课程号，并按成绩降序排列。","options":[],"answer":"```sql\nSELECT sno, cno, degree FROM sc WHERE degree < 60 ORDER BY degree DESC;\n```","explanation":"本题要求“查询成绩不及格的学生学号及课程号，并按成绩降序排列”。数据来源为 sc；SELECT 列表为 sno, cno, degree；WHERE 条件负责在分组或排序前筛选行：degree < 60；ORDER BY degree DESC; 只控制结果顺序。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-252","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":29,"title":"聚合与分组","kind":"open","answerKind":"open","typeName":"聚合与分组","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询至少选修一门课程的学生学号。","options":[],"answer":"```sql\nSELECT DISTINCT sno FROM sc;\n```","explanation":"本题要求“查询至少选修一门课程的学生学号”。数据来源为 sc；SELECT 列表为 DISTINCT sno。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-253","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":30,"title":"聚合与分组","kind":"open","answerKind":"open","typeName":"聚合与分组","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n统计各系学生人数。","options":[],"answer":"```sql\nSELECT sdept, COUNT(*) AS student_count FROM student GROUP BY sdept;\n```","explanation":"本题要求“统计各系学生人数”。数据来源为 student；SELECT 列表为 sdept, COUNT(*) AS student_count；按 sdept; 分组，组内再使用聚合函数统计。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-254","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":31,"title":"聚合与分组","kind":"open","answerKind":"open","typeName":"聚合与分组","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n统计各系的男、女生人数。","options":[],"answer":"```sql\nSELECT sdept, ssex, COUNT(*) AS student_count FROM student GROUP BY sdept, ssex;\n```","explanation":"本题要求“统计各系的男、女生人数”。数据来源为 student；SELECT 列表为 sdept, ssex, COUNT(*) AS student_count；按 sdept, ssex; 分组，组内再使用聚合函数统计。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-255","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":32,"title":"聚合与分组","kind":"open","answerKind":"open","typeName":"聚合与分组","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n统计各班级学生人数。","options":[],"answer":"```sql\nSELECT classno, COUNT(*) AS student_count FROM student GROUP BY classno;\n```","explanation":"本题要求“统计各班级学生人数”。数据来源为 student；SELECT 列表为 classno, COUNT(*) AS student_count；按 classno; 分组，组内再使用聚合函数统计。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-256","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":33,"title":"聚合与分组","kind":"open","answerKind":"open","typeName":"聚合与分组","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n统计各班男、女生人数。","options":[],"answer":"```sql\nSELECT classno, ssex, COUNT(*) AS student_count FROM student GROUP BY classno, ssex;\n```","explanation":"本题要求“统计各班男、女生人数”。数据来源为 student；SELECT 列表为 classno, ssex, COUNT(*) AS student_count；按 classno, ssex; 分组，组内再使用聚合函数统计。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-257","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":34,"title":"聚合与分组","kind":"open","answerKind":"open","typeName":"聚合与分组","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n统计各系教师人数，并按人数降序排列。","options":[],"answer":"```sql\nSELECT sdept, COUNT(*) AS teacher_count FROM teacher GROUP BY sdept ORDER BY teacher_count DESC;\n```","explanation":"本题要求“统计各系教师人数，并按人数降序排列”。数据来源为 teacher；SELECT 列表为 sdept, COUNT(*) AS teacher_count；按 sdept 分组，组内再使用聚合函数统计；ORDER BY teacher_count DESC; 只控制结果顺序。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-258","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":35,"title":"聚合与分组","kind":"open","answerKind":"open","typeName":"聚合与分组","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n统计不及格人数超过 10 人的课程号。","options":[],"answer":"```sql\nSELECT cno, COUNT(*) AS fail_count FROM sc WHERE degree < 60 GROUP BY cno HAVING COUNT(*) > 10;\n```","explanation":"本题要求“统计不及格人数超过 10 人的课程号”。数据来源为 sc；SELECT 列表为 cno, COUNT(*) AS fail_count；WHERE 条件负责在分组或排序前筛选行：degree < 60；按 cno 分组，组内再使用聚合函数统计；HAVING 在分组后保留满足 COUNT(*) > 10; 的组。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-259","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":36,"title":"聚合与分组","kind":"open","answerKind":"open","typeName":"聚合与分组","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询软件工程系的男生信息，按出生日期升序排列；出生日期相同时按地址降序排列。","options":[],"answer":"```sql\nSELECT * FROM student WHERE sdept = '软件工程系' AND ssex = '男' ORDER BY sbirthday ASC, saddress DESC;\n```","explanation":"本题要求“查询软件工程系的男生信息，按出生日期升序排列；出生日期相同时按地址降序排列”。数据来源为 student；使用 * 返回目标表的全部列；WHERE 条件负责在分组或排序前筛选行：sdept = '软件工程系' AND ssex = '男'；ORDER BY sbirthday ASC, saddress DESC; 只控制结果顺序。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-066","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":66,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"基于这样的3个表，即学生表S、课程表C和学生选课表SC，它们的关系模式如下：S(S#，SN，SEX，AGE，DEPT)(学号，姓名，性别，年龄，系别)C(C#，CN)(课程号，课程名称)SC(S#，C#，GRADE)(学号，课程号，成绩).检索选修4门以上课程的学生总成绩(不统计不及格的课程)，并要求按总成绩的降序排列出来。正确的SELECT语句是（ ）。","options":["SELECT S#,SUM(GRAGE) FROM SC WHERE GRADE>=60 GROUP BY S# ORDER BY S# HAVING COUNT(*)>=4","SELECT S#,SUM(GRADE) FROM SC WHERE GRADE>=60 GROUP BY S# HAVING COUNT(*)>=4 ORDER BY 2 DESC","SELECT S#,SUM(GRADE) FROM SC WHERE GRADE>=60 HAVING COUNT(*)<=4 GROUP BY S# ORDER BY 2 DESC","SELECT S#,SUM(GRADE) FROM SC WHERE GRADE>=60 HAVING COUNT(*)>=4 GROUP BY S# ORDER BY 2"],"answer":["B"],"explanation":"正确答案：B。先筛选及格课程，再按学生分组，HAVING 保留门数至少 4 的组，最后按总成绩降序排列。","origin":"《数据库原理及应用》总复习"},{"id":"doc-067","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":67,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"下列聚合函数不忽略空值(NULL)的是（ ）。","options":["SUM(列名)","MAX(列名)","COUNT(*)","AVG(列名)"],"answer":["C"],"explanation":"正确答案：C。COUNT(*) 统计行数，不检查某列是否为 NULL；其他聚合函数都忽略 NULL。","origin":"《数据库原理及应用》总复习"},{"id":"doc-078","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":78,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"“学生-选课-课程”数据库中的3个关系：\nS(S#,SNAME,SEX,DEPARTMENT)，主码是S#；\nC(C#,CNAME,TEACHER)，主码是C#；\nSC(S#,C#,GRADE)，主码是(S#，C#)。\n若要“查询选修了3门以上课程的学生的学号”，则正确的SQL语句是（ ）。","options":["SELECT S# FROM SC GROUP BY S# WHERE COUNT(*)> 3","SELECT S# FROM SC GROUP BY S# HAVING COUNT(*)> 3","SELECT S# FROM SC ORDER BY S# WHERE COUNT(*)> 3","SELECT S# FROM SC ORDER BY S# HAVING COUNT(*)> 3"],"answer":["B"],"explanation":"正确答案：B。分组后的聚合条件必须放在 HAVING 中，WHERE 不能直接使用 COUNT(*)。","origin":"《数据库原理及应用》总复习"},{"id":"doc-079","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":79,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"SELECT语句中，使用（ ）子句可按指定列的值分组。","options":["WHERE","HAVING","GROUP BY","ORDER BY"],"answer":["C"],"explanation":"正确答案：C。GROUP BY 按指定列或列组合分组，每组产生一行汇总结果。","origin":"《数据库原理及应用》总复习"},{"id":"doc-080","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":80,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"SELECT语句中，使用GROUP BY子句可按指定列的值分组，同时使用（ ）可提取满足条件的组。","options":["WHERE","HAVING","GROUP BY","ORDER BY"],"answer":["B"],"explanation":"正确答案：B。HAVING 用于分组后筛选组，可使用 COUNT、SUM、AVG 等聚合函数。","origin":"《数据库原理及应用》总复习"},{"id":"doc-307","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":84,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n聚合函数能否用于 SELECT、HAVING、WHERE 和 GROUP BY 子句？","options":[],"answer":"可用于 SELECT 和 HAVING；WHERE 中不能直接使用聚合函数；GROUP BY 通常按普通列分组，不把聚合函数作为分组列。","explanation":"WHERE 在分组前执行，聚合结果尚未产生；HAVING 在分组后执行，可筛选聚合值。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-308","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":85,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\nWHERE 与 HAVING 有何区别？","options":[],"answer":"WHERE 在分组前筛选原始行，HAVING 在分组后筛选结果组。","explanation":"原始列条件应尽量放 WHERE，以减少参与分组的数据量；聚合条件必须放 HAVING。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-309","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":86,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n排序时是否必须明确指定 ASC 或 DESC？","options":[],"answer":"不必须。省略排序方向时通常默认 ASC。","explanation":"正式答题或要求可读性时，显式写出 ASC 或 DESC 更稳妥。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-310","chapter":5,"chapterTitle":"第五章 聚合、分组与排序","number":87,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n分组统计时可以按多个字段分组吗？","options":[],"answer":"可以。GROUP BY 可列出一个或多个分组字段，按字段组合形成分组。","explanation":"多列分组时，SELECT 中出现的普通列都必须包含在 GROUP BY 中。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"6-01","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":1,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"查询员工姓名和部门名称时需要连接 Employee 与 Department 两表。若只返回两表中连接条件匹配的记录，应使用（ ）。","options":["`CROSS JOIN`","`INNER JOIN`","`LEFT JOIN`，并以 Employee 为左表","`UNION`"],"answer":["B"],"explanation":"内连接只返回连接条件为真的匹配行。左连接会保留左表全部行；交叉连接无条件组合；`UNION` 合并两个结果集，不用于按主外键横向组合列。连接条件通常是 `e.DeptID = d.DeptID`。"},{"id":"6-02","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":2,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询所有员工姓名及其部门名称，只要求显示有匹配部门的员工。","options":[],"answer":"```sql\nSELECT e.EmpName, d.DeptName\nFROM Employee e\nINNER JOIN Department d\n  ON e.DeptID = d.DeptID;\n```","explanation":"表别名 e、d 用于简化列引用。`ON` 后面的连接条件决定两表如何匹配。员工 DeptID 为 NULL 或引用了不存在的部门时，该员工不会出现在内连接结果中。"},{"id":"6-03","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":3,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询部门名称及员工姓名，要求保留所有部门；没有员工的部门也要显示。","options":[],"answer":"```sql\nSELECT d.DeptName, e.EmpName\nFROM Department d\nLEFT JOIN Employee e\n  ON d.DeptID = e.DeptID;\n```","explanation":"Department 是左表，LEFT JOIN 保留左表全部行。无员工的部门仍出现一行，右侧 `e.EmpName` 为 NULL。实际展示可用 `COALESCE(e.EmpName, N'无员工')`，但这是显示层处理，不改变连接语义。"},{"id":"6-04","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":4,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"以下哪种连接会保留右表全部记录，即使左表没有匹配行？","options":["`INNER JOIN`","`LEFT JOIN`","`RIGHT JOIN`","`CROSS JOIN`"],"answer":["C"],"explanation":"RIGHT JOIN 以右表为保留侧。实际书写时可以把两表交换后改用 LEFT JOIN，通常更容易阅读。外连接必须有明确的保留侧和连接条件，否则结果可能与业务预期相反。"},{"id":"6-05","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":5,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"MySQL 可以直接执行 `FULL OUTER JOIN` 得到两表全部保留行。","options":[],"answer":"错","explanation":"MySQL 不直接支持 `FULL OUTER JOIN`，常用 `LEFT JOIN ... UNION ... RIGHT JOIN ...` 模拟。SQL Server 支持 `FULL OUTER JOIN`。应试要先根据题目指定的 DBMS 选择语法。"},{"id":"6-06","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":6,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询计算机学院的员工姓名和工资。分别说明 `ON` 与 `WHERE` 在普通内连接中的作用。","options":[],"answer":"```sql\nSELECT e.EmpName, e.Salary\nFROM Employee e\nJOIN Department d\n  ON e.DeptID = d.DeptID\nWHERE d.DeptName = N'计算机学院';\n```\n\n`ON` 描述两表如何匹配；`WHERE` 过滤连接后满足业务条件的行。","explanation":"在内连接中，把部门名称条件放在 ON 或 WHERE 往往都能得到相同结果，但语义不同。外连接中差异很大：右表过滤条件放在 WHERE 可能排除外连接补出的 NULL 行，从而把外连接效果退化为内连接。"},{"id":"6-07","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":7,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"忘记写连接条件时，两表连接通常会产生笛卡尔积。","options":[],"answer":"对","explanation":"若没有有效的连接条件，每个左表行都可能与每个右表行组合，结果行数为两表行数之积，通常会产生大量错误或重复结果。`CROSS JOIN` 是有意使用这种组合；普通业务连接不应遗漏 ON 条件。"},{"id":"6-08","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":8,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询客户姓名、订单号和订单中的图书编号，涉及 Customer、Orders、OrderDetail 三表。","options":[],"answer":"```sql\nSELECT c.CustomerName, o.OrderID, od.ISBN\nFROM Customer c\nJOIN Orders o\n  ON c.CustomerID = o.CustomerID\nJOIN OrderDetail od\n  ON o.OrderID = od.OrderID;\n```","explanation":"三表连接应沿外键链逐级连接：客户主键对应订单外键，订单主键对应订单明细外键。每一对连接都需要明确条件。若某订单没有明细，内连接不会返回该订单；若需保留订单，应改写为以 Orders 为保留侧的左连接。"},{"id":"6-09","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":9,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"Employee 表中有 EmpID 和 ManagerID，ManagerID 引用本表 EmpID。查询员工姓名及其上级姓名。","options":[],"answer":"```sql\nSELECT e.EmpName AS 员工姓名,\n       m.EmpName AS 上级姓名\nFROM Employee e\nLEFT JOIN Employee m\n  ON e.ManagerID = m.EmpID;\n```","explanation":"同一个 Employee 表需要取两个角色，因此分别使用别名 e 和 m，这是自连接。用 LEFT JOIN 可以保留没有上级的最高负责人。自连接必须用别名区分同一张表的两个逻辑角色，否则列引用无法区分。"},{"id":"6-10","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":10,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"`FROM Employee CROSS JOIN Department` 的结果是（ ）。","options":["只返回匹配记录","员工行数和部门行数之和","两表行的全部组合","只返回两表列名相同的记录"],"answer":["C"],"explanation":"交叉连接生成两表行的笛卡尔积。若 Employee 有 m 行，Department 有 n 行，结果为 m × n 行，属性数为两表属性数之和。若之后写 `WHERE e.DeptID = d.DeptID`，其效果类似内连接，但显式 JOIN 写法更清晰。"},{"id":"6-11","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":11,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"子查询 `(SELECT AVG(Salary) FROM Employee)` 只返回一个值，这种子查询属于（ ）。","options":["标量子查询","列子查询","行子查询","表子查询"],"answer":["A"],"explanation":"标量子查询返回一行一列，可用于 `=`、`>` 等单值比较。列子查询返回一列多行，常与 `IN`、`ANY`、`ALL` 搭配；行子查询返回一行多列；表子查询返回多行多列，常用于 FROM 子句的派生表。"},{"id":"6-12","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":12,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询工资高于全公司平均工资的员工姓名和工资。","options":[],"answer":"```sql\nSELECT EmpName, Salary\nFROM Employee\nWHERE Salary > (\n    SELECT AVG(Salary)\n    FROM Employee\n);\n```","explanation":"内层子查询先计算全公司平均工资，外层再筛选高于该平均值的人。若 Salary 为 NULL，不满足比较条件。若平均工资为 NULL，外层也不会返回记录，这在空表或全部工资为空时需要特别注意。"},{"id":"6-13","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":13,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询计算机学院的所有员工。","options":[],"answer":"```sql\nSELECT *\nFROM Employee\nWHERE DeptID IN (\n    SELECT DeptID\n    FROM Department\n    WHERE DeptName = N'计算机学院'\n);\n```","explanation":"内层返回一个或多个部门号，外层用 IN 判断员工属于哪些部门。若业务保证学院名称唯一，也可以使用等号标量子查询；使用 IN 对潜在的多行结果更稳妥。实际查询也可直接用 JOIN 完成。"},{"id":"6-14","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":14,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询工资最高的员工姓名和工资，要求使用子查询。","options":[],"answer":"```sql\nSELECT EmpName, Salary\nFROM Employee\nWHERE Salary = (\n    SELECT MAX(Salary)\n    FROM Employee\n);\n```","explanation":"使用 MAX 能返回所有并列最高工资的员工，而 `TOP 1` 只返回排序后的第一行。若工资允许 NULL，且表中存在 NULL，`MAX` 仍忽略 NULL；如果所有工资都为 NULL，条件为未知，外层无结果。"},{"id":"6-15","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":15,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"当子查询结果可能包含 NULL 时，下列写法最容易产生“查不到任何结果”风险的是（ ）。","options":["`EXISTS (子查询)`","`NOT EXISTS (子查询)`","`IN (子查询)`","`NOT IN (子查询)`"],"answer":["D"],"explanation":"`NOT IN` 与含 NULL 的集合比较时，比较结果可能为 UNKNOWN，从而过滤掉全部行。业务中查询“没有某关联”时，优先使用 `NOT EXISTS` 或先排除 NULL。`IN` 对 NULL 的处理也可能产生未知比较，但通常不会像 NOT IN 那样导致整张结果意外为空。"},{"id":"6-16","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":16,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询至少拥有一名员工的部门名称，要求使用 EXISTS。","options":[],"answer":"```sql\nSELECT d.DeptName\nFROM Department d\nWHERE EXISTS (\n    SELECT 1\n    FROM Employee e\n    WHERE e.DeptID = d.DeptID\n);\n```","explanation":"子查询中引用外层 `d.DeptID`，因此是相关子查询。EXISTS 只关心是否存在匹配行，SELECT 列表写 `1`、`*` 或某列通常不影响存在性判断。数据库优化器可能把 EXISTS 改写为半连接。"},{"id":"6-17","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":17,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询没有任何员工的部门名称。","options":[],"answer":"```sql\nSELECT d.DeptName\nFROM Department d\nWHERE NOT EXISTS (\n    SELECT 1\n    FROM Employee e\n    WHERE e.DeptID = d.DeptID\n);\n```","explanation":"对外层每个部门检查内层是否存在员工。若不存在，整个 EXISTS 为假，NOT EXISTS 为真。也可以用 LEFT JOIN 后判断右表主键 IS NULL，但 NOT EXISTS 语义直接，且通常能较好地利用索引。"},{"id":"6-18","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":18,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"相关子查询与外层查询完全独立，不能引用外层查询的列。","options":[],"answer":"错","explanation":"非相关子查询通常可以独立执行一次，再把结果交给外层；相关子查询引用外层列，逻辑上外层每一行都可能需要计算一次内层条件。数据库优化器可能采用缓存、半连接或反连接等策略，但语义上仍是相关的。"},{"id":"6-19","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":19,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"`UNION` 与 `UNION ALL` 的主要区别是（ ）。","options":["`UNION` 要求列数相同，`UNION ALL` 不要求","`UNION` 自动去重，`UNION ALL` 保留重复行","`UNION` 只能合并两张表，`UNION ALL` 可以合并多张表","`UNION` 自动排序，`UNION ALL` 不能排序"],"answer":["B"],"explanation":"两者都要求参与合并的查询列数相同、对应列类型兼容。`UNION` 要额外做去重，通常成本更高；`UNION ALL` 直接拼接结果，保留重复行，性能往往更好。若要稳定输出顺序，仍需显式写 `ORDER BY`。"},{"id":"6-20","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":20,"title":"综合编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询每个部门的名称、员工人数和平均工资，要求保留没有员工的部门，并按平均工资降序排列。","options":[],"answer":"```sql\nSELECT d.DeptName,\n       COUNT(e.EmpID) AS 员工人数,\n       AVG(e.Salary) AS 平均工资\nFROM Department d\nLEFT JOIN Employee e\n  ON d.DeptID = e.DeptID\nGROUP BY d.DeptID, d.DeptName\nORDER BY 平均工资 DESC;\n```","explanation":"从 Department 出发做 LEFT JOIN，保留无员工部门；`COUNT(e.EmpID)` 对无匹配组得到 0；AVG 对无工资组得到 NULL。按平均工资降序时，各 DBMS 对 NULL 的排序位置可能不同，若要求空部门排最后，应显式增加排序规则。SELECT 中的非聚合列都放入 GROUP BY。"},{"id":"doc-222","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":11,"title":"SQL 综合题","kind":"open","answerKind":"open","typeName":"SQL 综合题","stem":"查询考试平均成绩高于全体学生平均成绩的学生学号、姓名和平均成绩。关系为 Student(Sno,Sname,...)、SC(Sno,Cno,Score)。","options":[],"answer":"```sql\nSELECT S.Sno,\n S.Sname,\n AVG(SC.Score) AS AvgScore\nFROM Student AS S\nJOIN SC ON S.Sno = SC.Sno\nGROUP BY S.Sno, S.Sname\nHAVING AVG(SC.Score) > (\n SELECT AVG(Score)\n FROM SC\n);\n```","explanation":"内层子查询计算全体选课成绩的平均值；外层按学生分组求个人平均分，并在 HAVING 中与总平均分比较。AVG 忽略 NULL，若课程成绩为 NULL 需要按业务确定统计口径。","origin":"《数据库原理及应用》总复习"},{"id":"doc-223","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":12,"title":"SQL 综合题","kind":"open","answerKind":"open","typeName":"SQL 综合题","stem":"查询与教师李梅籍贯相同的学生学号、姓名和籍贯。关系为 Student(Sno,Sname,City,...)、Teacher(Tno,Tname,City)。","options":[],"answer":"```sql\nSELECT S.Sno, S.Sname, S.City\nFROM Student AS S\nJOIN Teacher AS T\n ON S.City = T.City\nWHERE T.Tname = '李梅';\n```","explanation":"按 City 相等连接学生和教师，再筛选李梅。若存在重名教师或空籍贯，应按实际业务使用教师号、去重或排除 NULL。城市相同的多个李梅会放大结果，必要时可改为 IN 子查询。","origin":"《数据库原理及应用》总复习"},{"id":"doc-260","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":37,"title":"多表连接","kind":"open","answerKind":"open","typeName":"多表连接","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询计算机工程系女学生的学号、姓名及考试成绩。","options":[],"answer":"```sql\nSELECT a.sno, a.sname, b.degree FROM student AS a JOIN sc AS b ON a.sno = b.sno WHERE a.sdept = '计算机工程系' AND a.ssex = '女';\n```","explanation":"本题要求“查询计算机工程系女学生的学号、姓名及考试成绩”。数据来源为 student、sc；SELECT 列表为 a.sno, a.sname, b.degree；WHERE 条件负责在分组或排序前筛选行：a.sdept = '计算机工程系' AND a.ssex = '女'。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-261","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":38,"title":"多表连接","kind":"open","answerKind":"open","typeName":"多表连接","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询“李勇”同学所选课程的成绩。","options":[],"answer":"```sql\nSELECT sc.cno, sc.degree FROM student AS s JOIN sc ON s.sno = sc.sno WHERE s.sname = '李勇';\n```","explanation":"本题要求“查询“李勇”同学所选课程的成绩”。数据来源为 student、sc；SELECT 列表为 sc.cno, sc.degree；WHERE 条件负责在分组或排序前筛选行：s.sname = '李勇'。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-262","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":39,"title":"多表连接","kind":"open","answerKind":"open","typeName":"多表连接","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询“李新”老师所授课程的课程名称。","options":[],"answer":"```sql\nSELECT DISTINCT c.cname FROM teacher AS t JOIN teaching AS tt ON t.tno = tt.tno JOIN course AS c ON tt.cno = c.cno WHERE t.tname = '李新';\n```","explanation":"本题要求“查询“李新”老师所授课程的课程名称”。数据来源为 teacher、teaching、course；SELECT 列表为 DISTINCT c.cname；WHERE 条件负责在分组或排序前筛选行：t.tname = '李新'。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-263","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":40,"title":"多表连接","kind":"open","answerKind":"open","typeName":"多表连接","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询女教师所授课程的课程号及课程名称。","options":[],"answer":"```sql\nSELECT DISTINCT c.cno, c.cname FROM teacher AS t JOIN teaching AS tt ON t.tno = tt.tno JOIN course AS c ON tt.cno = c.cno WHERE t.tsex = '女';\n```","explanation":"本题要求“查询女教师所授课程的课程号及课程名称”。数据来源为 teacher、teaching、course；SELECT 列表为 DISTINCT c.cno, c.cname；WHERE 条件负责在分组或排序前筛选行：t.tsex = '女'。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-264","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":41,"title":"多表连接","kind":"open","answerKind":"open","typeName":"多表连接","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询至少选修一门课程的女学生姓名。","options":[],"answer":"```sql\nSELECT DISTINCT s.sname FROM student AS s JOIN sc ON s.sno = sc.sno WHERE s.ssex = '女';\n```","explanation":"本题要求“查询至少选修一门课程的女学生姓名”。数据来源为 student、sc；SELECT 列表为 DISTINCT s.sname；WHERE 条件负责在分组或排序前筛选行：s.ssex = '女'。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-265","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":42,"title":"多表连接","kind":"open","answerKind":"open","typeName":"多表连接","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询姓“王”的学生所学的课程名称。","options":[],"answer":"```sql\nSELECT DISTINCT c.cname FROM student AS s JOIN sc ON s.sno = sc.sno JOIN course AS c ON sc.cno = c.cno WHERE s.sname LIKE '王%';\n```","explanation":"本题要求“查询姓“王”的学生所学的课程名称”。数据来源为 student、sc、course；SELECT 列表为 DISTINCT c.cname；WHERE 条件负责在分组或排序前筛选行：s.sname LIKE '王%'；LIKE 中 % 表示任意长度字符，_ 表示单个字符，必要时使用 ESCAPE 转义。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-266","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":43,"title":"多表连接","kind":"open","answerKind":"open","typeName":"多表连接","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询选修“数据库”课程且成绩在 80～90 分的学生学号及成绩。","options":[],"answer":"```sql\nSELECT sc.sno, sc.degree FROM sc JOIN course AS c ON sc.cno = c.cno WHERE c.cname = '数据库' AND sc.degree BETWEEN 80 AND 90;\n```","explanation":"本题要求“查询选修“数据库”课程且成绩在 80～90 分的学生学号及成绩”。数据来源为 sc、course；SELECT 列表为 sc.sno, sc.degree；WHERE 条件负责在分组或排序前筛选行：c.cname = '数据库' AND sc.degree BETWEEN 80 AND 90。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-267","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":44,"title":"多表连接","kind":"open","answerKind":"open","typeName":"多表连接","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询课程成绩及格的男学生信息及课程号、成绩。","options":[],"answer":"```sql\nSELECT s.*, sc.cno, sc.degree FROM student AS s JOIN sc ON s.sno = sc.sno WHERE s.ssex = '男' AND sc.degree >= 60;\n```","explanation":"本题要求“查询课程成绩及格的男学生信息及课程号、成绩”。数据来源为 student、sc；SELECT 列表为 s.*, sc.cno, sc.degree；WHERE 条件负责在分组或排序前筛选行：s.ssex = '男' AND sc.degree >= 60。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-268","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":45,"title":"多表连接","kind":"open","answerKind":"open","typeName":"多表连接","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询选修“C04”课程学生的平均年龄。","options":[],"answer":"```sql\nSELECT AVG(YEAR(CURDATE()) - YEAR(s.sbirthday)) AS avg_age FROM student AS s JOIN sc ON s.sno = sc.sno WHERE sc.cno = 'C04';\n```","explanation":"本题要求“查询选修“C04”课程学生的平均年龄”。数据来源为 student、sc；SELECT 列表为 AVG(YEAR(CURDATE()) - YEAR(s.sbirthday)) AS avg_age；WHERE 条件负责在分组或排序前筛选行：sc.cno = 'C04'。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-269","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":46,"title":"多表连接","kind":"open","answerKind":"open","typeName":"多表连接","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询选修课程名为“数学”的学生学号和姓名。","options":[],"answer":"```sql\nSELECT DISTINCT s.sno, s.sname FROM student AS s JOIN sc ON s.sno = sc.sno JOIN course AS c ON sc.cno = c.cno WHERE c.cname = '数学';\n```","explanation":"本题要求“查询选修课程名为“数学”的学生学号和姓名”。数据来源为 student、sc、course；SELECT 列表为 DISTINCT s.sno, s.sname；WHERE 条件负责在分组或排序前筛选行：c.cname = '数学'。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-270","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":47,"title":"多表连接","kind":"open","answerKind":"open","typeName":"多表连接","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询“钱军”教师任课的课程号，以及选修其课程的学生的学号和成绩。","options":[],"answer":"```sql\nSELECT tt.cno, sc.sno, sc.degree FROM teacher AS t JOIN teaching AS tt ON t.tno = tt.tno JOIN sc ON tt.cno = sc.cno WHERE t.tname = '钱军';\n```","explanation":"本题要求“查询“钱军”教师任课的课程号，以及选修其课程的学生的学号和成绩”。数据来源为 teacher、teaching、sc；SELECT 列表为 tt.cno, sc.sno, sc.degree；WHERE 条件负责在分组或排序前筛选行：t.tname = '钱军'。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-271","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":48,"title":"多表连接","kind":"open","answerKind":"open","typeName":"多表连接","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询在第 3 学期所开课程的课程名称及学生成绩。","options":[],"answer":"```sql\nSELECT c.cname, sc.degree FROM teaching AS tt JOIN course AS c ON tt.cno = c.cno JOIN sc ON tt.cno = sc.cno WHERE tt.cterm = 3;\n```","explanation":"本题要求“查询在第 3 学期所开课程的课程名称及学生成绩”。数据来源为 teaching、course、sc；SELECT 列表为 c.cname, sc.degree；WHERE 条件负责在分组或排序前筛选行：tt.cterm = 3。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-272","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":49,"title":"多表连接","kind":"open","answerKind":"open","typeName":"多表连接","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询选修“C02”课程且不及格的学生信息。","options":[],"answer":"```sql\nSELECT s.* FROM student AS s JOIN sc ON s.sno = sc.sno WHERE sc.cno = 'C02' AND sc.degree < 60;\n```","explanation":"本题要求“查询选修“C02”课程且不及格的学生信息”。数据来源为 student、sc；SELECT 列表为 s.*；WHERE 条件负责在分组或排序前筛选行：sc.cno = 'C02' AND sc.degree < 60。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-273","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":50,"title":"多表连接","kind":"open","answerKind":"open","typeName":"多表连接","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询软件工程系成绩在 90 分以上学生的姓名、性别和课程名称。","options":[],"answer":"```sql\nSELECT s.sname, s.ssex, c.cname FROM student AS s JOIN sc ON s.sno = sc.sno JOIN course AS c ON sc.cno = c.cno WHERE s.sdept = '软件工程系' AND sc.degree > 90;\n```","explanation":"本题要求“查询软件工程系成绩在 90 分以上学生的姓名、性别和课程名称”。数据来源为 student、sc、course；SELECT 列表为 s.sname, s.ssex, c.cname；WHERE 条件负责在分组或排序前筛选行：s.sdept = '软件工程系' AND sc.degree > 90。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-274","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":51,"title":"多表连接","kind":"open","answerKind":"open","typeName":"多表连接","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询同时选修“C04”和“C02”课程的学生姓名及两门课程成绩。","options":[],"answer":"```sql\nSELECT s.sname, c4.degree AS c04_degree, c2.degree AS c02_degree FROM student AS s JOIN sc AS c4 ON s.sno = c4.sno AND c4.cno = 'C04' JOIN sc AS c2 ON s.sno = c2.sno AND c2.cno = 'C02';\n```","explanation":"本题要求“查询同时选修“C04”和“C02”课程的学生姓名及两门课程成绩”。数据来源为 student、sc；SELECT 列表为 s.sname, c4.degree AS c04_degree, c2.degree AS c02_degree。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-275","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":52,"title":"嵌套查询","kind":"open","answerKind":"open","typeName":"嵌套查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n使用 IN 子查询查询“李勇”同学所选课程的成绩。","options":[],"answer":"```sql\nSELECT cno, degree FROM sc WHERE sno IN (SELECT sno FROM student WHERE sname = '李勇');\n```","explanation":"本题要求“使用 IN 子查询查询“李勇”同学所选课程的成绩”。数据来源为 sc、student；SELECT 列表为 cno, degree；WHERE 条件负责在分组或排序前筛选行：sno IN (SELECT sno FROM student WHERE sname = '李勇')；子查询先给出候选集合、极值或存在性判断，外层查询再据此筛选。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-276","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":53,"title":"嵌套查询","kind":"open","answerKind":"open","typeName":"嵌套查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n使用子查询查询“李新”老师所授课程的课程名称。","options":[],"answer":"```sql\nSELECT cname FROM course WHERE cno IN (SELECT cno FROM teaching WHERE tno IN (SELECT tno FROM teacher WHERE tname = '李新'));\n```","explanation":"本题要求“使用子查询查询“李新”老师所授课程的课程名称”。数据来源为 course、teaching、teacher；SELECT 列表为 cname；WHERE 条件负责在分组或排序前筛选行：cno IN (SELECT cno FROM teaching WHERE tno IN (SELECT tno FROM teacher WHERE tname = '李新'))；子查询先给出候选集合、极值或存在性判断，外层查询再据此筛选。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-277","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":54,"title":"嵌套查询","kind":"open","answerKind":"open","typeName":"嵌套查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n使用子查询查询女教师所授课程的课程号及课程名称。","options":[],"answer":"```sql\nSELECT cno, cname FROM course WHERE cno IN (SELECT cno FROM teaching WHERE tno IN (SELECT tno FROM teacher WHERE tsex = '女'));\n```","explanation":"本题要求“使用子查询查询女教师所授课程的课程号及课程名称”。数据来源为 course、teaching、teacher；SELECT 列表为 cno, cname；WHERE 条件负责在分组或排序前筛选行：cno IN (SELECT cno FROM teaching WHERE tno IN (SELECT tno FROM teacher WHERE tsex = '女'))；子查询先给出候选集合、极值或存在性判断，外层查询再据此筛选。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-278","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":55,"title":"嵌套查询","kind":"open","answerKind":"open","typeName":"嵌套查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n使用子查询查询姓“王”的学生所学课程名称。","options":[],"answer":"```sql\nSELECT cname FROM course WHERE cno IN (SELECT cno FROM sc WHERE sno IN (SELECT sno FROM student WHERE sname LIKE '王%'));\n```","explanation":"本题要求“使用子查询查询姓“王”的学生所学课程名称”。数据来源为 course、sc、student；SELECT 列表为 cname；WHERE 条件负责在分组或排序前筛选行：cno IN (SELECT cno FROM sc WHERE sno IN (SELECT sno FROM student WHERE sname LIKE '王%'))；子查询先给出候选集合、极值或存在性判断，外层查询再据此筛选；LIKE 中 % 表示任意长度字符，_ 表示单个字符，必要时使用 ESCAPE 转义。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-279","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":56,"title":"嵌套查询","kind":"open","answerKind":"open","typeName":"嵌套查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n使用子查询查询选修“C02”课程且不及格的学生信息。","options":[],"answer":"```sql\nSELECT * FROM student WHERE sno IN (SELECT sno FROM sc WHERE cno = 'C02' AND degree < 60);\n```","explanation":"本题要求“使用子查询查询选修“C02”课程且不及格的学生信息”。数据来源为 student、sc；使用 * 返回目标表的全部列；WHERE 条件负责在分组或排序前筛选行：sno IN (SELECT sno FROM sc WHERE cno = 'C02' AND degree < 60)；子查询先给出候选集合、极值或存在性判断，外层查询再据此筛选。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-280","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":57,"title":"嵌套查询","kind":"open","answerKind":"open","typeName":"嵌套查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n使用子查询查询选修“数据库”课程且成绩在 80～90 分的学生学号及成绩。","options":[],"answer":"```sql\nSELECT sno, degree FROM sc WHERE cno IN (SELECT cno FROM course WHERE cname = '数据库') AND degree BETWEEN 80 AND 90;\n```","explanation":"本题要求“使用子查询查询选修“数据库”课程且成绩在 80～90 分的学生学号及成绩”。数据来源为 sc、course；SELECT 列表为 sno, degree；WHERE 条件负责在分组或排序前筛选行：cno IN (SELECT cno FROM course WHERE cname = '数据库') AND degree BETWEEN 80 AND 90；子查询先给出候选集合、极值或存在性判断，外层查询再据此筛选。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-281","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":58,"title":"嵌套查询","kind":"open","answerKind":"open","typeName":"嵌套查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n使用子查询查询选修“C04”课程学生的平均年龄。","options":[],"answer":"```sql\nSELECT AVG(YEAR(CURDATE()) - YEAR(sbirthday)) AS avg_age FROM student WHERE sno IN (SELECT sno FROM sc WHERE cno = 'C04');\n```","explanation":"本题要求“使用子查询查询选修“C04”课程学生的平均年龄”。数据来源为 student、sc；SELECT 列表为 AVG(YEAR(CURDATE()) - YEAR(sbirthday)) AS avg_age；WHERE 条件负责在分组或排序前筛选行：sno IN (SELECT sno FROM sc WHERE cno = 'C04')；子查询先给出候选集合、极值或存在性判断，外层查询再据此筛选。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-282","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":59,"title":"嵌套查询","kind":"open","answerKind":"open","typeName":"嵌套查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n使用子查询查询选修课程名为“数学”的学生学号和姓名。","options":[],"answer":"```sql\nSELECT sno, sname FROM student WHERE sno IN (SELECT sno FROM sc WHERE cno IN (SELECT cno FROM course WHERE cname = '数学'));\n```","explanation":"本题要求“使用子查询查询选修课程名为“数学”的学生学号和姓名”。数据来源为 student、sc、course；SELECT 列表为 sno, sname；WHERE 条件负责在分组或排序前筛选行：sno IN (SELECT sno FROM sc WHERE cno IN (SELECT cno FROM course WHERE cname = '数学'))；子查询先给出候选集合、极值或存在性判断，外层查询再据此筛选。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-283","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":60,"title":"嵌套查询","kind":"open","answerKind":"open","typeName":"嵌套查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n使用子查询查询“钱军”教师任课的课程号，以及选修其课程的学生的学号和成绩。","options":[],"answer":"```sql\nSELECT t2.cno, sc.sno, sc.degree FROM teaching AS t2 JOIN sc ON t2.cno = sc.cno WHERE t2.tno IN (SELECT tno FROM teacher WHERE tname = '钱军');\n```","explanation":"本题要求“使用子查询查询“钱军”教师任课的课程号，以及选修其课程的学生的学号和成绩”。数据来源为 teaching、sc、teacher；SELECT 列表为 t2.cno, sc.sno, sc.degree；WHERE 条件负责在分组或排序前筛选行：t2.tno IN (SELECT tno FROM teacher WHERE tname = '钱军')；子查询先给出候选集合、极值或存在性判断，外层查询再据此筛选。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-284","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":61,"title":"嵌套查询","kind":"open","answerKind":"open","typeName":"嵌套查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n使用子查询查询第 3 学期所开课程的课程名称及学生成绩。","options":[],"answer":"```sql\nSELECT c.cname, sc.degree FROM course AS c JOIN sc ON c.cno = sc.cno WHERE c.cno IN (SELECT cno FROM teaching WHERE cterm = 3);\n```","explanation":"本题要求“使用子查询查询第 3 学期所开课程的课程名称及学生成绩”。数据来源为 course、sc、teaching；SELECT 列表为 c.cname, sc.degree；WHERE 条件负责在分组或排序前筛选行：c.cno IN (SELECT cno FROM teaching WHERE cterm = 3)；子查询先给出候选集合、极值或存在性判断，外层查询再据此筛选。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-285","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":62,"title":"嵌套查询","kind":"open","answerKind":"open","typeName":"嵌套查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询与“李勇”同系的同学姓名，要求使用子查询。","options":[],"answer":"```sql\nSELECT sname FROM student WHERE sdept IN (SELECT sdept FROM student WHERE sname = '李勇');\n```","explanation":"本题要求“查询与“李勇”同系的同学姓名，要求使用子查询”。数据来源为 student；SELECT 列表为 sname；WHERE 条件负责在分组或排序前筛选行：sdept IN (SELECT sdept FROM student WHERE sname = '李勇')；子查询先给出候选集合、极值或存在性判断，外层查询再据此筛选。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-286","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":63,"title":"嵌套查询","kind":"open","answerKind":"open","typeName":"嵌套查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询学号比“刘晨”大、出生日期比她小的学生姓名。","options":[],"answer":"```sql\nSELECT sname FROM student WHERE sno > ALL (SELECT sno FROM student WHERE sname = '刘晨') AND sbirthday < ALL (SELECT sbirthday FROM student WHERE sname = '刘晨');\n```","explanation":"本题要求“查询学号比“刘晨”大、出生日期比她小的学生姓名”。数据来源为 student；SELECT 列表为 sname；WHERE 条件负责在分组或排序前筛选行：sno > ALL (SELECT sno FROM student WHERE sname = '刘晨') AND sbirthday < ALL (SELECT sbirthday FROM student WHERE sname = '刘晨')；子查询先给出候选集合、极值或存在性判断，外层查询再据此筛选。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-287","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":64,"title":"嵌套查询","kind":"open","answerKind":"open","typeName":"嵌套查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询出生日期大于所有女同学出生日期的男同学姓名及系别。","options":[],"answer":"```sql\nSELECT sname, sdept FROM student WHERE sbirthday > ALL (SELECT sbirthday FROM student WHERE ssex = '女') AND ssex = '男';\n```","explanation":"本题要求“查询出生日期大于所有女同学出生日期的男同学姓名及系别”。数据来源为 student；SELECT 列表为 sname, sdept；WHERE 条件负责在分组或排序前筛选行：sbirthday > ALL (SELECT sbirthday FROM student WHERE ssex = '女') AND ssex = '男'；子查询先给出候选集合、极值或存在性判断，外层查询再据此筛选。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-288","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":65,"title":"嵌套查询","kind":"open","answerKind":"open","typeName":"嵌套查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询成绩高于本课程平均成绩的学生学号、课程号和成绩。","options":[],"answer":"```sql\nSELECT a.sno, a.cno, a.degree FROM sc AS a WHERE a.degree > (SELECT AVG(b.degree) FROM sc AS b WHERE b.cno = a.cno);\n```","explanation":"本题要求“查询成绩高于本课程平均成绩的学生学号、课程号和成绩”。数据来源为 sc；SELECT 列表为 a.sno, a.cno, a.degree；WHERE 条件负责在分组或排序前筛选行：a.degree > (SELECT AVG(b.degree) FROM sc AS b WHERE b.cno = a.cno)。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-289","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":66,"title":"嵌套查询","kind":"open","answerKind":"open","typeName":"嵌套查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询不讲授“C01”课程的教师姓名。","options":[],"answer":"```sql\nSELECT tname FROM teacher WHERE tno NOT IN (SELECT tno FROM teaching WHERE cno = 'C01');\n```","explanation":"本题要求“查询不讲授“C01”课程的教师姓名”。数据来源为 teacher、teaching；SELECT 列表为 tname；WHERE 条件负责在分组或排序前筛选行：tno NOT IN (SELECT tno FROM teaching WHERE cno = 'C01')；子查询先给出候选集合、极值或存在性判断，外层查询再据此筛选。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-290","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":67,"title":"嵌套查询","kind":"open","answerKind":"open","typeName":"嵌套查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询没有选修“C02”课程的学生学号及姓名。","options":[],"answer":"```sql\nSELECT sno, sname FROM student WHERE sno NOT IN (SELECT sno FROM sc WHERE cno = 'C02');\n```","explanation":"本题要求“查询没有选修“C02”课程的学生学号及姓名”。数据来源为 student、sc；SELECT 列表为 sno, sname；WHERE 条件负责在分组或排序前筛选行：sno NOT IN (SELECT sno FROM sc WHERE cno = 'C02')；子查询先给出候选集合、极值或存在性判断，外层查询再据此筛选。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-291","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":68,"title":"嵌套查询","kind":"open","answerKind":"open","typeName":"嵌套查询","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查询选修“数据库”课程的学生学号、姓名及系别。","options":[],"answer":"```sql\nSELECT sno, sname, sdept FROM student WHERE sno IN (SELECT sno FROM sc WHERE cno IN (SELECT cno FROM course WHERE cname = '数据库'));\n```","explanation":"本题要求“查询选修“数据库”课程的学生学号、姓名及系别”。数据来源为 student、sc、course；SELECT 列表为 sno, sname, sdept；WHERE 条件负责在分组或排序前筛选行：sno IN (SELECT sno FROM sc WHERE cno IN (SELECT cno FROM course WHERE cname = '数据库'))；子查询先给出候选集合、极值或存在性判断，外层查询再据此筛选。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-081","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":81,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"“学生-选课-课程”数据库中的3个关系：\nS(S#,SNAME,SEX,DEPARTMENT)，主码是S#；\nC(C#,CNAME,TEACHER)，主码是C#；\nSC(S#,C#,GRADE)，主码是(S#，C#)。\n查找每个学生的学号、姓名、选修的课程名和成绩，将使用关系（ ）。","options":["只有S,SC","只有SC,C","只有S,C","S,SC,C"],"answer":["D"],"explanation":"正确答案：D。学号和姓名来自 S，课程名来自 C，成绩来自 SC，因此需要同时连接 S、SC、C。","origin":"《数据库原理及应用》总复习"},{"id":"doc-082","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":82,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"“学生-选课-课程”数据库中的3个关系：\nS(S#,SNAME,SEX,DEPARTMENT)，主码是S#；\nC(C#,CNAME,TEACHER)，主码是C#；\nSC(S#,C#,GRADE)，主码是(S#，C#)。\n若要查找“由张劲老师执教的数据库课程的平均成绩、最高成绩和最低成绩”，则将使用关系（ ）。","options":["只有S,SC","只有SC,C","只有S,C","S,SC,C"],"answer":["B"],"explanation":"正确答案：B。教师姓名在 C，成绩在 SC；题目不要求 S 中属性，因此使用 C 和 SC。","origin":"《数据库原理及应用》总复习"},{"id":"doc-083","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":83,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"基于这样的3个表，即学生表S、课程表C和学生选课表SC，它们的关系模式如下：\nS(S#，SN，SEX，AGE，DEPT)(学号，姓名，性别，年龄，系别)，\nC(C#，CN)(课程号，课程名称)，\nSC(S#，C#，GRADE)(学号，课程号，成绩)，\n检索学生姓名及其所选修课程的课程号和成绩。正确的SELECT语句是（ ）。","options":["SELECT S.SN,SC.C#,SC.GRADE FROM S WHERE S.S#=SC.S#","SELECT S.SN, SC.C#,SC.GRADE FROM SC WHERE S.S#=SC.GRADE","SELECT S.SN,SC.C#,SC.GRADE FROM S, SC WHERE S.S#=SC.S#","SELECT S.SN,SC.C#,SC.GRADE FROM S,SC"],"answer":["C"],"explanation":"正确答案：C。学生姓名在 S，课程号和成绩在 SC，需按 S# 等值连接 S 与 SC。","origin":"《数据库原理及应用》总复习"},{"id":"doc-084","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":84,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"假设学生关系S（S＃，SNAME，SEX），课程关系C（C＃，CNAME），学生选课关系SC（S＃，C＃，GRADE）。要查询选修“Computer”课的男生姓名，将涉及到关系（ ）。","options":["S","SC","SC和C","S、SC和C"],"answer":["D"],"explanation":"正确答案：D。性别在 S，成绩和选课关系在 SC，课程名在 C，三个关系都需要。","origin":"《数据库原理及应用》总复习"},{"id":"doc-085","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":85,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"设有关系R(A,B,C)和S(C,D)，与关系代数表达式πA,B,D(σR.C=S.C(R∞S))等价的SQL语句是（ ）。","options":["SELECT * FROM R，S WHERE R.C=S.C","SELECT A,B,D FROM R,S WHERE R.C=S.C","SELECT A,B,D FROM R,S WHERE R=S","SELECT A,B FROM R WHERE(SELECT D FROM S WHERE R.C=S.C"],"answer":["B"],"explanation":"正确答案：B。先按 R.C=S.C 连接，再投影 A、B、D；重复列 C 只在连接条件中使用。","origin":"《数据库原理及应用》总复习"},{"id":"doc-086","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":86,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"有关系S(S#,SNAME,SAGE)，C(C#,CNAME)，SC(S#,C#,GRADE)。要查询选修“ACCESS”课的年龄不小于20的全体学生姓名的SQL语句是“SELECT SNAME FROM S,C,SC WHERE子句”。这里的WHERE子句的内容是（ ）。","options":["S.S#=SC.S# AND C.C#=SC.C# AND SAGE>=20 AND CNAME='ACCESS'","S.S#=SC.S# AND C.C#=SC.C#","SAGE>=20 AND CNAME='ACCESS'","SAGE>=20 AND CNAME IN ACCESS"],"answer":["A"],"explanation":"正确答案：A。必须同时建立 S-SC、C-SC 连接，并筛选年龄和课程名；字符常量 ACCESS 要加引号。","origin":"《数据库原理及应用》总复习"},{"id":"doc-087","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":87,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"有关系S（S＃，SNAME，SEX），C（C＃，CNAME），SC（S＃，C＃，GRADE）。其中S＃是学生号，SNAME是学生姓名，SEX是性别， C＃是课程号，CNAME是课程名称。要查询选修“数据库”课的全体男生姓名的SQL语句是SELECT SNAME FROM S,C,SC WHERE子句。这里的WHERE子句的内容是（ ）。","options":["S.S#=SC.S# AND C.C#=SC.C# AND SEX='男' AND CNAME='数据库'","S.S#=SC.S# AND C.C#=SC.C#","SEX='男' AND CNAME='数据库'","S.SEX='男' AND CNAME='数据库'"],"answer":["A"],"explanation":"正确答案：A。需要连接 S、SC、C，并同时限制 SEX='男' 与 CNAME='数据库'。","origin":"《数据库原理及应用》总复习"},{"id":"doc-311","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":88,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n给表起较短别名有什么好处？","options":[],"answer":"可以缩短列引用，尤其在自连接和多表连接中用别名区分同一张表的不同角色。","explanation":"别名不改变数据含义，只影响语句中的引用方式和结果列名。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-089","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":89,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"基于这样的3个表，即学生表S、课程表C和学生选课表SC，它们的关系模式如下：\nS(S#，SN，SEX，AGE，DEPT)(学号，姓名，性别，年龄，系别)\nC(C#，CN)(课程号，课程名称)\nSC(S#，C#，GRADE)(学号，课程号，成绩)。\n检索选修课程“C2”的学生中成绩最高的学生的学号。正确的SELECT语句是（ ）。","options":["SELECT S# FROM SC WHERE C#='C2' AND GRADE>=(SELECT GRADE FROM SC WHERE C#='C2')","SELECT S# FROM SC WHERE C#='C2' AND GRADE IN(SELECT GRADE FROM SC WHERE C#='C2')","SELECT S# FROM SC WHERE C#='C2' AND GRADE NOT IN(SELECT GRADE FROM SC WHERE C#='C2')","SELECT S# FROM SC WHERE C#='C2' AND GRADE>=ALL(SELECT GRADE FROM SC WHERE C#='C2')"],"answer":["D"],"explanation":"正确答案：D。先用 GRADE>=ALL(同课程成绩) 找出 C2 的最高分，再返回对应学生学号。","origin":"《数据库原理及应用》总复习"},{"id":"doc-312","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":89,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n内连接与外连接有什么区别？","options":[],"answer":"内连接只保留连接条件匹配的行；外连接还会保留指定一侧的全部行，无匹配列补 NULL。","explanation":"左外连接保留左表全部行，右外连接保留右表全部行。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-090","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":90,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"现有学生表S、课程表C和学生选课表SC，它们的关系模式如下。\nS(S#,SN,SEX,AGE,DEPT)(学号,姓名,性别,年龄,系别)；\nC(C#,CN)(课程号,课程名称)；\nSC(S#,C#,GRADE)(学号,课程号,成绩)。\n检索所有比“王华”年龄大的学生姓名、年龄和性别。下面正确的SELECT语句是（ ）。","options":["SELECT SN,AGE,SEX FROM S WHERE AGE>(SELECT AGE FROM S WHERE SN='王华')","SELECT SN,AGE,SEX FROM S WHERE SN='王华'","SELECT SN,AGE,SEX FROM S WHERE AGE>(SELECT AGE WHERE SN='王华')","SELECT SN,AGE,SEX FROM S WHERE SGE>'王华'.AGE"],"answer":["A"],"explanation":"正确答案：A。标量子查询先求王华年龄，外层筛选 AGE 更大的学生。","origin":"《数据库原理及应用》总复习"},{"id":"doc-313","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":90,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\nIN 与 = 在什么情况下作用相同？","options":[],"answer":"当子查询确定只返回一个值时，IN 与该标量子查询的 = 效果相同。","explanation":"无法保证单值时应使用 IN，避免子查询返回多行导致错误。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-091","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":91,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"在SQL语言中，子查询是（ ）。","options":["返回单表中数据子集的查询语句","选取多表中字段子集的查询语句","选取单表中字段子集的查询语句","嵌入到另一个查询语句之中的查询语句"],"answer":["D"],"explanation":"正确答案：D。子查询是嵌入另一个查询中的 SELECT，可作为标量、集合、派生表或 EXISTS 条件。","origin":"《数据库原理及应用》总复习"},{"id":"doc-314","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":91,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\nEXISTS 子查询何时使外层 WHERE 条件为真？","options":[],"answer":"子查询至少返回一行时 EXISTS 为真；NOT EXISTS 则相反。","explanation":"EXISTS 只关心是否存在匹配行，子查询 SELECT 列表写 1 或 * 通常不影响语义。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-315","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":92,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n既能用连接查询又能用嵌套查询时，应如何选择？","options":[],"answer":"应优先根据可读性、数据库优化器和执行计划选择；连接查询通常便于优化，嵌套查询语义更直观。不能一概断言嵌套查询更快。","explanation":"现代 DBMS 常会把 IN/EXISTS 改写为半连接，最终性能应以执行计划为准。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-316","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":93,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n子查询通常分为哪几类？","options":[],"answer":"按相关性和结果形状可分为不相关子查询、相关子查询、标量子查询、列子查询、行子查询和表子查询等。","explanation":"相关子查询引用外层查询列，逻辑上可能随外层每行执行；不相关子查询可独立计算一次。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-317","chapter":6,"chapterTitle":"第六章 多表连接与子查询","number":94,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n相关子查询的执行过程是什么？","options":[],"answer":"外层查询逐行提供相关列值给子查询，子查询判断是否存在匹配行或返回结果，再由外层决定是否保留该行。","explanation":"实现层可能缓存或改写为连接，但答题时可按逐行相关语义解释。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"7-01","chapter":7,"chapterTitle":"第七章 视图与索引","number":1,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"视图本质上通常是（ ）。","options":["保存完整数据副本的物理表","基于查询定义的虚拟表","只能存储一列数据的表","数据库的备份文件"],"answer":["B"],"explanation":"视图是基于 SELECT 查询定义的虚拟表，通常不保存实际数据，查询视图时会转换为对基础表的查询。某些 DBMS 支持物化视图，会存储结果并需要刷新，但基础课程中“视图通常不存数据”是核心结论。"},{"id":"7-02","chapter":7,"chapterTitle":"第七章 视图与索引","number":2,"title":"多项选择题","kind":"choice","answerKind":"choice","typeName":"多项选择","stem":"视图的常见作用包括（ ）。","options":["简化复杂查询","限制用户只能访问部分行或列","为应用提供相对稳定的数据接口","一定能够提高所有更新操作的速度"],"answer":["A","B","C"],"explanation":"视图可以封装连接、过滤和计算逻辑；只授予视图权限而不授予基表权限，可以实现一定的列级或行级访问控制；基表结构变化时，可通过调整视图减少应用改动。D 错误，视图本身不保证更新性能，还可能增加查询复杂度。"},{"id":"7-03","chapter":7,"chapterTitle":"第七章 视图与索引","number":3,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"视图一旦创建，就拥有独立于基础表的数据副本，因此基础表变化不会影响视图查询结果。","options":[],"answer":"错","explanation":"普通视图不保存独立数据副本，视图查询会访问基础表。基础表数据变化后，再次查询视图会看到符合视图条件的最新结果。若需要独立快照，需要物化视图、复制表或 ETL 等机制。"},{"id":"7-04","chapter":7,"chapterTitle":"第七章 视图与索引","number":4,"title":"简答题","kind":"open","answerKind":"open","typeName":"简答","stem":"视图与基本表的主要区别是什么？","options":[],"answer":"基本表实际存储数据；普通视图通常只保存查询定义，不直接存储数据。基本表可长期作为数据实体；视图依赖基础表存在。","explanation":"视图是外模式的一种体现，可对用户隐藏部分结构。基本表通常对应模式层的数据结构。虽然简单视图可能支持 DML，但视图更新最终仍作用于基础表，并受可更新性规则限制。"},{"id":"7-05","chapter":7,"chapterTitle":"第七章 视图与索引","number":5,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"创建视图 `v_emp_dept`，显示员工号、姓名和部门名称。","options":[],"answer":"```sql\nCREATE VIEW v_emp_dept AS\nSELECT e.EmpID,\n       e.EmpName,\n       d.DeptName\nFROM Employee e\nJOIN Department d\n  ON e.DeptID = d.DeptID;\n```","explanation":"创建视图时，SELECT 中的列名最好明确，尤其是包含表达式、聚合函数或同名属性时，应使用列别名。视图定义中不要写 `ORDER BY` 来冒充最终排序，最终查询需要排序时应在 SELECT 视图时写 `ORDER BY`。"},{"id":"7-06","chapter":7,"chapterTitle":"第七章 视图与索引","number":6,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询视图 `v_emp_dept` 中计算机学院的员工。","options":[],"answer":"```sql\nSELECT *\nFROM v_emp_dept\nWHERE DeptName = N'计算机学院';\n```","explanation":"视图可以像表一样参与 SELECT。查询视图时，数据库会把视图定义与外部条件结合，生成访问基础表的执行计划。对外部条件是否下推到基础表，由优化器决定，但用户应按逻辑结果理解。"},{"id":"7-07","chapter":7,"chapterTitle":"第七章 视图与索引","number":7,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"在 MySQL 中修改视图 `v_emp_dept`，只显示工资不低于 5000 的员工。","options":[],"answer":"```sql\nCREATE OR REPLACE VIEW v_emp_dept AS\nSELECT e.EmpID,\n       e.EmpName,\n       d.DeptName,\n       e.Salary\nFROM Employee e\nJOIN Department d\n  ON e.DeptID = d.DeptID\nWHERE e.Salary >= 5000;\n```","explanation":"MySQL 常用 `CREATE OR REPLACE VIEW`；SQL Server 常用 `ALTER VIEW`。修改视图时必须保证列的数量、名称和类型仍满足依赖该视图的对象要求，否则可能影响已有查询或应用。"},{"id":"7-08","chapter":7,"chapterTitle":"第七章 视图与索引","number":8,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"删除视图 `v_emp_dept`。","options":[],"answer":"```sql\nDROP VIEW v_emp_dept;\n```","explanation":"删除视图只删除视图定义，不删除基础表和基础表数据。若其他视图依赖该视图，删除时可能受依赖限制或导致后续查询失败。生产环境执行前应检查依赖关系和备份需要。"},{"id":"7-09","chapter":7,"chapterTitle":"第七章 视图与索引","number":9,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"下列视图中，通常最难直接支持 INSERT、UPDATE 和 DELETE 的是（ ）。","options":["只包含一个基础表、保留主键且没有聚合的简单视图","包含 `GROUP BY` 和聚合函数的视图","只选择部分列且没有表达式的视图","基于单表并使用 WHERE 的简单视图"],"answer":["B"],"explanation":"含聚合、GROUP BY、DISTINCT、UNION、复杂子查询或多表连接的视图通常不可直接更新，因为一行视图数据可能无法唯一映射回某个基础表行。简单单表视图更可能可更新，但仍需满足 DBMS 的具体规则。"},{"id":"7-10","chapter":7,"chapterTitle":"第七章 视图与索引","number":10,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"所有视图都可以直接执行 INSERT 和 UPDATE。","options":[],"answer":"错","explanation":"视图更新受基础表数量、是否包含聚合、DISTINCT、GROUP BY、UNION、表达式以及是否包含必要主键等因素限制。即使视图可更新，也可能只允许更新部分列。考试中应表述为“简单视图可能可更新，复杂视图通常只适合查询”。"},{"id":"7-11","chapter":7,"chapterTitle":"第七章 视图与索引","number":11,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"创建只包含计算机学院员工数据的视图，并启用 `WITH CHECK OPTION`。","options":[],"answer":"```sql\nCREATE VIEW v_computer_emp AS\nSELECT EmpID, EmpName, Salary, DeptID\nFROM Employee\nWHERE DeptID = (\n    SELECT DeptID\n    FROM Department\n    WHERE DeptName = N'计算机学院'\n)\nWITH CHECK OPTION;\n```","explanation":"`WITH CHECK OPTION` 用于阻止通过视图插入或更新出不符合视图条件的数据。题目若使用固定部门号，可把条件简化为 `WHERE DeptID = 1`。具体实现和可更新性仍受 DBMS 限制。"},{"id":"7-12","chapter":7,"chapterTitle":"第七章 视图与索引","number":12,"title":"简答题","kind":"open","answerKind":"open","typeName":"简答","stem":"授权用户查询视图而不授予基础表查询权限，有什么安全意义？","options":[],"answer":"可以限制用户只能看到视图暴露的行和列，减少敏感数据暴露。","explanation":"例如工资表视图可隐藏身份证号、银行卡号等字段，也可只显示本部门数据。视图不是绝对安全边界，仍要配合用户、角色、行级安全策略和审计。若视图定义者权限和调用者权限处理不当，也可能带来权限扩大风险。"},{"id":"7-13","chapter":7,"chapterTitle":"第七章 视图与索引","number":13,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"索引最主要的作用是（ ）。","options":["自动消除数据冗余","加快数据定位和查询","代替主键约束","保证所有字段都非空"],"answer":["B"],"explanation":"索引类似书的目录，能减少扫描数据页的数量，常用于 WHERE、JOIN、ORDER BY 等场景。索引不能自动消除冗余，不能取代完整性约束，也不保证字段非空。唯一索引可以辅助保证唯一性，但普通索引不具备该作用。"},{"id":"7-14","chapter":7,"chapterTitle":"第七章 视图与索引","number":14,"title":"多项选择题","kind":"choice","answerKind":"choice","typeName":"多项选择","stem":"建立索引可能带来的代价包括（ ）。","options":["占用额外的存储空间","增加 INSERT 的维护成本","增加 UPDATE 和 DELETE 的维护成本","让所有查询都无条件变快"],"answer":["A","B","C"],"explanation":"索引需要空间，数据变化时还要维护索引结构。索引只对符合其结构和查询条件的访问有帮助，低选择性列、频繁更新列或查询条件无法使用索引时，收益可能很小甚至有害。D 过于绝对。"},{"id":"7-15","chapter":7,"chapterTitle":"第七章 视图与索引","number":15,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"聚集索引决定或近似决定表中数据行的物理排列顺序，一个表通常只能有一个聚集索引。","options":[],"answer":"对","explanation":"数据行只能按一种主要顺序物理组织，因此一个表通常只能有一个聚集索引。非聚集索引单独保存索引键和行定位信息，一个表可以有多个。不同 DBMS 的存储实现和术语略有差异。"},{"id":"7-16","chapter":7,"chapterTitle":"第七章 视图与索引","number":16,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"一个表可以建立多个（ ）。","options":["主键","聚集索引","非聚集索引","数据库"],"answer":["C"],"explanation":"一个表只能有一个主键约束，通常也只能有一个聚集索引，但可以有多个非聚集索引。索引数量不是越多越好，应根据查询负载、写入成本和空间预算综合设计。"},{"id":"7-17","chapter":7,"chapterTitle":"第七章 视图与索引","number":17,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"在 Employee 表的 EmpName 列上创建普通索引 `idx_emp_name`。","options":[],"answer":"```sql\nCREATE INDEX idx_emp_name\nON Employee(EmpName);\n```","explanation":"普通索引允许重复值。若查询经常按姓名筛选，索引可能有用；如果姓名选择性很低、表很小或更新频繁，收益可能有限。实际系统可先查看执行计划和统计信息，再决定是否添加。"},{"id":"7-18","chapter":7,"chapterTitle":"第七章 视图与索引","number":18,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"在 Department 表的 DeptName 列上创建唯一索引，并写出删除该索引的 MySQL 语句。","options":[],"answer":"```sql\nCREATE UNIQUE INDEX idx_dept_name\nON Department(DeptName);\n\nDROP INDEX idx_dept_name ON Department;\n```","explanation":"唯一索引要求索引键在非 NULL 值上不重复。NULL 的处理规则依 DBMS 而异。SQL Server 删除索引常用 `DROP INDEX idx_dept_name ON Department;`，但某些旧版本或特定对象可能使用不同的语法，答题时要看题目环境。"},{"id":"7-19","chapter":7,"chapterTitle":"第七章 视图与索引","number":19,"title":"简答题","kind":"open","answerKind":"open","typeName":"简答","stem":"复合索引 `(A, B, C)` 的最左前缀原则是什么？给出可以使用和不能有效使用该索引的条件示例。","options":[],"answer":"查询条件应以 A 开始，才能较好利用索引；可以使用 `A`、`A AND B`、`A AND B AND C`，通常不能直接利用 `B` 或 `C` 作为最左条件。","explanation":"最左前缀原则是 B+ 树复合索引的常见规则。范围条件会影响后续列的使用程度，具体能否使用索引还取决于优化器、统计信息和查询写法。`A` 上使用函数或隐式类型转换也可能导致索引失效。"},{"id":"7-20","chapter":7,"chapterTitle":"第七章 视图与索引","number":20,"title":"综合应用题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询 `WHERE YEAR(HireDate) = 2026` 较慢。请说明可能原因并给出改写方案。","options":[],"answer":"对索引列 HireDate 使用 YEAR 函数可能阻止普通索引有效使用。可改写为日期范围：`HireDate >= '2026-01-01' AND HireDate < '2027-01-01'`。","explanation":"在索引列上做函数、运算或隐式类型转换，可能使数据库无法直接利用索引。使用半开区间 `[2026-01-01, 2027-01-01)` 能正确包含 2026 年全部时间点，并避免 `BETWEEN ... '2026-12-31'` 漏掉带时间部分的记录。最终应使用执行计划验证。"},{"id":"doc-181","chapter":7,"chapterTitle":"第七章 视图与索引","number":50,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"在数据库中建立的索引越多越好。","options":[],"answer":"错","explanation":"答案：错。索引会增加存储和维护成本，过多索引会拖慢插入、更新和删除。","origin":"《数据库原理及应用》总复习"},{"id":"doc-182","chapter":7,"chapterTitle":"第七章 视图与索引","number":51,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"在一个基本表上可以创建多个索引。","options":[],"answer":"对","explanation":"答案：对。一个基本表可以建立多个普通、唯一或复合索引。","origin":"《数据库原理及应用》总复习"},{"id":"doc-183","chapter":7,"chapterTitle":"第七章 视图与索引","number":52,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"在MySQL中，若一个表中的某个字段的取值范围很少，则该列不适合创建索引。","options":[],"answer":"对","explanation":"答案：对。取值很少的列选择性低，索引区分度不足，通常不适合单独建立索引。","origin":"《数据库原理及应用》总复习"},{"id":"doc-184","chapter":7,"chapterTitle":"第七章 视图与索引","number":53,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"SQL语言的视图定义和视图操作功能在一定程度上支持了数据的逻辑独立性。","options":[],"answer":"对","explanation":"答案：对。视图可隐藏基表结构变化，在一定程度上提高逻辑独立性和安全性。","origin":"《数据库原理及应用》总复习"},{"id":"doc-185","chapter":7,"chapterTitle":"第七章 视图与索引","number":54,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"视图本身没有保存数据，而是保存一条查询语句。","options":[],"answer":"对","explanation":"答案：对。普通视图通常只保存查询定义，查询时再从基本表产生结果。","origin":"《数据库原理及应用》总复习"},{"id":"doc-186","chapter":7,"chapterTitle":"第七章 视图与索引","number":55,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"视图和表是完全一样的。","options":[],"answer":"错","explanation":"答案：错。视图是虚表，基本表实际存储数据，两者在存储和更新规则上不同。","origin":"《数据库原理及应用》总复习"},{"id":"doc-187","chapter":7,"chapterTitle":"第七章 视图与索引","number":56,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"因为通过视图可以插入、修改或删除数据，因此视图也是一个实在表。","options":[],"answer":"错","explanation":"答案：错。部分视图可以更新，但更新最终作用于基本表，视图本身不是实在表。","origin":"《数据库原理及应用》总复习"},{"id":"doc-188","chapter":7,"chapterTitle":"第七章 视图与索引","number":57,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"在关系数据库中，视图是三级模式中的外模式。","options":[],"answer":"对","explanation":"答案：对。视图面向具体用户，通常对应三级模式结构中的外模式。","origin":"《数据库原理及应用》总复习"},{"id":"doc-189","chapter":7,"chapterTitle":"第七章 视图与索引","number":58,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"在MySQL中，删除一个视图所用的命令是DELETE。","options":[],"answer":"错","explanation":"答案：错。MySQL 删除视图使用 DROP VIEW；DELETE 删除表中数据。","origin":"《数据库原理及应用》总复习"},{"id":"doc-321","chapter":7,"chapterTitle":"第七章 视图与索引","number":98,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n数据库中索引被损坏后会产生什么结果？","options":[],"answer":"索引损坏可能导致查询结果错误、查询失败或性能显著下降。应通过一致性检查、重建索引或从备份恢复处理。","explanation":"索引只是辅助存取结构，但其错误会影响优化器访问路径和查询正确性，因此需要定期维护。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-099","chapter":7,"chapterTitle":"第七章 视图与索引","number":99,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"创建索引的主要目的是（ ）。","options":["提高查询和存取速度","增加存储空间","保证所有字段非空","自动消除数据冗余"],"answer":["A"],"explanation":"正确答案：A。索引的主要目的是加快数据定位和查询速度，但会增加存储和更新维护成本。","origin":"《数据库原理及应用》总复习"},{"id":"doc-322","chapter":7,"chapterTitle":"第七章 视图与索引","number":99,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n普通视图上能创建索引吗？","options":[],"answer":"MySQL 的普通视图不能直接创建索引；物化视图是否支持索引取决于具体 DBMS。","explanation":"普通视图是查询定义，不拥有独立的物理数据页，因此没有可直接建立 B+ 树索引的数据对象。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-100","chapter":7,"chapterTitle":"第七章 视图与索引","number":100,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"为了使索引键的值在基本表中唯一，在创建索引的语句中应使用保留字（ ）。","options":["UNIQUE","COUNT","DISTINCT","UNION"],"answer":["A"],"explanation":"正确答案：A。CREATE UNIQUE INDEX 使用 UNIQUE 保证索引键值不重复。","origin":"《数据库原理及应用》总复习"},{"id":"doc-323","chapter":7,"chapterTitle":"第七章 视图与索引","number":100,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n向视图中插入的数据能进入基本表吗？","options":[],"answer":"如果视图是可更新视图，插入数据会转换为对基本表的插入；复杂视图通常不可更新。","explanation":"可更新性取决于视图是否包含聚合、DISTINCT、GROUP BY、UNION 或无法映射的表达式等。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-101","chapter":7,"chapterTitle":"第七章 视图与索引","number":101,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"为了提高特定查询的速度，对SC(S#, C#, DEGREE)关系创建唯一性索引，应该创建在哪一个(组)属性上？（ ）","options":["(S#, C#)","(S#, DEGREE)","(C#, DEGREE)","DEGREE"],"answer":["A"],"explanation":"正确答案：A。SC 的业务唯一性由学号和课程号共同决定，因此唯一索引应建在 (S#, C#)。","origin":"《数据库原理及应用》总复习"},{"id":"doc-324","chapter":7,"chapterTitle":"第七章 视图与索引","number":101,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n修改基本表的数据会自动反映到视图中吗？","options":[],"answer":"会。普通视图查询时会重新读取基本表，因此基本表变化会在下次查询视图时体现。","explanation":"物化视图保存结果副本，需要刷新后才反映基表变化，与普通视图不同。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-102","chapter":7,"chapterTitle":"第七章 视图与索引","number":102,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"下列关于SQL语言中索引(Index)的叙述中，哪一条是不正确的？（ ）","options":["索引是外模式","一个基本表上可以创建多个索引","索引可以加快查询的执行速度","系统在存取数据时会自动选择合适的索引作为存取路径"],"answer":["A"],"explanation":"正确答案：A。索引是物理存取结构，不是外模式；外模式通常由视图等用户视图体现。","origin":"《数据库原理及应用》总复习"},{"id":"doc-103","chapter":7,"chapterTitle":"第七章 视图与索引","number":103,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"下列几种情况下，不适合创建索引的是（ ）。","options":["列的取值范围很少","用作查询条件的列","频繁搜索范围的列","连接中频繁使用的列"],"answer":["A"],"explanation":"正确答案：A。取值很少的低选择性列区分度差，通常不适合单独创建索引。","origin":"《数据库原理及应用》总复习"},{"id":"doc-104","chapter":7,"chapterTitle":"第七章 视图与索引","number":104,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"关于视图下列哪一个说法是错误的（ ）。","options":["视图是一种虚拟表","视图中保存一份完整的数据副本","视图可由视图派生","视图在数据库中保存的是 SELECT 查询定义"],"answer":["B"],"explanation":"正确答案：B。视图是虚表，通常只保存查询定义而不直接保存数据。","origin":"《数据库原理及应用》总复习"},{"id":"doc-105","chapter":7,"chapterTitle":"第七章 视图与索引","number":105,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"设S_AVG(SNO,AVG_GRADE)是一个基于关系SC定义的学号和他的平均成绩的视图。下面对该视图的操作语句中，（ ）是不能正确执行的。\nⅠ.UPDATE S_AVG SET AVG_GRADE=90 WHERE SNO=2004010601\nⅡ.SELECT SNO, AVG_GRADE FROM S_AVG WHERE SNO=2004010601","options":["仅Ⅰ","仅Ⅱ","都能","都不能"],"answer":["A"],"explanation":"正确答案：A。S_AVG 含聚合结果，不能直接通过 UPDATE 修改 AVG_GRADE；查询操作正常。","origin":"《数据库原理及应用》总复习"},{"id":"doc-106","chapter":7,"chapterTitle":"第七章 视图与索引","number":106,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"视图是一个“虚表”，视图的构造基于（ ）。\nⅠ．基本表 Ⅱ．视图 Ⅲ．索引","options":["I 或II","I或Ⅲ","Ⅱ或Ⅲ","Ⅰ、Ⅱ或Ⅲ"],"answer":["A"],"explanation":"正确答案：A。视图可以建立在一个或多个基本表上，也可以建立在其他视图上。","origin":"《数据库原理及应用》总复习"},{"id":"doc-107","chapter":7,"chapterTitle":"第七章 视图与索引","number":107,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"下面关于关系数据库视图的描述不正确的是（ ）。","options":["视图是关系数据库三级模式中的内模式","视图能够对机密数据提供安全保护","视图对重构数据库提供了一定程度的逻辑独立性","对视图的一切操作最终要转换为对其基本表的操作"],"answer":["A"],"explanation":"正确答案：A。视图对应外模式，不是内模式；它可简化查询并提高一定逻辑独立性。","origin":"《数据库原理及应用》总复习"},{"id":"doc-108","chapter":7,"chapterTitle":"第七章 视图与索引","number":108,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"以下关于视图的描述，错误的是（ ）。","options":["视图是从一个或几个基本表或视图导出的虚表","视图并不实际存储数据，只在数据字典中保存其逻辑定义","视图里面的任何数据不可以进行修改","SQL中的SELECT语句可以像对基表一样，对视图进行查询"],"answer":["C"],"explanation":"正确答案：C。简单视图在满足条件时可以更新，复杂视图通常只读，因此“任何数据都不可修改”错误。","origin":"《数据库原理及应用》总复习"},{"id":"doc-109","chapter":7,"chapterTitle":"第七章 视图与索引","number":109,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"在SQL语言中，删除一个视图的命令是（ ）。","options":["DELETE","DROP","CLEAR","REMOVE"],"answer":["B"],"explanation":"正确答案：B。删除视图使用 DROP VIEW；DELETE 删除表中数据。","origin":"《数据库原理及应用》总复习"},{"id":"doc-110","chapter":7,"chapterTitle":"第七章 视图与索引","number":110,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"在关系数据库中，视图(view)是三级模式结构中的（ ）。","options":["内模式","模式","存储模式","外模式"],"answer":["D"],"explanation":"正确答案：D。视图面向用户，通常对应三级模式结构中的外模式。","origin":"《数据库原理及应用》总复习"},{"id":"doc-111","chapter":7,"chapterTitle":"第七章 视图与索引","number":111,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"在关系数据库中，为了简化用户的查询操作，而又不增加数据的存储空间，则应该创建的数据库对象是（ ）。","options":["table(表)","index(索引)","cursor(游标)","view(视图)"],"answer":["D"],"explanation":"正确答案：D。视图不增加实际数据存储空间，却能封装复杂查询并简化用户操作。","origin":"《数据库原理及应用》总复习"},{"id":"doc-112","chapter":7,"chapterTitle":"第七章 视图与索引","number":112,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"在视图上不能完成的操作是（ ）。","options":["更新视图数据","查询","在视图上定义新的基本表","在视图上定义新视图"],"answer":["C"],"explanation":"正确答案：C。基本表是独立数据库对象，不能在视图上定义新的基本表；视图可查询、有限更新或再定义视图。","origin":"《数据库原理及应用》总复习"},{"id":"doc-335","chapter":7,"chapterTitle":"第七章 视图与索引","number":112,"title":"MySQL 操作题","kind":"open","answerKind":"open","typeName":"MySQL 操作题","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n在 test 数据库中创建 workinfo 表，并通过 SQL 完成：id 降序唯一索引 index_id、name 普通索引 index_name、type 与 address 组合索引 index_t、extra 全文索引 index_ext，最后删除 index_id。","options":[],"answer":"```sql\nCREATE TABLE workinfo (\n    id INT,\n    name VARCHAR(50),\n    type VARCHAR(20),\n    address VARCHAR(100),\n    extra TEXT,\n    UNIQUE INDEX index_id (id DESC),\n    INDEX index_name (name),\n    INDEX index_t (type, address),\n    FULLTEXT INDEX index_ext (extra)\n);\n\nDROP INDEX index_id ON workinfo;\n```","explanation":"唯一索引保证 id 非空值不重复，组合索引按 type、address 的最左前缀使用，全文索引用于文本检索。MySQL 删除索引用 DROP INDEX 索引名 ON 表名。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-336","chapter":7,"chapterTitle":"第七章 视图与索引","number":113,"title":"MySQL 操作题","kind":"open","answerKind":"open","typeName":"MySQL 操作题","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n在 writers 表上完成：w_id 唯一索引 uniqidx、w_name 普通索引 nameidx、w_address 与 w_age 组合索引 multiidx、w_note 全文索引 ftidx；随后删除全文索引和普通索引。","options":[],"answer":"```sql\nCREATE TABLE writers (\n    w_id INT,\n    w_name VARCHAR(20),\n    w_address VARCHAR(50),\n    w_age INT,\n    w_note TEXT,\n    UNIQUE INDEX uniqidx (w_id)\n);\n\nALTER TABLE writers ADD INDEX nameidx (w_name);\nCREATE INDEX multiidx ON writers (w_address, w_age);\nCREATE FULLTEXT INDEX ftidx ON writers (w_note);\n\nALTER TABLE writers DROP INDEX ftidx;\nDROP INDEX nameidx ON writers;\n```","explanation":"创建索引可在建表时定义，也可使用 CREATE INDEX 或 ALTER TABLE ADD INDEX。删除索引时必须写明索引名，并在需要的语法中指定所属表。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-337","chapter":7,"chapterTitle":"第七章 视图与索引","number":114,"title":"MySQL 操作题","kind":"open","answerKind":"open","typeName":"MySQL 操作题","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n在 gradem 数据库中完成视图操作：创建成绩大于 90 的 sc_view1、成绩小于 80 的 sc_view2、指定班级选课信息的 sc_view3，以及从 sc_view1 查询 C01 的 view_new；再修改 sc_view1，并测试视图查询、更新和删除。","options":[],"answer":"```sql\nCREATE VIEW sc_view1 AS\nSELECT * FROM sc WHERE degree > 90;\n\nCREATE VIEW sc_view2 AS\nSELECT sno, cno, degree FROM sc WHERE degree < 80;\n\nCREATE VIEW sc_view3 AS\nSELECT s.sname, c.cname, sc.degree\nFROM student AS s\nJOIN sc ON s.sno = sc.sno\nJOIN course AS c ON sc.cno = c.cno\nWHERE s.classno = '20070303';\n\nCREATE VIEW view_new AS\nSELECT * FROM sc_view1 WHERE cno = 'C01';\n\nALTER VIEW sc_view1 AS\nSELECT sc.*\nFROM sc\nWHERE sc.degree > 90\n  AND sc.cno IN (SELECT cno FROM teaching WHERE cterm = 3);\n\nSELECT * FROM sc_view2 WHERE sno = '2007030125' AND cno = 'a01';\nUPDATE sc_view2 SET degree = 87 WHERE sno = '2007030122' AND cno = 'c02';\nDELETE FROM sc_view2 WHERE sno = '2007030123' AND cno = 'a01';\n```","explanation":"普通视图保存查询定义，查询视图会访问基本表。sc_view2 只包含单表字段和简单 WHERE，通常可更新；包含聚合、分组或多表复杂连接的视图通常不可直接更新。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-338","chapter":7,"chapterTitle":"第七章 视图与索引","number":115,"title":"MySQL 操作题","kind":"open","answerKind":"open","typeName":"MySQL 操作题","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n使用图形工具或等价 SQL 创建 stud_query2_view，查询 1984 年出生学生的学号、姓名和家庭住址；再创建 stud_query3_view，查询 1984 年出生的女学生；最后查询并修改 stud_query3_view 中指定学生姓名。","options":[],"answer":"```sql\nCREATE VIEW stud_query2_view AS\nSELECT sno, sname, saddress\nFROM student\nWHERE YEAR(sbirthday) = 1984;\n\nCREATE VIEW stud_query3_view AS\nSELECT sno, sname, saddress\nFROM student\nWHERE YEAR(sbirthday) = 1984 AND ssex = '女';\n\nSELECT * FROM stud_query3_view;\nUPDATE stud_query3_view\nSET sname = '于君'\nWHERE sno = '2007030301';\n```","explanation":"两个视图都只基于 student 表的简单列和筛选条件，通常可更新。生产环境更推荐使用半开日期范围而不是在索引列上使用 YEAR，以便利用出生日期索引。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-131","chapter":7,"chapterTitle":"第七章 视图与索引","number":131,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"不可对视图执行的操作有（ ）。","options":["SELECT","INSERT","DELETE","CREATE INDEX"],"answer":["D"],"explanation":"正确答案：D。视图是虚表，普通视图不能创建索引；其余查询、有限更新和删除通常可按视图规则执行。","origin":"《数据库原理及应用》总复习"},{"id":"8-01","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":1,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"E-R 图中，实体、属性和联系通常分别使用（ ）表示。","options":["矩形、椭圆、菱形","菱形、矩形、椭圆","椭圆、菱形、矩形","矩形、菱形、椭圆"],"answer":["A"],"explanation":"实体用矩形，属性用椭圆，联系用菱形。主键属性通常在属性名下方加下划线。弱实体常用双边矩形，弱联系常用双边菱形。阅卷时图形元素是否规范、连线是否正确、基数是否标出都是得分点。"},{"id":"8-02","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":2,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"E-R 图中的主键属性应加下划线。","options":[],"answer":"对","explanation":"主键属性用于唯一标识实体，标准画法通常在其名称下加下划线。若题目环境不支持下划线，也可在文字说明中明确写“主键：×××”。但图形题中能画下划线时应尽量画。"},{"id":"8-03","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":3,"title":"简答题","kind":"open","answerKind":"open","typeName":"简答","stem":"实体型、实体集和实体实例有什么区别？","options":[],"answer":"实体型是实体名与属性名的结构定义；实体集是同型实体的集合；实体实例是实体集中的一个具体对象。","explanation":"例如 Student(StudentID, Name) 是实体型；某学校全部学生构成实体集；学生“2026001，张三”是一个实体实例。概念设计通常关注实体型的结构和联系，而不逐个录入实例。"},{"id":"8-04","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":4,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"“一个班级只有一个班主任，一个班主任只管理一个班级”属于（ ）。","options":["1:1 联系","1:N 联系","M:N 联系","自反联系"],"answer":["A"],"explanation":"双向提问：一个班级对应几个班主任？一个；一个班主任对应几个班级？一个。因此是 1:1。现实中是否允许多个班级由一个老师管理，应由需求明确，不能仅凭常识替代业务规则。"},{"id":"8-05","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":5,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"“一个部门有多名员工，一名员工只属于一个部门”属于（ ）。","options":["1:1 联系","1:N 联系","M:N 联系","无法判断"],"answer":["B"],"explanation":"一个部门对应多名员工，但一名员工只对应一个部门，从部门到员工是一对多。转换关系模式时，把部门主键作为外键放入员工表，不需要单独建立“隶属”表。"},{"id":"8-06","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":6,"title":"编程与设计题","kind":"open","answerKind":"open","typeName":"综合题","stem":"“一个订单包含多本图书，一本图书可以出现在多个订单中”。写出联系类型及联系属性应挂在哪里。","options":[],"answer":"订单与图书是 M:N 联系；“数量”“成交单价”等只描述本次订单和图书组合的属性应挂在“包含”菱形上。","explanation":"同一本书在不同订单中的数量可能不同，因此数量不属于 Book；一张订单包含多本图书，因此单独一个数量字段也不属于 Orders。联系属性应连到联系菱形上，并在关系模式转换时进入联系表。"},{"id":"8-07","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":7,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"联系只能连接两个实体，不能连接三个实体或带自身属性。","options":[],"answer":"错","explanation":"联系可以连接两个实体，也可以连接三个或更多实体形成多元联系；联系还可以拥有自己的属性。自反联系还可以让同一实体集内的实体发生关系。考试中遇到“供应商向仓库供应零件”“员工有上级”等描述，要特别判断多元联系或自反联系。"},{"id":"8-08","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":8,"title":"简答题","kind":"open","answerKind":"open","typeName":"简答","stem":"“地址”和“部门”在什么情况下应作为属性，在什么情况下应作为实体？","options":[],"answer":"只描述某实体且不需要独立管理时，可作为属性；若需要独立标识、维护负责人、地点、电话等多条信息并被多个对象引用时，应作为独立实体。","explanation":"“地址”若可拆成省、市、区、街道，也可能属于复合属性；若需要管理地址字典和历史版本，则可提升为实体。“部门名称”作为员工的一个普通属性时不是实体；当系统要维护部门主键、负责人和地点时，应建立 Department 实体。"},{"id":"8-09","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":9,"title":"简答题","kind":"open","answerKind":"open","typeName":"简答","stem":"写出从业务需求设计 E-R 图的主要步骤。","options":[],"answer":"找名词识别实体和属性，给实体确定主键，找动词识别联系，判断基线数和联系属性，最后检查模型能否回答全部业务问题。","explanation":"识别时不要见名词就当实体，也不要见动词就漏联系。重点检查“一个 X 对几个 Y、一个 Y 对几个 X”，并把“数量、成绩、借阅日期、工时”等联系属性挂到正确位置。概念模型应独立于具体 DBMS。"},{"id":"8-10","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":10,"title":"简答题","kind":"open","answerKind":"open","typeName":"简答","stem":"什么是弱实体？订单明细为什么可视为弱实体？","options":[],"answer":"弱实体依赖强实体存在，且单靠自身属性不能形成完整主键。订单明细依赖订单，主键通常包含订单号和图书号。","explanation":"订单明细没有订单号就无法独立存在，订单删除后明细通常也应处理。E-R 图中弱实体可用双边矩形表示，标识联系可用双边菱形表示。若教材只采用普通实体和复合主键表达，也可写成 `OrderDetail(OrderID, ISBN, ...)`。"},{"id":"8-11","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":11,"title":"简答题","kind":"open","answerKind":"open","typeName":"简答","stem":"某学生可以有多个联系电话。若电话列表直接放在 Student 表的一列中，会违反什么要求？应如何设计？","options":[],"answer":"会违反属性原子性和 1NF 要求。应拆出 StudentPhone(StudentID, Phone) 表，以 StudentID 和 Phone 为组合主键，StudentID 作为外键。","explanation":"一列中保存 `138...;139...` 属于多值属性。E-R 图中可用多值属性表示，转换关系模式时应单独建表。若允许同一学生保存同一号码的历史状态，还需要增加类型、启用日期或流水号等字段。"},{"id":"8-12","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":12,"title":"综合设计题","kind":"open","answerKind":"open","typeName":"综合题","stem":"在线书店需求：\n\n- 图书：ISBN、书名、价格、出版日期、库存。\n- 客户：客户编号、姓名、电话。\n- 订单：订单号、下单日期、总金额。\n- 一个客户可有多个订单，一个订单属于一个客户。\n- 一个订单包含多本图书，一本图书可出现在多个订单中。\n\n请用文字描述实体、联系、基线数和联系属性。","options":[],"answer":"实体为 Book、Customer、Orders。Customer 与 Orders 是 1:N 的“下单”联系；Orders 与 Book 是 M:N 的“包含”联系，数量、成交单价属于联系属性。","explanation":"客户与订单之间，一个客户多个订单、一个订单一个客户；订单与图书之间，一个订单多本图书、一本图书多个订单。总金额若可由明细计算，属于派生属性；若教材样题明确要求保留，可以保留，但要说明由订单明细维护一致性。"},{"id":"8-13","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":13,"title":"综合设计题","kind":"open","answerKind":"open","typeName":"综合题","stem":"某公司有多个部门，一个部门有多名员工，一名员工只属于一个部门；一个部门最多有一名经理，一名经理最多管理一个部门。\n\n请说明应识别哪些实体和联系。","options":[],"answer":"实体 Department、Employee；Department 与 Employee 之间有 1:N 的“隶属”联系；Department 与 Employee 之间另有 1:1 的“管理”联系。","explanation":"同一对实体之间可以有多条不同语义的联系。经理本身也是员工，因此“管理”联系可看成 Employee 到 Department 的 1:1 联系，也可理解为 Employee 的自反或角色关系的一种业务表达。答题时必须给联系命名并标明基数，避免把“隶属”和“管理”混成一个联系。"},{"id":"8-14","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":14,"title":"综合设计题","kind":"open","answerKind":"open","typeName":"综合题","stem":"画出一个最小可接受的员工-部门 E-R 图文字结构，要求体现实体、属性、主键和联系。","options":[],"answer":"```text\n[Employee] -- n -- <隶属> -- 1 -- [Department]\n  |                                  |\n  +-- EmpID(下划线), EmpName, Salary +\n  +-- DeptID(下划线), DeptName, Location\n```","explanation":"Employee 的主键为 EmpID，Department 的主键为 DeptID。联系从 Employee 一侧标 n，从 Department 一侧标 1。员工表还需要在关系模式中加入 DeptID 作为外键；属性应连到所属实体，联系基数应标在实体与菱形的连线上。"},{"id":"8-15","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":15,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"E-R 图属于概念模型，通常应当独立于具体 DBMS。","options":[],"answer":"对","explanation":"E-R 图描述业务中的实体、属性和联系，不直接规定 MySQL、SQL Server 或 Oracle 的存储实现。进入逻辑设计和物理设计后，才逐步引入关系模式、数据类型、索引和存储引擎。"},{"id":"8-16","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":16,"title":"综合设计题","kind":"open","answerKind":"open","typeName":"综合题","stem":"图书馆要管理读者、图书和借阅。一个读者可借多本书，一本书可被不同读者在不同时间借阅；每次借阅需要记录借阅日期、应还日期和归还日期。请说明联系及主键设计的关键点。","options":[],"answer":"读者与图书之间是 M:N 的“借阅”联系，联系属性为借阅日期、应还日期和归还日期。若允许同一读者多次借同一本书，联系表不能只以 `(ReaderID, ISBN)` 为主键，应增加借阅流水号或借阅日期参与主键。","explanation":"业务是否允许重复借阅决定主键。若每一对读者和图书在系统中永远只有一条历史记录，可用复合主键；若存在续借、归还后再次借阅，应使用 BorrowID 唯一标识每次借阅。主键设计必须保留业务历史并避免覆盖旧记录。"},{"id":"doc-004","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":4,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"下列实体类型的联系中，属于一对一联系的是（ ）。","options":["教研室对教师的所属联系","父亲对孩子的亲生联系","省对省会的所属联系","供应商与工程项目的供货联系"],"answer":["C"],"explanation":"正确答案：C。一个省只有一个省会，一个省会只属于一个省，因此是 1:1 联系。","origin":"《数据库原理及应用》总复习"},{"id":"doc-005","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":5,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"公司中有多个部门和多名职员，每个职员只能属于一个部门，一个部门可以有多名职员，职员到部门的联系类型是（ ）。","options":["一对一","一对多","多对一","多对多"],"answer":["C"],"explanation":"正确答案：C。从职工看只能到一个部门，从部门看可有多个职工，所以职工到部门是多对一。","origin":"《数据库原理及应用》总复习"},{"id":"doc-006","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":6,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"下列实体类型的联系中，属于多对多联系的是（ ）。","options":["父亲对孩子的亲生联系","省对省会的所属联系","供应商与工程项目的供货联系","班级与学生之间的关系"],"answer":["C"],"explanation":"正确答案：C。一个供应商可向多个项目供货，一个项目也可由多个供应商供货，是 M:N。","origin":"《数据库原理及应用》总复习"},{"id":"doc-007","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":7,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"学生和课程之间是典型的（ ）关系。","options":["一对一","多对一","一对多","多对多"],"answer":["D"],"explanation":"正确答案：D。一个学生可选多门课，一门课也可被多名学生选，学生与课程是典型 M:N。","origin":"《数据库原理及应用》总复习"},{"id":"doc-008","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":8,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"学生社团可以接纳多名学生参加，但每个学生只能参加一个社团，从社团到学生之间的联系类型是（ ）。","options":["一对一","多对一","一对多","多对多"],"answer":["C"],"explanation":"正确答案：C。一个社团对应多名学生，一个学生只参加一个社团，从社团到学生是 1:N。","origin":"《数据库原理及应用》总复习"},{"id":"doc-139","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":8,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"E-R图是用来表示关系模型的图形。","options":[],"answer":"错","explanation":"答案：错。E-R 图表示概念模型中的实体、属性和联系，不表示关系模型的二维表结构。","origin":"《数据库原理及应用》总复习"},{"id":"doc-021","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":21,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"关系代数中的自然连接操作是由（ ）操作组合而成 。","options":["选择和投影","选择和笛卡尔积","投影、选择、笛卡尔积","投影和笛卡尔积"],"answer":["C"],"explanation":"正确答案：C。自然连接先用笛卡尔积组合，再选择公共属性相等的元组，最后投影去掉重复公共属性。","origin":"《数据库原理及应用》总复习"},{"id":"doc-029","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":29,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"在数据库设计中，E-R模型是进行（ ）的一个主要工具。","options":["需求分析","概念设计","逻辑设计","物理设计"],"answer":["B"],"explanation":"正确答案：B。E-R 图是概念结构设计的主要工具，用于抽象实体、属性和联系。","origin":"《数据库原理及应用》总复习"},{"id":"doc-030","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":30,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"在数据库设计中，当合并局部E-R图时，学生在某一局部应用中被当做实体，而在另一局部应用中被当做属性，那么这种冲突称为（ ）。","options":["属性冲突","命名冲突","联系冲突","结构冲突"],"answer":["D"],"explanation":"正确答案：D。同一对象在一处是实体、另一处是属性，属于抽象层次不一致的结构冲突。","origin":"《数据库原理及应用》总复习"},{"id":"doc-031","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":31,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"在数据库设计中，学生的学号在某一局部应用中被定义为字符型，而在另一局部应用中被定义为整型，那么这种冲突称为（ ）。","options":["属性冲突","命名冲突","联系冲突","结构冲突"],"answer":["A"],"explanation":"正确答案：A。同一属性在不同局部模型中的类型或域定义不同，属于属性冲突。","origin":"《数据库原理及应用》总复习"},{"id":"doc-032","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":32,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"E-R图是数据库设计的工具之一，它适用于建立数据库的（ ）。","options":["概念模型","逻辑模型","结构模型","物理模型"],"answer":["A"],"explanation":"正确答案：A。E-R 图建立概念模型；转换为关系模式后才进入逻辑模型和物理实现。","origin":"《数据库原理及应用》总复习"},{"id":"doc-163","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":32,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"数据库的概念结构设计只能采用自顶向下或自底向上的方法。","options":[],"answer":"错","explanation":"答案：错。概念结构设计可采用自顶向下、自底向上、逐步扩张和混合策略等，不只两种。","origin":"《数据库原理及应用》总复习"},{"id":"doc-033","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":33,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"E-R图中的主要元素是（ ）、联系和属性。","options":["记录型","结点","实体集","表"],"answer":["C"],"explanation":"正确答案：C。E-R 图的三要素是实体集、联系和属性，分别用矩形、菱形和椭圆表示。","origin":"《数据库原理及应用》总复习"},{"id":"doc-034","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":34,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"概念结构设计是整个数据库设计的关键，它通过对用户需求进行综合、归纳与抽象，形成一个独立于具体DBMS的（ ）。","options":["数据模型","概念模型","层次模型","关系模型"],"answer":["B"],"explanation":"正确答案：B。概念结构设计的产物是独立于具体 DBMS 的概念模型，通常用 E-R 图表示。","origin":"《数据库原理及应用》总复习"},{"id":"doc-165","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":34,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"E-R图在需求分析阶段生成。","options":[],"answer":"错","explanation":"答案：错。E-R 图在概念结构设计阶段产生，不在需求分析阶段直接生成。","origin":"《数据库原理及应用》总复习"},{"id":"doc-035","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":35,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"概念设计的结果是（ ）。","options":["一个与DBMS相关的概念模式","一个与DBMS无关的概念模式","数据库系统的公用视图","数据库系统的数据词典"],"answer":["B"],"explanation":"正确答案：B。概念设计得到与 DBMS 无关的概念模式；逻辑设计才将其转换为具体数据模型。","origin":"《数据库原理及应用》总复习"},{"id":"doc-036","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":36,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"数据库概念设计的E-R方法中，用属性描述实体的特征，属性在E-R图中，用（ ）表示。","options":["矩形","四边形","菱形","椭圆形"],"answer":["D"],"explanation":"正确答案：D。实体用矩形、联系用菱形、属性用椭圆表示，主键属性通常在属性名下加下划线。","origin":"《数据库原理及应用》总复习"},{"id":"doc-167","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":36,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"命名冲突属于局部概念模式间的冲突。","options":[],"answer":"对","explanation":"答案：对。同一对象在不同局部 E-R 图中使用不同名称或同名异义，属于命名冲突。","origin":"《数据库原理及应用》总复习"},{"id":"doc-037","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":37,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"在数据库的概念设计中，最常用的数据模型是（ ）。","options":["形象模型","物理模型","逻辑模型","实体联系模型"],"answer":["D"],"explanation":"正确答案：D。概念设计面向业务语义，最常用实体-联系模型；关系模型是实现阶段的逻辑模型。","origin":"《数据库原理及应用》总复习"},{"id":"doc-168","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":37,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"值域冲突属于局部概念模式间的冲突。","options":[],"answer":"对","explanation":"答案：对。同一属性在不同局部模型中的域、类型或单位不同，属于属性冲突中的值域冲突。","origin":"《数据库原理及应用》总复习"},{"id":"doc-038","chapter":8,"chapterTitle":"第八章 E-R 图与数据库概念设计","number":38,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"在数据库设计中，在概念设计阶段可用E-R方法，其设计出的图称为（ ）。","options":["实物示意图","实用概念图","实体表示图","实体联系图"],"answer":["D"],"explanation":"正确答案：D。用 E-R 方法设计出的图称为实体-联系图，即 E-R 图。","origin":"《数据库原理及应用》总复习"},{"id":"9-01","chapter":9,"chapterTitle":"第九章 E-R 图到关系模式的转换","number":1,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"E-R 图中的一个实体通常转换为（ ）。","options":["一个属性","一个关系模式","一个外键","一个触发器"],"answer":["B"],"explanation":"实体的属性成为关系模式的属性，实体主键成为关系模式的主键。联系需要根据基数分别处理。若存在弱实体或多值属性，还要增加相应的关系模式。"},{"id":"9-02","chapter":9,"chapterTitle":"第九章 E-R 图到关系模式的转换","number":2,"title":"填空题","kind":"open","answerKind":"open","typeName":"填空","stem":"关系模式中，主键通常加 ________ 标注，外键需要注明它引用的 ________。","options":[],"answer":"下划线；父关系及属性","explanation":"考试中应写清楚“主键：×××”和“外键：××× 参照 父表(父属性)”。复合主键的每一列都要标注为主键组成部分。只写“外键：DeptID”而不说明引用对象，会丢失得分点。"},{"id":"9-03","chapter":9,"chapterTitle":"第九章 E-R 图到关系模式的转换","number":3,"title":"编程与设计题","kind":"open","answerKind":"open","typeName":"综合题","stem":"把 1:1 联系“班级-班主任”转换为关系模式。要求给出一种常用方案并说明约束。","options":[],"answer":"例如 `Class(ClassID, ClassName, TeacherID UNIQUE)`，其中 TeacherID 为外键，引用 Teacher(TeacherID)，并加 UNIQUE 约束。","explanation":"1:1 可把一方主键作为外键放入另一方，并加唯一约束，防止同一教师管理多个班级；也可单独建联系表，或业务允许时合并实体。若外键允许 NULL，可表达“暂时没有班主任”。"},{"id":"9-04","chapter":9,"chapterTitle":"第九章 E-R 图到关系模式的转换","number":4,"title":"编程与设计题","kind":"open","answerKind":"open","typeName":"综合题","stem":"将“Department 1:N Employee”转换为关系模式并标注主外键。","options":[],"answer":"`Department(DeptID PK, DeptName)`；`Employee(EmpID PK, EmpName, Salary, DeptID FK REFERENCES Department(DeptID))`。","explanation":"1:N 联系不单独建表，把“1”端主键放入“多”端作为外键。联系本身若只有从属关系而没有额外属性，不需要新增字段。员工若可暂时不属于任何部门，EmpDeptID 应允许 NULL。"},{"id":"9-05","chapter":9,"chapterTitle":"第九章 E-R 图到关系模式的转换","number":5,"title":"编程与设计题","kind":"open","answerKind":"open","typeName":"综合题","stem":"将订单与图书的 M:N“包含”联系转换为关系模式。联系属性有数量和成交单价。","options":[],"answer":"`OrderDetail(OrderID PK, ISBN PK, Quantity, UnitPrice)`，其中两列共同组成复合主键，并分别引用 Orders 和 Book。","explanation":"M:N 必须单独建表。联系表的主键通常为双方主键的组合，联系属性进入该表。若同一订单中同一 ISBN 可能因促销拆成多行，应进一步增加明细行号，否则复合主键会重复。"},{"id":"9-06","chapter":9,"chapterTitle":"第九章 E-R 图到关系模式的转换","number":6,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"M:N 联系可以直接把双方主键都塞进其中一张实体表，而不需要新建联系表。","options":[],"answer":"错","explanation":"一对多可以把一端的键放入多端，因为多端每行只对应一个父记录；多对多中任意一端都可能对应多个另一端，无法用一个普通列稳定保存多值关系，除非采用非规范的数组或拼接字符串设计。规范关系模型应为 M:N 建立独立联系表。"},{"id":"9-07","chapter":9,"chapterTitle":"第九章 E-R 图到关系模式的转换","number":7,"title":"简答题","kind":"open","answerKind":"open","typeName":"简答","stem":"1:N 联系的属性应放在哪里？M:N 联系的属性应放在哪里？","options":[],"answer":"1:N 联系的属性通常放入“多”端关系或外键所在表；M:N 联系的属性必须放入独立联系表。","explanation":"例如员工属于部门，入职部门日期可以放在员工表；学生选课成绩发生在学生与课程组合上，应放在选课联系表。判断标准是：该属性是否只描述某一对实体的组合，而不是只描述单个实体。"},{"id":"9-08","chapter":9,"chapterTitle":"第九章 E-R 图到关系模式的转换","number":8,"title":"简答题","kind":"open","answerKind":"open","typeName":"简答","stem":"多值属性和弱实体转换为关系模式时分别要注意什么？","options":[],"answer":"多值属性通常单独建表，并以实体主键加属性值等作为主键；弱实体要保留所依赖强实体的主键，并与自身区分属性组成主键。","explanation":"例如 StudentPhone(StudentID, Phone)，StudentID 是外键；OrderDetail(OrderID, ISBN, ...) 中 OrderID 来自强实体 Orders，ISBN 可作为区分订单中方记录的部分键。具体主键还取决于一条订单是否可能出现多行同 ISBN 的明细。"},{"id":"9-09","chapter":9,"chapterTitle":"第九章 E-R 图到关系模式的转换","number":9,"title":"综合设计题","kind":"open","answerKind":"open","typeName":"综合题","stem":"写出在线书店的核心关系模式，并标注主外键。","options":[],"answer":"```text\nBook(ISBN PK, Title, Price, PublishDate, Stock)\nCustomer(CustomerID PK, Name, Phone)\nOrders(OrderID PK, OrderDate, TotalAmount, CustomerID FK)\nOrderDetail(OrderID PK/FK, ISBN PK/FK, Quantity, UnitPrice)\n```","explanation":"Orders.CustomerID 引用 Customer；OrderDetail.OrderID 引用 Orders，OrderDetail.ISBN 引用 Book；OrderDetail 的复合主键为 `(OrderID, ISBN)`。如果 TotalAmount 可由明细汇总得到，它可以作为派生字段保留，但必须维护一致性。"},{"id":"9-10","chapter":9,"chapterTitle":"第九章 E-R 图到关系模式的转换","number":10,"title":"综合设计题","kind":"open","answerKind":"open","typeName":"综合题","stem":"图书馆需求中，同一读者可以多次借同一本书。请写出 Borrow 关系的推荐主键与外键。","options":[],"answer":"```text\nBorrow(BorrowID PK, ReaderID FK, ISBN FK,\n       BorrowDate, DueDate, ReturnDate)\n```","explanation":"BorrowID 唯一标识每次借阅，ReaderID 引用 Reader，ISBN 引用 Book。若业务要求同一读者在同一时刻不能重复借同一本书，可以在 ReaderID、ISBN 等字段上增加业务约束，但不应把历史记录覆盖。"},{"id":"9-11","chapter":9,"chapterTitle":"第九章 E-R 图到关系模式的转换","number":11,"title":"综合设计题","kind":"open","answerKind":"open","typeName":"综合题","stem":"关系 `OrderDetail(OrderID, ISBN, Quantity, UnitPrice)` 中，若同一订单可以多次出现同一 ISBN 的促销行，原复合主键有什么问题？如何修改？","options":[],"answer":"原复合主键会阻止同一订单同一 ISBN 出现多行。应增加明细行号 `LineNo`，使用 `(OrderID, LineNo)` 作为主键，ISBN 作为外键。","explanation":"或者使用全局唯一的明细 ID。主键必须符合真实业务粒度：如果一行代表“订单中的一条明细”，主键应标识明细行，而不只是标识订单与图书的组合。关系模型必须能保存业务允许的重复场景。"},{"id":"9-12","chapter":9,"chapterTitle":"第九章 E-R 图到关系模式的转换","number":12,"title":"填空题","kind":"open","answerKind":"open","typeName":"填空","stem":"在常见转换规则下，关系模式数量可近似按“实体数 + M:N 联系数 + 多元联系数 + 多值属性数”计算；1:1 和 1:N 联系通常 ________。","options":[],"answer":"不增加独立关系模式","explanation":"这是一般规则，不是绝对公式。若弱实体单独建模、1:1 选择单独建联系表，或教材对某些联系采用不同约定，模式数量可能变化。考试时应结合题目的转换规则和业务粒度作答，并写出主外键作为实质依据。"},{"id":"9-13","chapter":9,"chapterTitle":"第九章 E-R 图到关系模式的转换","number":13,"title":"综合设计题","kind":"open","answerKind":"open","typeName":"综合题","stem":"人力资源系统包含 Department、Employee、Project。一个员工可参加多个项目，一个项目可有多个员工，参与记录需要工时。写出关系模式。","options":[],"answer":"```text\nDepartment(DeptID PK, DeptName, Location)\nEmployee(EmpID PK, EmpName, Salary, DeptID FK)\nProject(ProjectID PK, ProjectName, Budget)\nWorksOn(EmpID PK/FK, ProjectID PK/FK, Hours)\n```","explanation":"Department 与 Employee 是 1:N，DeptID 放入 Employee；Employee 与 Project 是 M:N，WorksOn 是联系表，Hours 是联系属性。WorksOn 的复合主键为 `(EmpID, ProjectID)`，若同一员工同一项目允许多次参与记录，应再增加参与流水号。"},{"id":"9-14","chapter":9,"chapterTitle":"第九章 E-R 图到关系模式的转换","number":14,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"外键字段名必须和被引用字段名完全相同。","options":[],"answer":"错","explanation":"外键字段名可以不同，例如 `ManagerID` 引用 Employee(EmpID)，或用 `SupervisorID` 表示自反联系。真正要求是数据类型兼容、被引用列有主键或唯一约束，并且业务语义清楚。"},{"id":"9-15","chapter":9,"chapterTitle":"第九章 E-R 图到关系模式的转换","number":15,"title":"简答题","kind":"open","answerKind":"open","typeName":"简答","stem":"转换为关系模式后，为什么要立即检查 1NF、2NF 和 3NF？","options":[],"answer":"因为 E-R 转换可能留下多值属性、重复分组或非主属性之间的依赖，需要规范化来消除冗余和更新异常。","explanation":"概念模型正确不代表关系模式一定规范。例如订单表若同时保存图书名、作者等只依赖 ISBN 的属性，会产生部分依赖。规范化检查应在逻辑设计阶段完成，再结合性能需求决定是否适度反规范化。"},{"id":"9-16","chapter":9,"chapterTitle":"第九章 E-R 图到关系模式的转换","number":16,"title":"综合应用题","kind":"open","answerKind":"open","typeName":"综合题","stem":"某课程系统需求是“一个学生可选多门课，一门课可有多个学生，选课记录包含成绩”。请完成实体、联系、关系模式和主外键。","options":[],"answer":"```text\nStudent(StudentID PK, StudentName, Gender)\nCourse(CourseID PK, CourseName, Credits)\nEnrollment(StudentID PK/FK, CourseID PK/FK, Score)\n```","explanation":"Student 与 Course 是 M:N，Enrollment 是联系表，主键为 `(StudentID, CourseID)`，Score 是联系属性。若一个学生可以重修同一门课并保留多次成绩，应增加学期或选课流水号参与主键。"},{"id":"doc-216","chapter":9,"chapterTitle":"第九章 E-R 图到关系模式的转换","number":5,"title":"数据库设计综合题","kind":"open","answerKind":"open","typeName":"数据库设计综合题","stem":"学生 S 的属性为 S#、SNAME、AGE、SEX；课程 C 的属性为 C#、CNAME、TEACHER。S 与 C 之间为 M:N 联系，学生选修课程后取得 GRADE。\n\n请转换为关系模型并指出主键。","options":[],"answer":"```text\nS(S# PK, SNAME, AGE, SEX)\nC(C# PK, CNAME, TEACHER)\nSC(S# PK/FK, C# PK/FK, GRADE)\n```","explanation":"两个实体分别转换为关系模式，M:N 选课联系转换为独立关系 SC。SC 的主键由学生主键 S# 和课程主键 C# 组合而成，GRADE 是联系属性，不属于 S 或 C 单独所有。","origin":"《数据库原理及应用》总复习"},{"id":"doc-039","chapter":9,"chapterTitle":"第九章 E-R 图到关系模式的转换","number":39,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"从E-R模型向关系模型转换时，一个m：n联系转换为关系模式时，该关系模式的关键字是（ ）。","options":["M端实体的关键字","N端实体的关键字","M端实体关键字与N端实体关键字组合","重新选取其他属性"],"answer":["C"],"explanation":"正确答案：C。M:N 联系必须转换为独立关系表，主键由两端实体的主键组合而成。","origin":"《数据库原理及应用》总复习"},{"id":"doc-040","chapter":9,"chapterTitle":"第九章 E-R 图到关系模式的转换","number":40,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"从E-R图导出关系模型时，如果两实体间的联系是M：N的，下列说法中正确的是（ ）。","options":["将N方关键字和联系的属性纳入M方的属性中","将M方关键字和联系的属性纳入N方的属性中","增加一个关系表示联系，其中纳入M方和N方的关键字","在M方属性和N方的属性中均增加一个表示级别的属性"],"answer":["C"],"explanation":"正确答案：C。M:N 联系不能在任一端简单增加单值外键，必须新增联系关系并包含双方主键。","origin":"《数据库原理及应用》总复习"},{"id":"doc-041","chapter":9,"chapterTitle":"第九章 E-R 图到关系模式的转换","number":41,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"如果采用关系数据库实现应用，在数据库的逻辑设计阶段需将（ ）转换为关系数据模型。","options":["E-R模型","层次模型","关系模型","网状模型"],"answer":["A"],"explanation":"正确答案：A。逻辑设计阶段将概念设计得到的 E-R 模型转换为关系模式并规范化。","origin":"《数据库原理及应用》总复习"},{"id":"doc-042","chapter":9,"chapterTitle":"第九章 E-R 图到关系模式的转换","number":42,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"如何构造出一个合适的数据逻辑结构是（ ）主要解决的问题。","options":["物理结构设计","数据字典","逻辑结构设计","关系数据库查询"],"answer":["C"],"explanation":"正确答案：C。逻辑结构设计负责选择数据模型、转换关系模式并构造合适的数据逻辑结构。","origin":"《数据库原理及应用》总复习"},{"id":"doc-043","chapter":9,"chapterTitle":"第九章 E-R 图到关系模式的转换","number":43,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"在ER模型中，如果有3个不同的实体型，3个M：N联系，根据ER模型转换为关系模型的规则，转换为关系的数目是（ ）。","options":["4","5","6","7"],"answer":["C"],"explanation":"正确答案：C。3 个实体各转换为 1 个关系，3 个 M:N 联系各增加 1 个关系，共 6 个。","origin":"《数据库原理及应用》总复习"},{"id":"doc-044","chapter":9,"chapterTitle":"第九章 E-R 图到关系模式的转换","number":44,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"在数据库设计中，将E-R图转换成关系数据模型的过程属于（ ）。","options":["需求分析阶段","逻辑设计阶段","概念设计阶段","物理设计阶段"],"answer":["B"],"explanation":"正确答案：B。E-R 图到关系模型的转换属于逻辑结构设计，不是概念设计或物理设计。","origin":"《数据库原理及应用》总复习"},{"id":"10-01","chapter":10,"chapterTitle":"第十章 函数依赖与规范化","number":1,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"`X -> Y` 的含义是（ ）。","options":["X 和 Y 一定相等","X 的每个取值能唯一确定 Y 的一个取值","Y 的每个取值能唯一确定 X 的一个取值","X 和 Y 都没有 NULL"],"answer":["B"],"explanation":"函数依赖描述属性之间的决定关系：在一个关系中，只要两个元组的 X 值相同，它们的 Y 值就必须相同。函数依赖由业务语义决定，不能只凭某一张当前数据表是否有重复值来推断。"},{"id":"10-02","chapter":10,"chapterTitle":"第十章 函数依赖与规范化","number":2,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"函数依赖是可以仅根据当前实例中的若干行数据证明的。","options":[],"answer":"错","explanation":"当前数据恰好没有重复，不代表业务规则规定未来也不能重复。函数依赖来自现实世界语义和完整性规则。例如学号决定姓名，是由学号唯一标识学生这一业务规则决定，不是由当前表中碰巧没有重名决定。"},{"id":"10-03","chapter":10,"chapterTitle":"第十章 函数依赖与规范化","number":3,"title":"填空题","kind":"open","answerKind":"open","typeName":"填空","stem":"设 K 能函数决定关系中的所有属性，且 K 的任一真子集都不能决定全部属性，则 K 是 ________。","options":[],"answer":"候选键","explanation":"候选键兼具唯一性和极小性。能决定全部属性但不满足极小性的是超键；从一个候选键中选定用于实现的是主键；包含在任意候选键中的属性是主属性。"},{"id":"10-04","chapter":10,"chapterTitle":"第十章 函数依赖与规范化","number":4,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"给定 `R(A, B, C)`，`A -> B, B -> C`。A 的闭包 `A+` 是（ ）。","options":["`{A}`","`{A, B}`","`{A, B, C}`","`{B, C}`"],"answer":["C"],"explanation":"从 A 出发，由 `A -> B` 得到 B；再由 `B -> C` 得到 C。因此 `A+ = {A, B, C}`。闭包是求候选键和判断函数依赖是否被逻辑蕴涵的基本工具。"},{"id":"10-05","chapter":10,"chapterTitle":"第十章 函数依赖与规范化","number":5,"title":"简答题","kind":"open","answerKind":"open","typeName":"简答","stem":"在 `R(A, B, C, D)` 中，若 `A -> B`、`A -> C`、`A -> D`，A 是否是候选键？","options":[],"answer":"是。A 能决定全部属性，且 A 是单属性，不存在可去掉的真子集。","explanation":"若 A 能决定全部属性，则 A 是超键；由于 A 只有一个属性，空的属性集通常不能决定全部属性，因此 A 满足极小性，是候选键。若要确认是否还有别的候选键，仍需检查其他属性组合。"},{"id":"10-06","chapter":10,"chapterTitle":"第十章 函数依赖与规范化","number":6,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"`Enrollment(StudentID, CourseID, StudentName, Score)` 的主键为 `(StudentID, CourseID)`，且 `StudentID -> StudentName`。该关系存在（ ）。","options":["部分函数依赖","传递函数依赖","多值依赖","不存在任何依赖"],"answer":["A"],"explanation":"StudentName 只依赖复合主键的一部分 StudentID，而不是完整依赖 `(StudentID, CourseID)`，所以是部分函数依赖。应拆分为 Student 和 Enrollment，以消除学生姓名在每条选课记录中的重复。"},{"id":"10-07","chapter":10,"chapterTitle":"第十章 函数依赖与规范化","number":7,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"`Employee(EmpID, EmpName, DeptID, DeptName)` 中，`EmpID -> DeptID` 且 `DeptID -> DeptName`。DeptName 对 EmpID 存在（ ）。","options":["完全依赖","部分依赖","传递依赖","平凡依赖"],"answer":["C"],"explanation":"EmpID 决定 DeptID，DeptID 又决定 DeptName，因此 DeptName 通过 DeptID 间接依赖 EmpID。规范化为 Employee(EmpID, EmpName, DeptID) 和 Department(DeptID, DeptName)，可以减少部门名称重复和修改异常。"},{"id":"10-08","chapter":10,"chapterTitle":"第十章 函数依赖与规范化","number":8,"title":"简答题","kind":"open","answerKind":"open","typeName":"简答","stem":"数据冗余可能引起哪三类操作异常？","options":[],"answer":"插入异常、删除异常和更新异常。","explanation":"插入异常是指缺少某个无关信息时无法插入有用数据；删除异常是删除一条记录时意外丢失其他业务信息；更新异常是同一事实重复存储，修改时可能只改了一部分，造成数据不一致。规范化通过拆分关系减少这些风险。"},{"id":"10-09","chapter":10,"chapterTitle":"第十章 函数依赖与规范化","number":9,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"数据冗余越小越好，因此规范化程度越高越好。","options":[],"answer":"错","explanation":"高范式通常减少冗余和异常，但会拆出更多表，查询连接增多。实际设计常以 3NF 为基准，并结合读写比例、性能、复杂度和业务一致性要求适度反规范化。反规范化必须有明确目的和维护机制。"},{"id":"10-10","chapter":10,"chapterTitle":"第十章 函数依赖与规范化","number":10,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"关系满足 1NF 的基本要求是（ ）。","options":["每个非主属性完全依赖候选键","每个属性值都是原子值","每个决定因素都是候选键","不存在任何函数依赖"],"answer":["B"],"explanation":"1NF 要求每个属性值不可再分，即每行每列都是原子值。一个单元格中保存逗号分隔的多个电话号码不符合 1NF。2NF 进一步消除非主属性的部分依赖；3NF 消除非主属性的传递依赖。"},{"id":"10-11","chapter":10,"chapterTitle":"第十章 函数依赖与规范化","number":11,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"2NF 在 1NF 基础上主要消除（ ）。","options":["非主属性对候选键的部分函数依赖","非主属性对候选键的传递函数依赖","主属性对候选键的部分依赖","所有多值依赖"],"answer":["A"],"explanation":"2NF 关注非主属性是否完整依赖于整个候选键。若候选键是单属性，就不存在“真子集”导致的部分依赖，因此单属性候选键的关系通常自动满足 2NF。3NF 再消除非主属性的传递依赖。"},{"id":"10-12","chapter":10,"chapterTitle":"第十章 函数依赖与规范化","number":12,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"3NF 在 2NF 基础上主要消除（ ）。","options":["主属性对候选键的依赖","非主属性对候选键的传递函数依赖","外键引用","所有非空约束"],"answer":["B"],"explanation":"3NF 通常表述为：每个非主属性都完全且直接依赖于候选键，不能通过其他非主属性间接依赖。更形式化的等价表述会涉及决定因素是否为超键，或在决定因素不是超键时被决定属性是否为主属性。"},{"id":"10-13","chapter":10,"chapterTitle":"第十章 函数依赖与规范化","number":13,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"关于 BCNF，下列说法正确的是（ ）。","options":["BCNF 比 3NF 更弱","满足 BCNF 一定满足 3NF","满足 3NF 一定满足 BCNF","BCNF 只检查非主属性"],"answer":["B"],"explanation":"包含关系是 `1NF ⊃ 2NF ⊃ 3NF ⊃ BCNF`，方向表示 BCNF 最严格。BCNF 要求每个非平凡函数依赖的决定因素都是候选键或超键，不只检查非主属性。3NF 关系中可能存在决定因素不是候选键的特殊反例，因此不一定是 BCNF。"},{"id":"10-14","chapter":10,"chapterTitle":"第十章 函数依赖与规范化","number":14,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"一个关系只要没有非主属性，就一定满足 3NF。","options":[],"answer":"对","explanation":"3NF 的常见简化判断主要约束非主属性。如果所有属性都是主属性，则不存在“非主属性对码的部分或传递依赖”，通常可判定满足 3NF。但它不一定满足 BCNF，仍需检查每个非平凡函数依赖的决定因素是否为超键。"},{"id":"10-15","chapter":10,"chapterTitle":"第十章 函数依赖与规范化","number":15,"title":"综合应用题","kind":"open","answerKind":"open","typeName":"综合题","stem":"给定 `R(A, B, C, D, E)`，函数依赖为 `AB -> CDE`、`C -> E`。判断 R 是否满足 2NF、3NF，并说明理由。","options":[],"answer":"R 满足 2NF，但不满足 3NF。候选键为 AB，存在 `AB -> C` 且 `C -> E` 的传递依赖。可分解为 `R1(A, B, C, D)` 和 `R2(C, E)`。","explanation":"由 `AB+ = {A, B, C, D, E}` 可知 AB 是候选键。A 或 B 单独都不能决定 E，因此 E 对 AB 不存在部分依赖，满足 2NF。但 C 是非主属性，`AB -> C` 且 `C -> E`，使 E 通过 C 传递依赖于候选键 AB，因此不满足 3NF。该拆分的交集为 C，且 `C -> E`，可以据此判断两模式分解具有无损连接性。"},{"id":"10-16","chapter":10,"chapterTitle":"第十章 函数依赖与规范化","number":16,"title":"综合应用题","kind":"open","answerKind":"open","typeName":"综合题","stem":"将 `OrderDetail(OrderID, ISBN, Quantity, BookTitle, BookPrice)` 规范到 2NF。已知主键为 `(OrderID, ISBN)`，且 `ISBN -> BookTitle, BookPrice`。","options":[],"answer":"```text\nOrderDetail(OrderID, ISBN, Quantity)\nBook(ISBN, BookTitle, BookPrice)\n```","explanation":"BookTitle 和 BookPrice 只依赖 ISBN，不依赖完整主键，存在部分依赖。拆出 Book 后，OrderDetail 仍以 `(OrderID, ISBN)` 为主键，ISBN 作为外键引用 Book。还需继续检查 3NF，例如 BookTitle 是否又决定其他非主属性。"},{"id":"10-17","chapter":10,"chapterTitle":"第十章 函数依赖与规范化","number":17,"title":"综合应用题","kind":"open","answerKind":"open","typeName":"综合题","stem":"将 `Employee(EmpID, EmpName, DeptID, DeptName, Location)` 规范到 3NF。已知 `EmpID -> EmpName, DeptID`，`DeptID -> DeptName, Location`。","options":[],"answer":"```text\nEmployee(EmpID, EmpName, DeptID)\nDepartment(DeptID, DeptName, Location)\n```","explanation":"EmpID 是候选键，DeptName 和 Location 通过 DeptID 传递依赖于 EmpID。拆分后 Employee.DeptID 是外键，引用 Department.DeptID。若员工可暂时没有部门，DeptID 应允许 NULL。"},{"id":"10-18","chapter":10,"chapterTitle":"第十章 函数依赖与规范化","number":18,"title":"简答题","kind":"open","answerKind":"open","typeName":"简答","stem":"说明规范化的主要优点和代价。","options":[],"answer":"优点是减少冗余、降低插入删除更新异常、提高结构清晰度；代价是表数量增加、连接查询增多、某些应用逻辑变复杂。","explanation":"规范化和性能不是简单的正比关系。事务系统常在 3NF 附近取得较好平衡；分析型系统或高频读取场景可能使用星型模型、宽表、冗余汇总等反规范化设计，但必须有批次刷新或触发器维护一致性。"},{"id":"doc-218","chapter":10,"chapterTitle":"第十章 函数依赖与规范化","number":7,"title":"范式判断题","kind":"open","answerKind":"open","typeName":"范式判断题","stem":"判断下列关系最高满足第几范式，并说明理由：\n\n（1）职员(职员代码, 职员姓名, 部门代码, 部门负责人代码)，主键为职员代码。\n（2）项目(项目代码, 职员代码, 职员所属部门, 累计工作时间)，主键为（项目代码，职员代码）。\n（3）学生(学号, 身份证号, 姓名, 年龄, 班级号)，主键为学号，身份证号也是候选键。","options":[],"answer":"（1）满足 2NF，不满足 3NF。 \n（2）最高满足 1NF，不满足 2NF。 \n（3）满足 3NF，但不一定满足 BCNF。","explanation":"（1）单属性主键不存在部分依赖，但存在职员代码→部门代码→部门负责人代码的传递依赖。（2）主键为复合键，而职员代码单独决定职员所属部门，存在部分依赖。（3）学号和身份证号都是候选键，所有属性均为主属性；3NF 的非主属性传递依赖条件不再构成违反，但身份证号→学号且身份证号是候选键，需进一步检查 BCNF。","origin":"《数据库原理及应用》总复习"},{"id":"doc-169","chapter":10,"chapterTitle":"第十章 函数依赖与规范化","number":38,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"若R.A→R.B，R.B→R.C, 则R. A→R.C。","options":[],"answer":"对","explanation":"答案：对。函数依赖具有传递性：若 A→B 且 B→C，则 A→C。","origin":"《数据库原理及应用》总复习"},{"id":"doc-045","chapter":10,"chapterTitle":"第十章 函数依赖与规范化","number":45,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"规范化理论是关系数据库进行逻辑设计的理论依据，根据这个理论，关系数据库中的关系必须满足：其每个属性都是（ ）。","options":["互不相关的","不可分解的","长度可变的","互相关联的"],"answer":["B"],"explanation":"正确答案：B。关系模型要求每个分量都是原子值，即属性不可再分，这是 1NF 的基本要求。","origin":"《数据库原理及应用》总复习"},{"id":"doc-046","chapter":10,"chapterTitle":"第十章 函数依赖与规范化","number":46,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"关系规范化中的删除操作异常是指（ ）","options":["不该删除的数据被删除","不该插入的数据被插入","应该删除的数据未被删除","应该插入的数据未被插入"],"answer":["A"],"explanation":"正确答案：A。删除异常是删除一条记录时附带丢失了本应保留的其他信息。","origin":"《数据库原理及应用》总复习"},{"id":"doc-047","chapter":10,"chapterTitle":"第十章 函数依赖与规范化","number":47,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"关系模式中，满足2NF的模式（ ）。","options":["可能是1NF","必定是1NF","必定是3NF","必定是BCNF"],"answer":["B"],"explanation":"正确答案：B。2NF 以 1NF 为前提，所以满足 2NF 必定满足 1NF，但不一定满足 3NF。","origin":"《数据库原理及应用》总复习"},{"id":"doc-048","chapter":10,"chapterTitle":"第十章 函数依赖与规范化","number":48,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"关系模式至少应满足（ ）才允许存在于关系数据库中。","options":["1NF","2NF","3NF","BCNF"],"answer":["A"],"explanation":"正确答案：A。关系模式至少应满足 1NF，所有属性值原子；3NF 是良好设计目标，不是“可用”的最低条件。","origin":"《数据库原理及应用》总复习"},{"id":"doc-049","chapter":10,"chapterTitle":"第十章 函数依赖与规范化","number":49,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"关系数据库规范化是为解决关系数据库中（ ）问题而引入的。","options":["插入、删除异常和数据冗余","提高查询速度","减少数据操作的复杂性","保证数据的安全性和完整性"],"answer":["A"],"explanation":"正确答案：A。规范化主要减少数据冗余并消除插入、删除和更新异常。","origin":"《数据库原理及应用》总复习"},{"id":"doc-050","chapter":10,"chapterTitle":"第十章 函数依赖与规范化","number":50,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"规范化过程主要为克服数据库逻辑结构中的插入异常、删除异常以及（ ）的缺陷。","options":["数据的不一致性","结构不合理","冗余度大","数据丢失"],"answer":["C"],"explanation":"正确答案：C。规范化的直接目标是降低冗余，从而减少插入、删除和更新异常。","origin":"《数据库原理及应用》总复习"},{"id":"doc-051","chapter":10,"chapterTitle":"第十章 函数依赖与规范化","number":51,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"由于关系模式设计不当所引起的插入异常指的是（ ）。","options":["两个事务并发地对同一关系进行插入而造成数据库不一致","由于码值的一部分为空而不能将有用的信息作为一个元组插入到关系中","未经授权的用户对关系进行了插入","插入操作因为违反完整性约束条件而遭到拒绝"],"answer":["B"],"explanation":"正确答案：B。插入异常通常是因为缺少主键的一部分，导致有用信息无法独立插入。","origin":"《数据库原理及应用》总复习"},{"id":"doc-052","chapter":10,"chapterTitle":"第十章 函数依赖与规范化","number":52,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"在关系模式中，如果属性A和B存在1对1的联系，则说（ ）。","options":["A→B","B→A","A←→B","以上都不是"],"answer":["C"],"explanation":"正确答案：C。A 与 B 为一对一联系意味着 A 决定 B 且 B 决定 A，即 A↔B。","origin":"《数据库原理及应用》总复习"},{"id":"11-01","chapter":11,"chapterTitle":"第十一章 存储过程与游标","number":1,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"存储过程是一组（ ）。","options":["保存在数据库中的 SQL 语句集合","只能返回一行的数据表","自动生成索引的工具","只存在于客户端程序中的代码"],"answer":["A"],"explanation":"存储过程是事先定义并保存于数据库中的 SQL 语句和控制逻辑集合，可以接受参数、返回结果集或输出参数。不同 DBMS 的语法、编译缓存和权限模型存在差异，但“数据库内可复用的过程”是共同核心。"},{"id":"11-02","chapter":11,"chapterTitle":"第十一章 存储过程与游标","number":2,"title":"多项选择题","kind":"choice","answerKind":"choice","typeName":"多项选择","stem":"使用存储过程的优点包括（ ）。","options":["封装业务逻辑，提高复用性","减少客户端与数据库之间的往返传输","便于通过权限控制限制直接访问基础表","任何情况下都比单条 SQL 更快"],"answer":["A","B","C"],"explanation":"D 过于绝对。复杂存储过程可能难以调试、移植和版本管理，也可能因执行计划或流程控制产生性能问题。简单查询直接执行有时更清晰。应根据业务复杂度、调用频率和团队维护能力选择。"},{"id":"11-03","chapter":11,"chapterTitle":"第十一章 存储过程与游标","number":3,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"存储过程一旦创建，就只能执行一条 `SELECT` 语句。","options":[],"answer":"错","explanation":"存储过程可包含多条 SQL、变量声明、条件判断、循环、异常处理和事务控制。它还可以有输入参数、输出参数或返回结果集。复杂度应按业务需要控制，避免把过多逻辑堆在一个巨大过程中。"},{"id":"11-04","chapter":11,"chapterTitle":"第十一章 存储过程与游标","number":4,"title":"简答题","kind":"open","answerKind":"open","typeName":"简答","stem":"SQL Server 存储过程中输入参数、输出参数分别用什么关键字表示？","options":[],"answer":"输入参数可直接声明参数名和类型，默认按输入处理；输出参数在类型后写 `OUTPUT`。MySQL 中使用 `IN`、`OUT`、`INOUT`。","explanation":"SQL Server 的 `@EmpName NVARCHAR(50)` 默认是输入参数，`@DeptName NVARCHAR(50) OUTPUT` 是输出参数。调用时输出参数需要用变量接收，并再次标注 `OUTPUT`。不要混用 MySQL 的 `CALL 过程(实参, @out)` 语法。"},{"id":"11-05","chapter":11,"chapterTitle":"第十一章 存储过程与游标","number":5,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"编写 SQL Server 存储过程 `pro_get_emp_by_dept`，输入部门名称，返回该部门员工号、姓名和工资。","options":[],"answer":"```sql\nCREATE PROCEDURE pro_get_emp_by_dept\n    @DeptName NVARCHAR(50)\nAS\nBEGIN\n    SELECT e.EmpID, e.EmpName, e.Salary\n    FROM Employee e\n    JOIN Department d\n      ON e.DeptID = d.DeptID\n    WHERE d.DeptName = @DeptName;\nEND;\n```","explanation":"`@DeptName` 是输入参数，过程内部可直接在 WHERE 中使用。返回结果集不需要 `RETURN` 逐行返回；`SELECT` 语句本身会把结果集发送给调用方。若部门名称不唯一，按名称过滤可能返回多个部门的数据，实际设计应优先按 DeptID 查询。"},{"id":"11-06","chapter":11,"chapterTitle":"第十一章 存储过程与游标","number":6,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"编写 SQL Server 存储过程，输入员工姓名，输出部门名称。","options":[],"answer":"```sql\nCREATE PROCEDURE pro_get_emp_dept\n    @EmpName NVARCHAR(50),\n    @DeptName NVARCHAR(50) OUTPUT\nAS\nBEGIN\n    SELECT @DeptName = d.DeptName\n    FROM Employee e\n    JOIN Department d\n      ON e.DeptID = d.DeptID\n    WHERE e.EmpName = @EmpName;\nEND;\n```","explanation":"`OUTPUT` 参数用于把单个值带回调用方。若姓名对应多条员工记录，`SELECT ... INTO 变量` 的行为会依 DBMS 而不同，可能取任意一条或报错。业务上通常应使用唯一员工号作为输入，或先判断是否存在重复。"},{"id":"11-07","chapter":11,"chapterTitle":"第十一章 存储过程与游标","number":7,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"调用上题过程，输入“张三”，接收并显示部门名称。","options":[],"answer":"```sql\nDECLARE @result NVARCHAR(50);\n\nEXEC pro_get_emp_dept\n    @EmpName = N'张三',\n    @DeptName = @result OUTPUT;\n\nSELECT @result AS DeptName;\n```","explanation":"SQL Server 用 `EXEC` 调用，输出参数变量需在调用处也写 `OUTPUT`。若查询没有匹配行，变量可能保持原值或为 NULL，具体取决于初始化情况。稳妥的过程应先设置默认值，并显式处理“未找到”的业务情况。"},{"id":"11-08","chapter":11,"chapterTitle":"第十一章 存储过程与游标","number":8,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"编写 SQL Server 存储过程，输入员工号。若工资不低于 8000 返回“高工资”，否则返回“普通工资”。","options":[],"answer":"```sql\nCREATE PROCEDURE pro_check_salary\n    @EmpID INT\nAS\nBEGIN\n    DECLARE @salary DECIMAL(10,2);\n\n    SELECT @salary = Salary\n    FROM Employee\n    WHERE EmpID = @EmpID;\n\n    IF @salary >= 8000\n        SELECT N'高工资' AS Result;\n    ELSE\n        SELECT N'普通工资' AS Result;\nEND;\n```","explanation":"先声明变量，再通过 SELECT 把查询结果赋给变量，然后用 IF 判断。若员工不存在，`@salary` 为 NULL，比较结果为未知，通常走 ELSE 分支。实际过程应增加存在性判断和不在简单 IF 中误用 NULL 的处理。"},{"id":"11-09","chapter":11,"chapterTitle":"第十一章 存储过程与游标","number":9,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"SQL Server 的局部变量通常以 `@` 开头。","options":[],"answer":"对","explanation":"T-SQL 中 `DECLARE @salary DECIMAL(10,2);` 声明局部变量，`SELECT @salary = Salary ...` 赋值。MySQL 的局部变量可以在过程中用 `DECLARE` 声明，不以 `@` 开头；会话变量可用 `@name`，两者语义层级不同。"},{"id":"11-10","chapter":11,"chapterTitle":"第十一章 存储过程与游标","number":10,"title":"简答题","kind":"open","answerKind":"open","typeName":"简答","stem":"SQL Server 中 `RETURN` 和结果集有什么区别？","options":[],"answer":"`RETURN` 通常返回整数状态码，供调用方判断执行结果；SELECT 结果集返回表格数据。需要返回单个业务值时，也可以使用 OUTPUT 参数。","explanation":"存储过程的返回值不应被误认为函数返回值。`RETURN 0` 常表示成功，非零值表示自定义状态。调用方用 `EXEC @rc = 过程名 ...` 接收状态码；业务数据仍应通过结果集或 OUTPUT 参数返回。"},{"id":"11-11","chapter":11,"chapterTitle":"第十一章 存储过程与游标","number":11,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"编写 MySQL 无参数存储过程 `get_emp_count`，返回员工人数。","options":[],"answer":"```sql\nDELIMITER //\nCREATE PROCEDURE get_emp_count()\nBEGIN\n    SELECT COUNT(*) AS total\n    FROM Employee;\nEND //\nDELIMITER ;\n\nCALL get_emp_count();\n```","explanation":"MySQL 客户端使用 `DELIMITER` 临时改变语句结束符，避免过程内部的 `;` 提前结束 CREATE PROCEDURE。过程创建完成后要把分隔符改回 `;`。`CALL` 是 MySQL 的调用方式，对应 SQL Server 的 `EXEC`。"},{"id":"11-12","chapter":11,"chapterTitle":"第十一章 存储过程与游标","number":12,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"MySQL 存储过程中，参数方向通常不包括（ ）。","options":["`IN`","`OUT`","`INOUT`","`OUTPUT`"],"answer":["D"],"explanation":"MySQL 使用 `IN`、`OUT`、`INOUT`；SQL Server 使用 `OUTPUT`。混用会导致语法错误或流程不匹配。考试时要先看题目指定环境，再决定采用 T-SQL 还是 MySQL 写法。"},{"id":"11-13","chapter":11,"chapterTitle":"第十一章 存储过程与游标","number":13,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"游标的主要用途是（ ）。","options":["对查询结果逐行处理","自动生成主键","对整个表建立聚集索引","替代所有聚合查询"],"answer":["A"],"explanation":"游标把查询结果组织成可逐行提取的集合，适合必须按行执行复杂逻辑的场景。但游标通常比集合操作慢，能使用 UPDATE、JOIN、聚合或窗口函数完成的任务，应优先考虑集合方式。"},{"id":"11-14","chapter":11,"chapterTitle":"第十一章 存储过程与游标","number":14,"title":"简答题","kind":"open","answerKind":"open","typeName":"简答","stem":"写出一条 SQL Server 显式游标的基本执行顺序。","options":[],"answer":"声明游标，打开游标，循环提取数据并处理，关闭游标，释放游标。","explanation":"典型语句为 `DECLARE ... CURSOR FOR ...`、`OPEN`、`FETCH NEXT`、循环、`CLOSE`、`DEALLOCATE`。MySQL 中通常用 `DECLARE ... CURSOR FOR`、`OPEN`、`FETCH ... INTO`、`CLOSE`，并用 NOT FOUND 处理器控制循环。"},{"id":"11-15","chapter":11,"chapterTitle":"第十一章 存储过程与游标","number":15,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"使用 SQL Server 游标逐行打印员工姓名和工资。","options":[],"answer":"```sql\nDECLARE @empName NVARCHAR(50);\nDECLARE @salary DECIMAL(10,2);\n\nDECLARE cur_emp CURSOR FOR\nSELECT EmpName, Salary\nFROM Employee;\n\nOPEN cur_emp;\n\nFETCH NEXT FROM cur_emp\nINTO @empName, @salary;\n\nWHILE @@FETCH_STATUS = 0\nBEGIN\n    PRINT @empName + N' ' + CAST(@salary AS NVARCHAR(20));\n\n    FETCH NEXT FROM cur_emp\n    INTO @empName, @salary;\nEND;\n\nCLOSE cur_emp;\nDEALLOCATE cur_emp;\n```","explanation":"`FETCH` 的列顺序必须与游标查询中的列顺序一致。`@@FETCH_STATUS = 0` 表示成功取到一行。循环中必须再次 FETCH，否则会无限处理第一行。处理完成后关闭并释放游标。"},{"id":"11-16","chapter":11,"chapterTitle":"第十一章 存储过程与游标","number":16,"title":"简答题","kind":"open","answerKind":"open","typeName":"简答","stem":"存储过程、自定义函数和触发器的主要区别是什么？","options":[],"answer":"存储过程通过显式调用执行，可有多条 SQL 和输出参数；函数通常用于计算并返回值；触发器由表上的 DML 事件自动执行。","explanation":"存储过程适合封装业务流程；函数常用于表达式计算，并能嵌入查询；触发器用于自动维护完整性、日志和派生字段。触发器应保持简短、可预测，避免复杂业务链和递归调用。"},{"id":"doc-325","chapter":11,"chapterTitle":"第十一章 存储过程与游标","number":102,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n功能相同的存储过程和存储函数有什么不同？","options":[],"answer":"存储过程通过 CALL/EXEC 调用，可有 IN、OUT、INOUT 参数；函数通常在表达式中调用并返回一个值。","explanation":"函数常用于可嵌入 SELECT 的计算；存储过程更适合封装多语句业务流程。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-326","chapter":11,"chapterTitle":"第十一章 存储过程与游标","number":103,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n如何在不影响现有权限的情况下修改存储过程？","options":[],"answer":"修改参数或特性可优先使用 ALTER PROCEDURE；若 MySQL 需要改过程体，通常要 DROP 后重建，并保留 DEFINER 及重新确认相关 EXECUTE 权限。","explanation":"不同 DBMS 对例程修改支持不同，不能假定所有属性都能原地修改。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-113","chapter":11,"chapterTitle":"第十一章 存储过程与游标","number":113,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"下面选项中不属于存储过程的优点的是（ ）。","options":["增强代码的重用性和共享性","可以运行加快速度，减少网络流量","可以作为安全性机制","编辑简单"],"answer":["D"],"explanation":"正确答案：D。存储过程可复用、减少网络传输并作为权限控制边界；“编辑简单”不是其普遍优点。","origin":"《数据库原理及应用》总复习"},{"id":"doc-339","chapter":11,"chapterTitle":"第十一章 存储过程与游标","number":116,"title":"MySQL 操作题","kind":"open","answerKind":"open","typeName":"MySQL 操作题","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n编写存储过程和函数：查询指定班级学生资料；列出不及格选课情况；按班级号输入查询学生；按课程号输出课程总分；按学生平均分返回成绩等级。","options":[],"answer":"```sql\nDELIMITER //\n\nCREATE PROCEDURE proc_3(IN classno_tmp VARCHAR(10))\nBEGIN\n    SELECT sno, sname, ssex, sbirthday, classno\n    FROM student\n    WHERE classno = classno_tmp;\nEND//\n\nCREATE PROCEDURE proc_4(\n    IN cno_tmp VARCHAR(10),\n    OUT sum_degree DECIMAL(10,2)\n)\nBEGIN\n    SELECT SUM(degree) INTO sum_degree\n    FROM sc\n    WHERE cno = cno_tmp;\nEND//\n\nCREATE FUNCTION func_5(stu_no CHAR(10))\nRETURNS VARCHAR(20)\nREADS SQL DATA\nBEGIN\n    DECLARE avg_score DECIMAL(6,2);\n    SELECT AVG(degree) INTO avg_score\n    FROM sc\n    WHERE sno = stu_no;\n    RETURN CASE\n        WHEN avg_score >= 90 THEN '该生成绩优秀'\n        WHEN avg_score >= 80 THEN '该生成绩良好'\n        WHEN avg_score >= 60 THEN '该生成绩合格'\n        ELSE '该生成绩不及格'\n    END;\nEND//\n\nDELIMITER ;\n\nCALL proc_3('20070303');\nCALL proc_4('C01', @sum_degree);\nSELECT @sum_degree;\nSELECT func_5('2007030301');\n```","explanation":"输出参数必须使用 SELECT ... INTO 或 SET 赋值，原文档只写 SELECT SUM 并不会把结果赋给 OUT 参数。函数必须声明 RETURNS 类型并使用 RETURN 返回单个值。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-340","chapter":11,"chapterTitle":"第十一章 存储过程与游标","number":117,"title":"MySQL 操作题","kind":"open","answerKind":"open","typeName":"MySQL 操作题","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查看 proc_1～proc_4 和 func_1～func_5 的状态与定义；修改过程或函数的读写特性；删除指定过程和函数。","options":[],"answer":"```sql\nSHOW PROCEDURE STATUS LIKE 'proc\\_%';\nSHOW FUNCTION STATUS LIKE 'func\\_%';\nSHOW CREATE PROCEDURE proc_2;\nSHOW CREATE FUNCTION func_5;\n\nSELECT routine_name, routine_type, routine_definition\nFROM information_schema.routines\nWHERE routine_schema = DATABASE();\n\nALTER PROCEDURE proc_1\nMODIFIES SQL DATA\nSQL SECURITY INVOKER;\n\nALTER FUNCTION func_5\nREADS SQL DATA\nCOMMENT 'FUNCTION';\n\nDROP PROCEDURE IF EXISTS proc_1;\nDROP FUNCTION IF EXISTS func_1;\n```","explanation":"ALTER PROCEDURE/FUNCTION 主要修改特性，不直接改写过程体。若要改变过程体，通常需按目标 DBMS 的规则重建，并保留 DEFINER 和相关执行权限。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-341","chapter":11,"chapterTitle":"第十一章 存储过程与游标","number":118,"title":"MySQL 操作题","kind":"open","answerKind":"open","typeName":"MySQL 操作题","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n使用图形工具创建查询某班学生资料的存储过程，修改存储过程以查询某班男生，并查看、删除指定过程与函数。","options":[],"answer":"等价 SQL 重点是先保存过程定义，再用 ALTER 修改特性或重新创建过程体：\n\n```sql\nCREATE PROCEDURE proc_class_boys(IN p_classno VARCHAR(10))\nSELECT sno, sname, ssex, sbirthday, classno\nFROM student\nWHERE classno = p_classno AND ssex = '男';\n\nDROP PROCEDURE IF EXISTS proc_5;\nDROP FUNCTION IF EXISTS func_5;\n```","explanation":"图形工具中的创建、修改和删除，最终仍对应 DDL 操作。删改前应先用 SHOW CREATE 保存定义，避免丢失业务逻辑。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"12-01","chapter":12,"chapterTitle":"第十二章 触发器","number":1,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"触发器的主要特征是（ ）。","options":["必须由用户显式调用","在指定 DML 事件发生时自动执行","只能执行 SELECT","只能创建一个"],"answer":["B"],"explanation":"触发器绑定在表或视图上，当 INSERT、UPDATE 或 DELETE 发生时自动执行。它与需要显式调用的存储过程不同。一个表可以按事件和时机创建多个触发器，但要注意执行顺序、递归和性能。"},{"id":"12-02","chapter":12,"chapterTitle":"第十二章 触发器","number":2,"title":"多项选择题","kind":"choice","answerKind":"choice","typeName":"多项选择","stem":"触发器通常可以响应的事件包括（ ）。","options":["`INSERT`","`UPDATE`","`DELETE`","`SELECT`"],"answer":["A","B","C"],"explanation":"基础课程中的 DML 触发器主要响应插入、更新和删除。某些 DBMS 提供登录触发器、DDL 触发器或审计触发器，但普通表触发器不通过 SELECT 自动执行。考试时按题目指定的数据库类型作答。"},{"id":"12-03","chapter":12,"chapterTitle":"第十二章 触发器","number":3,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"SQL Server 的 `AFTER INSERT` 触发器在原 INSERT 语句成功之后执行。","options":[],"answer":"对","explanation":"AFTER 触发器在触发语句完成后执行，`inserted` 虚拟表中保存新插入的行。如果触发器内部发生错误，通常会使整个语句或事务回滚。INSTEAD OF 触发器则替代原操作执行。"},{"id":"12-04","chapter":12,"chapterTitle":"第十二章 触发器","number":4,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"SQL Server 中，用于保存 INSERT 后新行的虚拟表是（ ）。","options":["`deleted`","`inserted`","`updated`","`new`"],"answer":["B"],"explanation":"`inserted` 保存 INSERT 的新行以及 UPDATE 后的新行；`deleted` 保存 DELETE 的旧行以及 UPDATE 前的旧行。SQL Server 没有像 MySQL 一样直接使用 `NEW` 和 `OLD` 行级引用，而是通过这两个虚拟表按集合处理。"},{"id":"12-05","chapter":12,"chapterTitle":"第十二章 触发器","number":5,"title":"多项选择题","kind":"choice","answerKind":"choice","typeName":"多项选择","stem":"关于 `inserted` 和 `deleted`，下列说法正确的是（ ）。","options":["INSERT 触发器通常使用 `inserted`","DELETE 触发器通常使用 `deleted`","UPDATE 触发器可同时使用 `inserted` 和 `deleted`","SELECT 触发器必须同时使用两者"],"answer":["A","B","C"],"explanation":"INSERT 只有新行，DELETE 只有旧行，UPDATE 同时有更新前和更新后的数据。SQL Server 中这两个表可能包含多行，因此触发器不能假设一次只影响一行。D 错误，普通 SELECT 不触发这类 DML 触发器。"},{"id":"12-06","chapter":12,"chapterTitle":"第十二章 触发器","number":6,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"创建 SQL Server 触发器：员工表插入新员工后，把员工号和当前时间写入 `EmployeeLog(EmpID, ActionTime)`。","options":[],"answer":"```sql\nCREATE TRIGGER trg_emp_insert_log\nON Employee\nAFTER INSERT\nAS\nBEGIN\n    INSERT INTO EmployeeLog (EmpID, ActionTime)\n    SELECT EmpID, GETDATE()\n    FROM inserted;\nEND;\n```","explanation":"触发器从 `inserted` 表按集合读取新员工，不写“只取第一行”。一次 INSERT 可能插入多行，如果使用单变量 SELECT 赋值，可能丢失其他行。日志表字段类型应与被记录字段兼容。"},{"id":"12-07","chapter":12,"chapterTitle":"第十二章 触发器","number":7,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"图书表 Book 有 `ISBN` 和 `Stock`。创建订单明细插入后的 SQL Server 触发器，按插入数量扣减库存。","options":[],"answer":"```sql\nCREATE TRIGGER trg_orderdetail_insert\nON OrderDetail\nAFTER INSERT\nAS\nBEGIN\n    UPDATE b\n    SET b.Stock = b.Stock - i.Quantity\n    FROM Book b\n    JOIN inserted i\n      ON b.ISBN = i.ISBN;\nEND;\n```","explanation":"题目示例默认同一 ISBN 在一次插入中只出现一条。如果一次 INSERT 可能包含同一 ISBN 的多行，上述 UPDATE 的 JOIN 结果可能使语义不明确，应该先按 ISBN 汇总 inserted 中的数量，再更新 Book。触发器必须按集合处理。"},{"id":"12-08","chapter":12,"chapterTitle":"第十二章 触发器","number":8,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"创建订单明细删除后的 SQL Server 触发器，把删除数量加回图书库存。","options":[],"answer":"```sql\nCREATE TRIGGER trg_orderdetail_delete\nON OrderDetail\nAFTER DELETE\nAS\nBEGIN\n    UPDATE b\n    SET b.Stock = b.Stock + d.Quantity\n    FROM Book b\n    JOIN deleted d\n      ON b.ISBN = d.ISBN;\nEND;\n```","explanation":"DELETE 触发器使用 `deleted` 保存被删除行。和插入触发器一样，应按集合思维考虑多行删除以及同一 ISBN 多行的情况。库存恢复应避免重复执行，例如触发器被重复触发或业务层也再次恢复。"},{"id":"12-09","chapter":12,"chapterTitle":"第十二章 触发器","number":9,"title":"简答题","kind":"open","answerKind":"open","typeName":"简答","stem":"UPDATE 触发器怎样取得修改前后的工资？","options":[],"answer":"SQL Server 中 `deleted.Salary` 表示修改前，`inserted.Salary` 表示修改后；MySQL 中通常使用 `OLD.Salary` 和 `NEW.Salary`。","explanation":"触发器可比较新旧值，判断是否修改了工资，再写入审计日志或执行后续逻辑。SQL Server 应按集合处理，因为一条 UPDATE 可能影响多行，应避免写只处理一行的变量逻辑。"},{"id":"12-10","chapter":12,"chapterTitle":"第十二章 触发器","number":10,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"创建 SQL Server 触发器：员工工资被修改后，把员工号、旧工资、新工资和当前时间写入 `SalaryLog`。","options":[],"answer":"```sql\nCREATE TRIGGER trg_salary_update_log\nON Employee\nAFTER UPDATE\nAS\nBEGIN\n    INSERT INTO SalaryLog\n        (EmpID, OldSalary, NewSalary, ChangeTime)\n    SELECT d.EmpID, d.Salary, i.Salary, GETDATE()\n    FROM deleted d\n    JOIN inserted i\n      ON d.EmpID = i.EmpID\n    WHERE d.Salary <> i.Salary\n       OR d.Salary IS NULL\n       OR i.Salary IS NULL;\nEND;\n```","explanation":"`WHERE` 只记录真正变化的行，并兼容 NULL 的新旧值。若旧值和新值都为 NULL，不应记录；条件中通过 IS NULL 处理普通的 `<>` 比较。实际还需要考虑触发器权限和日志表约束。"},{"id":"12-11","chapter":12,"chapterTitle":"第十二章 触发器","number":11,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"SQL Server 触发器中可以假设一次 INSERT 只插入一行，因此可以直接把 inserted 表赋给单个变量。","options":[],"answer":"错","explanation":"一次 DML 可能影响多行，`inserted` 和 `deleted` 是集合。若写成只处理一行的变量逻辑，可能只处理任意一行或产生错误结果。正确做法是用 INSERT ... SELECT、UPDATE ... FROM、MERGE 或集合运算处理全部行。"},{"id":"12-12","chapter":12,"chapterTitle":"第十二章 触发器","number":12,"title":"简答题","kind":"open","answerKind":"open","typeName":"简答","stem":"触发器错误为什么可能导致原始 INSERT 操作失败或回滚？","options":[],"answer":"触发器与触发它的 DML 处于同一事务语义中；触发器报错或产生不可恢复错误时，数据库通常会回滚整个语句或事务。","explanation":"这正是触发器可以用来强制复杂业务规则的原因，也是风险所在。触发器执行耗时、抛出异常或嵌套触发都会影响主业务。应避免在触发器中执行不可控的外部操作和长时间查询。"},{"id":"12-13","chapter":12,"chapterTitle":"第十二章 触发器","number":13,"title":"判断题","kind":"judge","answerKind":"judge","typeName":"判断","stem":"触发器可能级联触发其他触发器，因此要注意递归和嵌套。","options":[],"answer":"对","explanation":"触发器修改其他表时可能触发那些表上的触发器；某些 DBMS 也允许表上的触发器再次影响自身或其他对象。应设置递归触发选项并限制调用深度，防止无限循环和不可预测的事务链。"},{"id":"12-14","chapter":12,"chapterTitle":"第十二章 触发器","number":14,"title":"简答题","kind":"open","answerKind":"open","typeName":"简答","stem":"为什么 MySQL 触发器通常不能直接操作触发它的同一张表？","options":[],"answer":"为避免触发器再次触发自身造成递归或不确定行为，MySQL 限制触发器直接修改定义它的表。","explanation":"若业务确实需要更新同一张表的冗余字段，通常应使用 `BEFORE` 行级触发器指定 `NEW` 值，或改由应用层、存储过程、批处理维护。不同 DBMS 的限制不同，考试要按题目指定环境作答。"},{"id":"12-15","chapter":12,"chapterTitle":"第十二章 触发器","number":15,"title":"单项选择题","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"触发器与存储过程的主要区别是（ ）。","options":["触发器必须手工调用，存储过程自动执行","存储过程通常显式调用，触发器由 DML 事件自动执行","触发器不能包含 SQL","存储过程只能有一个参数"],"answer":["B"],"explanation":"存储过程通过 `EXEC` 或 `CALL` 触发；触发器在指定 DML 事件上自动运行。函数通常通过表达式调用。三者的权限、返回方式和事务影响不同。"},{"id":"12-16","chapter":12,"chapterTitle":"第十二章 触发器","number":16,"title":"综合编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"订单明细插入后需要更新订单总金额并扣减库存。请说明触发器应如何设计，避免多行插入问题。","options":[],"answer":"先按订单号和 ISBN 汇总 `inserted` 的数量，再分别更新订单总金额和图书库存；更新时使用集合 SQL，不要逐个假设单行。","explanation":"可先创建按 `OrderID` 汇总的派生表计算新增金额，再更新 Orders；按 `ISBN` 汇总数量后更新 Book。具体金额计算还取决于是否使用 UnitPrice。一个触发器职责过多会增加维护难度，也可拆成两个职责清晰的触发器，但必须保证事务一致性和执行顺序可预测。"},{"id":"doc-196","chapter":12,"chapterTitle":"第十二章 触发器","number":65,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"MySQL 触发器只能在 DML 操作之前执行。","options":[],"answer":"错","explanation":"答案：错。MySQL 支持 BEFORE 和 AFTER 触发器，并非只能在 DML 操作之前执行。","origin":"《数据库原理及应用》总复习"},{"id":"doc-197","chapter":12,"chapterTitle":"第十二章 触发器","number":66,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"数据库触发器是计算机硬件。","options":[],"answer":"错","explanation":"答案：错。触发器是存储在数据库中的程序对象，不是计算机硬件。","origin":"《数据库原理及应用》总复习"},{"id":"doc-198","chapter":12,"chapterTitle":"第十二章 触发器","number":67,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"触发器像存储过程一样必须由用户显式调用。","options":[],"answer":"错","explanation":"答案：错。触发器由对应 DML 事件自动执行，不需要像存储过程那样显式调用。","origin":"《数据库原理及应用》总复习"},{"id":"doc-199","chapter":12,"chapterTitle":"第十二章 触发器","number":68,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"触发器执行出错时，原始 DML 语句通常会被取消或回滚。","options":[],"answer":"对","explanation":"答案：对。触发器执行出错时，数据库通常会取消或回滚触发它的 DML 语句。","origin":"《数据库原理及应用》总复习"},{"id":"doc-200","chapter":12,"chapterTitle":"第十二章 触发器","number":69,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"触发器主要是通过表操作事件进行触发而被执行的。","options":[],"answer":"对","explanation":"答案：对。触发器主要绑定 INSERT、UPDATE、DELETE 等表操作事件并自动执行。","origin":"《数据库原理及应用》总复习"},{"id":"doc-201","chapter":12,"chapterTitle":"第十二章 触发器","number":70,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"删除表时，表中的触发器不被同时删除。","options":[],"answer":"错","explanation":"答案：错。表被删除时，其上的触发器通常随表一起删除。","origin":"《数据库原理及应用》总复习"},{"id":"doc-202","chapter":12,"chapterTitle":"第十二章 触发器","number":71,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"视图具有与表相同的功能，在视图上也可以创建触发器。","options":[],"answer":"错","explanation":"答案：错。MySQL 触发器只能定义在基本表上，不能定义在普通视图上。","origin":"《数据库原理及应用》总复习"},{"id":"doc-327","chapter":12,"chapterTitle":"第十二章 触发器","number":104,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n能否在当前数据库中为其他数据库的表创建触发器？","options":[],"answer":"触发器必须与目标表位于同一个数据库。可以在语句中显式写其他数据库名创建该库表的触发器，前提是用户拥有相应 TRIGGER 权限。","explanation":"触发器不能脱离表独立存在，表被删除时触发器也随之删除。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-328","chapter":12,"chapterTitle":"第十二章 触发器","number":105,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n触发器何时被激发？","options":[],"answer":"当触发器所绑定的表发生对应 INSERT、UPDATE 或 DELETE 事件，并满足 BEFORE/AFTER 等定义时自动执行。","explanation":"触发器不需要显式调用，执行频率取决于触发事件和行级/语句级定义。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-117","chapter":12,"chapterTitle":"第十二章 触发器","number":117,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"触发器的类型有三种，下面哪一种是错误的触发器类型。（ ）","options":["UPDATE","DELETE","ALTER","INSERT"],"answer":["C"],"explanation":"正确答案：C。常见 DML 触发器类型是 INSERT、UPDATE、DELETE，ALTER 不是触发器事件。","origin":"《数据库原理及应用》总复习"},{"id":"doc-118","chapter":12,"chapterTitle":"第十二章 触发器","number":118,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"触发器可以创建在（ ）中。","options":["表","过程","数据过程","函数"],"answer":["A"],"explanation":"正确答案：A。触发器绑定在表上，由该表的 INSERT、UPDATE 或 DELETE 操作自动触发。","origin":"《数据库原理及应用》总复习"},{"id":"doc-119","chapter":12,"chapterTitle":"第十二章 触发器","number":119,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"使用（ ）语句删除触发器trig_Test。","options":["DROP * FROM trig_Test","DROP trig_Tes","DROP TRIGGER WHERE NAME=‘trig_Test’","DROP TRIGGER trig_Test"],"answer":["D"],"explanation":"正确答案：D。删除触发器使用 DROP TRIGGER 触发器名。","origin":"《数据库原理及应用》总复习"},{"id":"doc-342","chapter":12,"chapterTitle":"第十二章 触发器","number":119,"title":"MySQL 操作题","kind":"open","answerKind":"open","typeName":"MySQL 操作题","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n为 sc 表创建插入触发器，若学号在 student 中不存在则拒绝插入；为学生删除创建级联删除成绩触发器；为学生学号更新创建同步更新 sc 学号触发器。","options":[],"answer":"```sql\nDELIMITER //\n\nCREATE TRIGGER student_sc_insert\nBEFORE INSERT ON sc\nFOR EACH ROW\nBEGIN\n    IF NOT EXISTS (SELECT 1 FROM student WHERE sno = NEW.sno) THEN\n        SIGNAL SQLSTATE '45000'\n        SET MESSAGE_TEXT = '学生学号不存在';\n    END IF;\nEND//\n\nCREATE TRIGGER student_delete\nAFTER DELETE ON student\nFOR EACH ROW\nBEGIN\n    DELETE FROM sc WHERE sno = OLD.sno;\nEND//\n\nCREATE TRIGGER student_sno\nAFTER UPDATE ON student\nFOR EACH ROW\nBEGIN\n    IF NEW.sno <> OLD.sno THEN\n        UPDATE sc SET sno = NEW.sno WHERE sno = OLD.sno;\n    END IF;\nEND//\n\nDELIMITER ;\n```","explanation":"原文档插入触发器在学号不存在时自动插入学生，这与题目的“给出错误提示”不一致；正确做法是使用 SIGNAL 拒绝操作。删除和更新触发器分别使用 OLD.sno 定位被影响的历史记录。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-120","chapter":12,"chapterTitle":"第十二章 触发器","number":120,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"一个触发器能定义在多少个表中？（ ）","options":["只有一个","一个或者多个","一个到三个","任意多个"],"answer":["A"],"explanation":"正确答案：A。一个触发器定义只能绑定一个表或视图，不能同时定义在多个表中。","origin":"《数据库原理及应用》总复习"},{"id":"doc-343","chapter":12,"chapterTitle":"第十二章 触发器","number":120,"title":"MySQL 操作题","kind":"open","answerKind":"open","typeName":"MySQL 操作题","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n查看当前数据库中各触发器的定义、状态和语法信息，并删除 student_sno 触发器。","options":[],"answer":"```sql\nSHOW TRIGGERS;\n\nSELECT trigger_name, event_manipulation, event_object_table,\n       action_timing, action_statement\nFROM information_schema.triggers\nWHERE trigger_schema = DATABASE();\n\nDROP TRIGGER IF EXISTS student_sno;\n```","explanation":"SHOW TRIGGERS 返回当前数据库触发器摘要，information_schema.triggers 可查看更详细的目标表、触发事件、执行时机和动作语句。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-121","chapter":12,"chapterTitle":"第十二章 触发器","number":121,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"在一个表上可以有（ ）种不同类型的触发器。","options":["一种","两种","三种","无限制"],"answer":["C"],"explanation":"正确答案：C。同一张表可分别定义 INSERT、UPDATE、DELETE 三类触发器。","origin":"《数据库原理及应用》总复习"},{"id":"doc-344","chapter":12,"chapterTitle":"第十二章 触发器","number":121,"title":"MySQL 操作题","kind":"open","answerKind":"open","typeName":"MySQL 操作题","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n使用图形工具完成触发器 student_sc_insert、student_delete、student_sno 的创建、查看和删除。","options":[],"answer":"图形工具操作对应上一题的 CREATE TRIGGER、SHOW TRIGGERS 和 DROP TRIGGER。删除表时其触发器会随表一起删除。","explanation":"触发器必须绑定到具体基本表。图形工具只是生成并执行等价 DDL，核心逻辑仍是 INSERT、DELETE、UPDATE 三类触发事件。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"13-01","chapter":13,"chapterTitle":"第十三章 综合设计案例","number":1,"title":"数据库设计综合题","kind":"open","answerKind":"open","typeName":"综合题","stem":"某在线书店需要管理图书、客户和订单：\n\n- 图书属性：ISBN、书名、价格、出版日期、库存。\n- 客户属性：客户编号、姓名、联系电话。\n- 订单属性：订单号、下单日期、总金额。\n- 一个客户可有多个订单，一个订单只属于一个客户。\n- 一个订单包含多本图书，一本图书可出现在多个订单中。\n- 订单明细需要记录数量。成交单价可以按当时价格保存。\n\n要求：\n\n1. 列出实体、主键和联系类型。\n2. 写出关系模式并标明主外键。\n3. 说明总金额是否是派生属性。\n4. 写出 OrderDetail 的建表 SQL 要点。","options":[],"answer":"实体为 Book(ISBN)、Customer(CustomerID)、Orders(OrderID)。Customer 与 Orders 是 1:N 的“下单”联系；Orders 与 Book 是 M:N 的“包含”联系，联系属性为 Quantity、UnitPrice。\n\n```text\nBook(ISBN PK, Title, Price, PublishDate, Stock)\nCustomer(CustomerID PK, Name, Phone)\nOrders(OrderID PK, OrderDate, TotalAmount, CustomerID FK)\nOrderDetail(OrderID PK/FK, ISBN PK/FK, Quantity, UnitPrice)\n```\n\nOrders.CustomerID 引用 Customer(CustomerID)；OrderDetail.OrderID 引用 Orders(OrderID)；OrderDetail.ISBN 引用 Book(ISBN)。总金额可由订单明细的 `SUM(Quantity * UnitPrice)` 计算，是派生属性。若样题明确要求保留，可以存字段，但必须由事务或触发器维护。","explanation":"标准 20 分设计题应按“实体 → 联系 → E-R 图 → 关系模式 → 主外键 → 范式检查”分步写。M:N 联系不单独建表会直接导致无法保存一本书在不同订单中的数量和成交价。OrderDetail 的复合主键要同时标注两列，两个外键要写完整引用对象。"},{"id":"13-02","chapter":13,"chapterTitle":"第十三章 综合设计案例","number":2,"title":"数据库设计综合题","kind":"open","answerKind":"open","typeName":"综合题","stem":"图书馆需要管理读者、图书和借阅。每名读者可借阅多本书，同一本书可被不同读者在不同时间借阅。借阅需记录借阅日期、应还日期和归还日期。允许同一读者归还后再次借同一本书。\n\n要求：\n\n1. 设计 Reader、Book、Borrow。\n2. 说明主键怎样表示“一次借阅”。\n3. 写出 Reader 与 Book 的联系类型。\n4. 说明能否只用 `(ReaderID, ISBN)` 作为 Borrow 主键。","options":[],"answer":"```text\nReader(ReaderID PK, ReaderName, Phone)\nBook(ISBN PK, Title, Author, Category)\nBorrow(BorrowID PK, ReaderID FK, ISBN FK,\n       BorrowDate, DueDate, ReturnDate)\n```\n\nReader 与 Book 之间是 M:N 的“借阅”联系，联系属性为借阅日期、应还日期和归还日期。BorrowID 唯一标识一次借阅，ReaderID 和 ISBN 分别作为外键。\n\n因为允许同一读者多次借同一本书，`(ReaderID, ISBN)` 会重复，不能作为唯一主键。可以增加 BorrowID，也可以让 BorrowDate 或借阅流水号参与主键。通常使用独立 BorrowID 更清晰。","explanation":"主键设计要符合业务粒度。Borrow 记录的是“某次借阅事件”，而不只是“读者和图书之间是否存在关系”。如果使用 `(ReaderID, ISBN)`，第二次借阅会与历史记录冲突，导致旧记录被覆盖或插入失败。归还日期可以为 NULL，表示尚未归还。"},{"id":"13-03","chapter":13,"chapterTitle":"第十三章 综合设计案例","number":3,"title":"数据库设计综合题","kind":"open","answerKind":"open","typeName":"综合题","stem":"人力资源系统需求：\n\n- 一个部门有多名员工，一名员工属于一个部门。\n- 一个员工可参与多个项目，一个项目可有多个员工。\n- 参与项目需要记录投入工时和项目角色。\n\n要求：\n\n1. 列出实体及主键。\n2. 设计关系模式并标明主外键。\n3. 说明 Department 与 Employee、Employee 与 Project 分别如何转换。\n4. 说明 WorksOn 的主键和联系属性。","options":[],"answer":"```text\nDepartment(DeptID PK, DeptName, Location)\nEmployee(EmpID PK, EmpName, Gender, Salary, HireDate, DeptID FK)\nProject(ProjectID PK, ProjectName, Budget)\nWorksOn(EmpID PK/FK, ProjectID PK/FK, Hours, ProjectRole)\n```\n\nDepartment 与 Employee 是 1:N，将 DeptID 放入 Employee。Employee 与 Project 是 M:N，必须建立 WorksOn 联系表，主键为 `(EmpID, ProjectID)`，Hours 和 ProjectRole 是联系属性。","explanation":"若同一员工在同一项目允许多次、分阶段参与，应该增加参与流水号或阶段号，而不能只用两列复合主键。Employee 的 DeptID 应允许为 NULL 还是 NOT NULL，取决于公司是否允许未分配部门的员工存在；题目未说明时应在答案中说明假设。"},{"id":"13-04","chapter":13,"chapterTitle":"第十三章 综合设计案例","number":4,"title":"数据库设计综合题","kind":"open","answerKind":"open","typeName":"综合题","stem":"课程系统需求：\n\n- 一个学生可选多门课程，一门课程可有多个学生。\n- 每名学生每门课程可重修多次，需要保留每次成绩和学期。\n- 学生有学号、姓名；课程有课程号、课程名、学分。\n\n要求：\n\n1. 设计 Student、Course、Enrollment。\n2. 给出 Enrollment 的主键。\n3. 说明成绩是否属于联系属性。\n4. 指出哪一设计会丢失重修历史。","options":[],"answer":"```text\nStudent(StudentID PK, StudentName)\nCourse(CourseID PK, CourseName, Credits)\nEnrollment(StudentID PK/FK, CourseID PK/FK,\n           Term, AttemptNo, Score)\n```\n\nEnrollment 主键至少包含 `(StudentID, CourseID, Term, AttemptNo)`，其中 Term 和 AttemptNo 用来区分重修次数。Score 是联系属性。\n\n如果只把 `(StudentID, CourseID)` 作为主键，同一学生同一门课的第二次重修会与第一次冲突，从而丢失历史。","explanation":"也可以使用 EnrollmentID 单独作为主键，但对 `(StudentID, CourseID, Term, AttemptNo)` 加唯一约束，仍然可以表达业务唯一性。重修记录的主键设计取决于学期内是否允许多次考试、补考或多次选课尝试，必须根据需求定义最小业务粒度。"},{"id":"13-05","chapter":13,"chapterTitle":"第十三章 综合设计案例","number":5,"title":"数据库设计综合题","kind":"open","answerKind":"open","typeName":"综合题","stem":"医院门诊系统需求：\n\n- 一个科室有多名医生，一名医生只属于一个科室。\n- 一个患者可预约多次，一次预约只对应一个患者和一个医生。\n- 预约需要记录预约日期、时间段和状态。\n- 医生有医生号、姓名、职称；患者有病历号、姓名、电话。\n\n要求：\n\n1. 列出实体和联系。\n2. 写出关系模式并标主外键。\n3. 说明预约表的主键选择。","options":[],"answer":"```text\nDepartment(DeptID PK, DeptName)\nDoctor(DoctorID PK, DoctorName, Title, DeptID FK)\nPatient(PatientID PK, PatientName, Phone)\nAppointment(AppointmentID PK, PatientID FK,\n            DoctorID FK, AppointmentDate, TimeSlot, Status)\n```\n\nDepartment 与 Doctor 是 1:N；Patient 与 Doctor 通过 Appointment 形成预约关系，一次预约还对应具体日期和时间。AppointmentID 唯一标识一次预约。","explanation":"是否允许多个患者在同一医生同一时间段预约，应由业务唯一约束控制。若有这个限制，可对 `(DoctorID, AppointmentDate, TimeSlot)` 加唯一约束；若允许并发或候补，则不能简单加唯一。状态字段可记录预约、取消、完成等，但状态变更要有审计和业务规则。"},{"id":"13-06","chapter":13,"chapterTitle":"第十三章 综合设计案例","number":6,"title":"数据库设计综合题","kind":"open","answerKind":"open","typeName":"综合题","stem":"酒店系统需求：\n\n- 房型有房型编号、名称、价格。\n- 房间有房间号、楼层、房型编号。\n- 客户可预订多个房间，多个日期区间可能对应同一房间。\n- 预订需要记录入住日期、离店日期、客户和房间。\n\n要求：\n\n1. 设计 RoomType、Room、Customer、Reservation。\n2. 说明房间号与房型编号的关系。\n3. 说明预订为什么要按日期区间判断冲突。","options":[],"answer":"```text\nRoomType(TypeID PK, TypeName, Price)\nRoom(RoomNo PK, Floor, TypeID FK)\nCustomer(CustomerID PK, CustomerName, Phone)\nReservation(ReservationID PK, CustomerID FK,\n            RoomNo FK, CheckInDate, CheckOutDate)\n```\n\n一个房型对应多个房间，Room.TypeID 是外键。预订记录必须保存日期区间，检查同一房间是否冲突时使用区间重叠判断，例如 `NewCheckIn < ExistingCheckOut AND NewCheckOut > ExistingCheckIn`。","explanation":"一个预订可能包含多个房间，也可在 Reservation 与 Room 之间再建立预订明细表。若采用多人共享一间房、多人入住或按床位销售，还需增加入住人或床位实体。不要因为“同一房间可以多次预订”就误判为 M:N 主键只需房间号，日期区间才是业务冲突判断的核心。"},{"id":"13-07","chapter":13,"chapterTitle":"第十三章 综合设计案例","number":7,"title":"数据库设计综合题","kind":"open","answerKind":"open","typeName":"综合题","stem":"采购库存系统需求：\n\n- 供应商可供应多种零件，一种零件可由多个供应商供应。\n- 每次供货要记录供货日期、数量和供货单价。\n- 仓库保存零件的当前库存，零件只对应一个默认仓库。\n\n要求：\n\n1. 设计 Supplier、Part、Supply、Warehouse。\n2. 说明 Supply 是实体还是联系表。\n3. 写出主外键并说明数量、单价的位置。\n4. 说明库存字段可能存在的冗余及维护方式。","options":[],"answer":"```text\nWarehouse(WarehouseID PK, WarehouseName)\nPart(PartID PK, PartName, WarehouseID FK)\nSupplier(SupplierID PK, SupplierName)\nSupply(SupplyID PK, SupplierID FK, PartID FK,\n       SupplyDate, Quantity, SupplyPrice)\n```\n\nSupply 是由 M:N 供货联系演化出的联系表，同时可作为供货事件实体。Quantity 和 SupplyPrice 描述某次供应，不应放在 Supplier 或 Part 中。Part.WarehouseID 表示默认仓库。库存字段可由入库、出库记录汇总得到，如保留 `CurrentStock` 属于受控冗余，应通过事务或触发器维护。","explanation":"如果业务只关心当前供应关系而不保存历史，可在 Supply 上使用 `(SupplierID, PartID)` 主键；本题每次供货都是独立事件，因此使用 SupplyID 或把供货日期纳入主键。库存维护优先采用重算或幂等更新，避免手工加加减减造成长期误差。"},{"id":"13-08","chapter":13,"chapterTitle":"第十三章 综合设计案例","number":8,"title":"数据库设计综合分析题","kind":"open","answerKind":"open","typeName":"综合题","stem":"某关系模式为：\n\n`OrderLine(OrderID, ISBN, BookTitle, BookPrice, Quantity)`\n\n已知 `(OrderID, ISBN)` 是候选键，`ISBN -> BookTitle, BookPrice`。要求：\n\n1. 指出范式问题。\n2. 分解到 3NF。\n3. 说明分解后的主外键。\n4. 说明为什么不建议把所有字段继续合并成一张宽表。","options":[],"answer":"BookTitle 和 BookPrice 只依赖 ISBN，存在对复合候选键 `(OrderID, ISBN)` 的部分依赖，因此不满足 2NF。分解为：\n\n```text\nBook(ISBN PK, BookTitle, BookPrice)\nOrderLine(OrderID PK/FK, ISBN PK/FK, Quantity)\n```\n\nOrderLine.OrderID 引用 Orders，OrderLine.ISBN 引用 Book。拆开后每本书的名称和价格只存一次，订单行只保存本次数量。\n\n不建议合并成宽表，因为同一本书会在多条订单行中重复书名和价格，容易产生更新异常；价格若是指当前价格还会随时间变化，订单中的历史成交价应按业务保留在订单行或价格快照中。","explanation":"BookPrice 可能同时存在“图书当前定价”和“订单成交价”两种语义，不能简单混为一个字段。如果订单需要保存历史成交单价，应在 OrderLine 中保留 UnitPrice，同时 Book 中保留当前 Price，两者语义不同。规范化首先要明确每个属性的业务含义。"},{"id":"doc-212","chapter":13,"chapterTitle":"第十三章 综合设计案例","number":1,"title":"数据库设计综合题","kind":"open","answerKind":"open","typeName":"数据库设计综合题","stem":"某大学实行学分制：每名学生可选修多门课程，每门课程可由多位教师讲授，每位教师也可讲授多门课程。\n\n学生属性：学号、姓名、性别、年龄、班级。\n课程属性：课程号、课程名。\n教师属性：教师号、教师姓名、所属系别、职称。\n选课联系属性：学期、成绩。\n\n要求：\n1. 判断学生与课程、课程与教师分别是什么联系类型。\n2. 写出关系模式，标明主键和外键。","options":[],"answer":"```text\n学生(学号 PK, 姓名, 性别, 年龄, 班级)\n课程(课程号 PK, 课程名)\n教师(教师号 PK, 教师姓名, 所属系别, 职称)\n选课(学号 PK/FK, 课程号 PK/FK, 学期, 成绩)\n讲授(课程号 PK/FK, 教师号 PK/FK)\n```","explanation":"学生与课程、课程与教师均为 M:N 联系，都要转换为独立联系表。课程关系中不应再保存“任课教师”，否则会与讲授联系重复并造成多值问题。选课关系主键通常为（学号，课程号）；若允许同一学生同一课程重修，应把学期或修读流水号加入主键。","origin":"《数据库原理及应用》总复习"},{"id":"doc-213","chapter":13,"chapterTitle":"第十三章 综合设计案例","number":2,"title":"数据库设计综合题","kind":"open","answerKind":"open","typeName":"数据库设计综合题","stem":"设计“医院病房管理系统”。已知：\n\n- 科室：科室名、地址、电话、主任。\n- 病房：病房号、床位号、所属科室。\n- 医生：工作证号、姓名、职称、年龄、所属科室。\n- 病人：病历号、姓名、性别、诊断、主管医生、病房号。\n- 一个科室有多个病房和多名医生，一个病房只属于一个科室，一名医生只属于一个科室。\n- 一名医生可负责多名病人，一名病人只有一个主管医生。\n\n要求写出关系模式并标明主、外键。","options":[],"answer":"```text\n科室(科室名 PK, 科室地址, 科室电话, 主任工作证号 FK)\n病房(病房号 PK, 所属科室名 FK)\n床位(病房号 PK/FK, 床位号 PK)\n医生(工作证号 PK, 姓名, 职称, 年龄, 所属科室名 FK)\n病人(病历号 PK, 姓名, 性别, 诊断, 主管医生工作证号 FK, 病房号 FK)\n```","explanation":"科室与病房、科室与医生都是 1:N，因此把科室名放入病房和医生表作外键。医生的姓名不能作为科室表中的多值属性保存，应使用主任工作证号引用医生。若题目规定每个病房只有一张床，可将床位表合并进病房表；这里保留床位表以完整表达“病房—床位”。","origin":"《数据库原理及应用》总复习"},{"id":"doc-214","chapter":13,"chapterTitle":"第十三章 综合设计案例","number":3,"title":"数据库设计综合题","kind":"open","answerKind":"open","typeName":"数据库设计综合题","stem":"设计“订单管理系统”。已知信息包括：订单号、客户号、客户名、客户地址、产品号、产品名、产品价格、订购数量、订购日期。一个客户可以有多个订单，一个订单可以订购多种产品。\n\n要求写出关系模式并标明主、外键。","options":[],"answer":"```text\n客户(客户号 PK, 客户名, 客户地址)\n订单(订单号 PK, 客户号 FK, 订购日期)\n产品(产品号 PK, 产品名, 产品价格)\n订单明细(订单号 PK/FK, 产品号 PK/FK, 订购数量)\n```","explanation":"客户与订单是 1:N，订单号放客户号外键；订单与产品是 M:N，必须建立订单明细表。订购日期属于整张订单，应放订单表而不是明细表；订购数量属于某订单中的某产品，应放订单明细表。","origin":"《数据库原理及应用》总复习"},{"id":"doc-215","chapter":13,"chapterTitle":"第十三章 综合设计案例","number":4,"title":"数据库设计综合题","kind":"open","answerKind":"open","typeName":"数据库设计综合题","stem":"设计网络玩具销售系统的关系模式。已知：\n\n- 客户：客户编号、姓名、性别、年龄、电话、通信地址。\n- 玩具：玩具编号、名称、类型、价格、库存数量。\n- 一个客户可以订购多种玩具，一种玩具也可被多个客户订购。\n\n要求写出关系模式并标明主、外键。","options":[],"answer":"```text\n客户(客户编号 PK, 姓名, 性别, 年龄, 电话, 通信地址)\n玩具(玩具编号 PK, 名称, 类型, 价格, 库存数量)\n订购(客户编号 PK/FK, 玩具编号 PK/FK, 订购数量)\n```","explanation":"客户与玩具是 M:N，订购表以客户编号和玩具编号组成复合主键。题目没有给出订单编号，因此按“同一客户与同一玩具只保存一条当前订购记录”处理；如果允许保留多次订单，应增加订单编号或订购时间参与主键。","origin":"《数据库原理及应用》总复习"},{"id":"doc-217","chapter":13,"chapterTitle":"第十三章 综合设计案例","number":6,"title":"数据库设计综合题","kind":"open","answerKind":"open","typeName":"数据库设计综合题","stem":"某企业集团有若干工厂。每个工厂生产多种产品，每种产品可在多个工厂生产，并记录计划生产数量；每个工厂聘用多名职工，每名职工只能在一个工厂工作，聘用关系记录聘期和工资。\n\n实体属性：\n- 工厂：工厂编号、厂名、地址。\n- 产品：产品编号、产品名、规格。\n- 职工：职工号、姓名。\n\n要求写出关系模式并指出主键。","options":[],"answer":"```text\n工厂(工厂编号 PK, 厂名, 地址)\n产品(产品编号 PK, 产品名, 规格)\n职工(职工号 PK, 姓名, 工厂编号 FK, 聘期, 工资)\n生产(工厂编号 PK/FK, 产品编号 PK/FK, 计划数量)\n```","explanation":"工厂与产品是 M:N，需建立生产联系表，主键为（工厂编号，产品编号）。工厂与职工是 1:N，且每名职工只属于一个工厂，可把工厂编号、聘期和工资并入职工关系，不必再单独建立聘用表。","origin":"《数据库原理及应用》总复习"},{"id":"14-01","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":1,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询工资大于 8000 的员工姓名和工资。","options":[],"answer":"```sql\nSELECT EmpName, Salary\nFROM Employee\nWHERE Salary > 8000;\n```","explanation":"这是最基础的单表条件查询。`>` 不包含等于，若题目写“大于等于”应改为 `>=`。只选取题目要求的列，不要无脑写 `SELECT *`。"},{"id":"14-02","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":2,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询计算机学院员工的姓名、工资和部门名称。","options":[],"answer":"```sql\nSELECT e.EmpName, e.Salary, d.DeptName\nFROM Employee e\nJOIN Department d\n  ON e.DeptID = d.DeptID\nWHERE d.DeptName = N'计算机学院';\n```","explanation":"员工姓名在 Employee，部门名称在 Department，需要按 DeptID 连接。连接条件放在 ON，业务过滤放在 WHERE。SQL Server 使用 `N` 前缀表示 Unicode；MySQL 通常直接写普通字符串。"},{"id":"14-03","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":3,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询没有员工的部门名称。","options":[],"answer":"```sql\nSELECT d.DeptName\nFROM Department d\nLEFT JOIN Employee e\n  ON d.DeptID = e.DeptID\nWHERE e.EmpID IS NULL;\n```\n\n**也可写作：**\n\n```sql\nSELECT d.DeptName\nFROM Department d\nWHERE NOT EXISTS (\n    SELECT 1\n    FROM Employee e\n    WHERE e.DeptID = d.DeptID\n);\n```","explanation":"LEFT JOIN 后右表无匹配会产生 NULL，因此用右表主键 IS NULL 找出无员工部门。不要用 `COUNT(e.EmpID) = 0` 再放在 WHERE，因为 COUNT 是聚合函数，需要 HAVING。NOT EXISTS 语义更直接，也避免 NULL 陷阱。"},{"id":"14-04","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":4,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"按部门统计员工人数，并按人数降序排列。","options":[],"answer":"```sql\nSELECT DeptID, COUNT(*) AS 员工人数\nFROM Employee\nGROUP BY DeptID\nORDER BY 员工人数 DESC;\n```","explanation":"`GROUP BY DeptID` 每组产生一行，COUNT 统计该组行数。若部门没有员工，它不会出现在 Employee 的分组结果中；题目若要求保留无员工部门，应从 Department 表出发左连接。"},{"id":"14-05","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":5,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询平均工资高于 7000 的部门号、人数和平均工资。","options":[],"answer":"```sql\nSELECT DeptID,\n       COUNT(*) AS 人数,\n       AVG(Salary) AS 平均工资\nFROM Employee\nGROUP BY DeptID\nHAVING AVG(Salary) > 7000;\n```","explanation":"平均工资属于组级条件，应放在 HAVING。COUNT(*) 包括工资为 NULL 的员工；AVG(Salary) 忽略 NULL。如果题目人数的口径是“工资已登记的人数”，应改为 `COUNT(Salary)`。"},{"id":"14-07","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":7,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询和“张三”同部门的其他员工姓名。","options":[],"answer":"```sql\nSELECT EmpName\nFROM Employee\nWHERE DeptID = (\n    SELECT DeptID\n    FROM Employee\n    WHERE EmpName = N'张三'\n)\nAND EmpName <> N'张三';\n```","explanation":"内层查询找到张三的部门号。若可能有多名员工都叫张三且分属不同部门，用 `=` 的标量子查询可能报错或行为不确定，应改用 JOIN 或 `IN`，并最好用员工号唯一标识张三。`EmpName <> N'张三'` 排除本人。"},{"id":"14-08","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":8,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询从未下过订单的客户姓名。","options":[],"answer":"```sql\nSELECT c.CustomerName\nFROM Customer c\nWHERE NOT EXISTS (\n    SELECT 1\n    FROM Orders o\n    WHERE o.CustomerID = c.CustomerID\n);\n```","explanation":"外层每名客户检查是否存在订单。若不存在，保留该客户。相比 `NOT IN (SELECT CustomerID FROM Orders)`，NOT EXISTS 不受子查询 NULL 影响，是“没有关联记录”类题目的稳妥写法。"},{"id":"14-09","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":9,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询每个订单的订单号、客户姓名和订单明细汇总金额，只统计已有明细的订单。","options":[],"answer":"```sql\nSELECT o.OrderID,\n       c.CustomerName,\n       SUM(od.Quantity * od.UnitPrice) AS 明细金额\nFROM Orders o\nJOIN Customer c\n  ON o.CustomerID = c.CustomerID\nJOIN OrderDetail od\n  ON o.OrderID = od.OrderID\nGROUP BY o.OrderID, c.CustomerName\nORDER BY o.OrderID;\n```","explanation":"金额必须先按订单汇总，不能在订单表与明细表连接后直接对不同粒度字段随意求和。如果题目要求保留没有明细的订单，应把明细连接改为 LEFT JOIN，并用 `COALESCE(SUM(...), 0)` 处理 NULL。"},{"id":"14-10","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":10,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询从未出现在订单明细中的图书 ISBN 和书名。","options":[],"answer":"```sql\nSELECT b.ISBN, b.Title\nFROM Book b\nWHERE NOT EXISTS (\n    SELECT 1\n    FROM OrderDetail od\n    WHERE od.ISBN = b.ISBN\n);\n```","explanation":"题目问的是“在订单明细中从未出现”，不是“库存为 0”。两者业务含义不同。使用 NOT EXISTS 能直接表达反连接语义，并避免 NOT IN 子查询出现 NULL 的风险。"},{"id":"14-11","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":11,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询工资最高的前 3 名员工。分别给出 SQL Server 和 MySQL 写法。","options":[],"answer":"```sql\n-- SQL Server\nSELECT TOP 3 EmpName, Salary\nFROM Employee\nORDER BY Salary DESC;\n\n-- MySQL\nSELECT EmpName, Salary\nFROM Employee\nORDER BY Salary DESC\nLIMIT 3;\n```","explanation":"Top-N 必须明确排序。若存在并列第 3 名，上述写法只固定返回 3 行，不保证包含全部并列者。若要求并列名次统一显示，可使用 `DENSE_RANK() OVER (ORDER BY Salary DESC) <= 3`。"},{"id":"14-12","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":12,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询每个部门工资前 2 名的员工姓名、部门号和工资。","options":[],"answer":"```sql\nWITH Ranked AS (\n    SELECT EmpName,\n           DeptID,\n           Salary,\n           DENSE_RANK() OVER (\n               PARTITION BY DeptID\n               ORDER BY Salary DESC\n           ) AS rn\n    FROM Employee\n)\nSELECT EmpName, DeptID, Salary\nFROM Ranked\nWHERE rn <= 2;\n```","explanation":"`PARTITION BY DeptID` 在每个部门内部排名，`DENSE_RANK` 对相同工资给出相同名次。MySQL 8.0 和 SQL Server 2019 都支持该窗口函数。若必须使用旧版本，可用相关子查询计算“比我工资高的人数少于 2”。"},{"id":"14-13","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":13,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"按月统计订单数量、销售数量和销售金额。","options":[],"answer":"```sql\nSELECT YEAR(o.OrderDate) AS 年份,\n       MONTH(o.OrderDate) AS 月份,\n       COUNT(DISTINCT o.OrderID) AS 订单数,\n       SUM(od.Quantity) AS 销售数量,\n       SUM(od.Quantity * od.UnitPrice) AS 销售金额\nFROM Orders o\nJOIN OrderDetail od\n  ON o.OrderID = od.OrderID\nGROUP BY YEAR(o.OrderDate), MONTH(o.OrderDate)\nORDER BY 年份, 月份;\n```","explanation":"一个订单可能有多条明细，连接后订单会出现多行，因此订单数要写 `COUNT(DISTINCT o.OrderID)`，不能直接 `COUNT(*)`。按月分组也可以使用 MySQL 的 `DATE_FORMAT(OrderDate, '%Y-%m')` 或 SQL Server 的 `EOMONTH` 等函数。"},{"id":"14-14","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":14,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"按订单状态统计各状态订单数，并把“待付款、已付款、已完成、已取消”转换为四个列。","options":[],"answer":"```sql\nSELECT\n    SUM(CASE WHEN Status = N'待付款' THEN 1 ELSE 0 END) AS 待付款,\n    SUM(CASE WHEN Status = N'已付款' THEN 1 ELSE 0 END) AS 已付款,\n    SUM(CASE WHEN Status = N'已完成' THEN 1 ELSE 0 END) AS 已完成,\n    SUM(CASE WHEN Status = N'已取消' THEN 1 ELSE 0 END) AS 已取消\nFROM Orders;\n```","explanation":"这是行转列模板。每个 CASE 对满足状态的行返回 1，否则返回 0，再 SUM。四列之和应等于订单总数。若状态字段可能为 NULL，需要按业务决定是否把 NULL 计入“未知”类。"},{"id":"14-15","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":15,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"把员工姓名和客户姓名合并成一个联系人名单，并增加来源列；要求去除完全重复的行。","options":[],"answer":"```sql\nSELECT EmpName AS ContactName, N'员工' AS SourceType\nFROM Employee\nUNION\nSELECT CustomerName AS ContactName, N'客户' AS SourceType\nFROM Customer;\n```","explanation":"UNION 要求两次查询的列数相同、对应列类型兼容，并对整个结果行去重。由于加入了来源列，即使员工和客户同名，也会因 SourceType 不同而保留为两行。若只想合并姓名并去重，不返回来源列即可。"},{"id":"14-16","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":16,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"创建计算机学院员工视图 `v_computer_emp`，显示员工号、姓名、工资和部门名称。","options":[],"answer":"```sql\nCREATE VIEW v_computer_emp AS\nSELECT e.EmpID,\n       e.EmpName,\n       e.Salary,\n       d.DeptName\nFROM Employee e\nJOIN Department d\n  ON e.DeptID = d.DeptID\nWHERE d.DeptName = N'计算机学院';\n```","explanation":"视图可以封装连接和固定条件。由于包含多表连接，是否可直接通过该视图执行 INSERT、UPDATE、DELETE 取决于 DBMS；考试中应把它主要视为查询视图，不要假定所有列都可更新。"},{"id":"14-17","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":17,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"为员工姓名字段创建索引，并说明该索引可能无效或收益很小的情况。","options":[],"answer":"```sql\nCREATE INDEX idx_emp_name\nON Employee(EmpName);\n```\n\n可能收益较小或无法有效使用的情况包括：表很小、姓名频繁更新、姓名选择性很低、查询写成 `LIKE '%名'`、在索引列上使用函数或发生隐式类型转换。","explanation":"索引不是越多越好。创建后应使用 `EXPLAIN` 或执行计划查看是否实际使用，并比较查询与写入维护成本。若业务经常按姓名精确查询或前缀查询，普通索引可能有效；若只按部门查询，姓名索引没有帮助。"},{"id":"14-19","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":19,"title":"编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"创建 SQL Server 触发器：订单明细插入后扣减对应图书库存。","options":[],"answer":"```sql\nCREATE TRIGGER trg_orderdetail_insert\nON OrderDetail\nAFTER INSERT\nAS\nBEGIN\n    UPDATE b\n    SET b.Stock = b.Stock - i.Quantity\n    FROM Book b\n    JOIN inserted i\n      ON b.ISBN = i.ISBN;\nEND;\n```","explanation":"触发器必须按集合处理 `inserted`。如果一次插入中同一 ISBN 出现多行，示例 UPDATE 的 JOIN 可能产生语义模糊，应先用派生表按 ISBN 汇总数量。生产系统还应检查库存是否足够，并在触发器或事务中阻止负库存。"},{"id":"14-20","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":20,"title":"综合编程题","kind":"open","answerKind":"open","typeName":"综合题","stem":"查询购买了所有价格低于 50 元的图书的客户姓名。请使用关系除法思想。","options":[],"answer":"```sql\nSELECT c.CustomerName\nFROM Customer c\nWHERE NOT EXISTS (\n    SELECT 1\n    FROM Book b\n    WHERE b.Price < 50\n      AND NOT EXISTS (\n          SELECT 1\n          FROM Orders o\n          JOIN OrderDetail od\n            ON o.OrderID = od.OrderID\n          WHERE o.CustomerID = c.CustomerID\n            AND od.ISBN = b.ISBN\n      )\n);\n```","explanation":"外层含义是“不存在一本价格低于 50 元的书，是该客户没有买过的”。内层先遍历符合条件的书，再检查该客户是否有订单包含它。这就是关系除法 `R ÷ S` 的 SQL 表达。若一本书从未被任何客户购买，这个客户也不会误判为已购买；只有书籍集合非空时，结果才有明确的“全部购买”含义。\n\n---\n\n# 考场使用建议\n\n## 先判断题型，再选答题模板\n\n- 单选题先排除概念错误项，尤其注意“所有、一定、完全等价”这类绝对表述。\n- 填空题优先回忆标准术语和关键字，不要用口语替代 `HAVING`、`PRIMARY KEY`、`OUTPUT`、`TEST` 等术语。\n- SQL 题先写骨架，再补表连接、筛选、分组和排序，最后检查主外键与 NULL。\n- 设计题务必分步写出实体、联系、基线数、关系模式和主外键，即使 E-R 图不完美，也能稳拿分步分。\n- 存储过程和触发器题先判断 DBMS，再写参数、分隔符、虚拟表和事务注意事项。\n\n## 每题后的复盘三问\n\n1. 我错在概念不清、语法不熟，还是没有看懂业务规则？\n2. 正确答案对应哪一个知识点，能否用一句话复述？\n3. 如果把题目改一个条件，我还能不能做对？\n\n## 高频易错提醒\n\n- DB 与 DBMS 不同，DBS 是包含人员、应用和运行环境的整体。\n- 主键一定非空且唯一，候选键可以有多个，外键可以重复并可为 NULL。\n- 文件系统与数据库系统的本质区别是数据整体结构化。\n- 1:N 不单独建表，M:N 必须建表，1:1 外键要加唯一约束。\n- 2NF 消除部分依赖，3NF 消除传递依赖，BCNF 要求每个决定因素都是超键。\n- `COUNT(*)` 与 `COUNT(列)` 对 NULL 的统计不同。\n- `WHERE` 在分组前过滤行，`HAVING` 在分组后过滤组。\n- 左连接后统计关联行数通常用 `COUNT(右表.主键)`。\n- `NOT IN` 遇 NULL 可能整体失效，优先使用 `NOT EXISTS`。\n- 视图通常是虚表，复杂视图通常不可直接更新。\n- 索引会加快部分查询，但增加存储和写入维护成本。\n- MySQL 存储过程使用 `DELIMITER`，SQL Server 触发器使用 `inserted`、`deleted`。\n- 触发器必须按集合处理多行 DML，不能假设一次只影响一行。\n- 规范化减少冗余和异常，但可能增加连接成本，实际设计要平衡。\n\n## 最后的自检清单\n\n- 14 章是否都完成了一遍独立作答？\n- 所有 SQL 题是否亲手写到了纸上？\n- E-R 图是否至少手画了 10 张，并标注了基数和联系属性？\n- 是否能在 3 分钟内判断一个关系模式的候选键和常见范式？\n- 是否能区分数据库设计五阶段、视图可更新性、索引类型和触发器事件？\n- 是否把错题按“概念、SQL、设计、编程、方言差异”分类复盘？"},{"id":"doc-203","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":72,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"MySQL的访问控制分为连接核实和请求核实两个阶段。","options":[],"answer":"对","explanation":"答案：对。MySQL 访问控制通常分为连接核实和请求核实两个阶段。","origin":"《数据库原理及应用》总复习"},{"id":"doc-204","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":73,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"当某用户试图连接MySQL服务器进行查询操作时，如果不能通过身份验证，该用户仍然可以进行查询操作。","options":[],"answer":"错","explanation":"答案：错。用户必须通过身份验证并具备相应权限，才能连接和执行查询。","origin":"《数据库原理及应用》总复习"},{"id":"doc-205","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":74,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"为用户授权时只能授予全局权限，不能授予数据库权限。","options":[],"answer":"错","explanation":"答案：错。MySQL 可授予全局、数据库、表、列和存储程序等不同级权限。","origin":"《数据库原理及应用》总复习"},{"id":"doc-206","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":75,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"要想在MySQL中创建新的用户，必须有相应的操作权限。","options":[],"answer":"对","explanation":"答案：对。创建用户需要 CREATE USER 权限或等价的账户管理权限。","origin":"《数据库原理及应用》总复习"},{"id":"doc-207","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":76,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"已授权给某用户的权限不能收回。","options":[],"answer":"错","explanation":"答案：错。已授予的权限可以使用 REVOKE 收回。","origin":"《数据库原理及应用》总复习"},{"id":"doc-208","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":77,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"数据库恢复可以利用备份并结合日志完成。","options":[],"answer":"对","explanation":"答案：对。数据库恢复可以利用备份并结合日志把数据库恢复到一致状态。","origin":"《数据库原理及应用》总复习"},{"id":"doc-209","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":78,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"数据备份就是制作数据库结构、对象和数据的复制，以便在数据库遭到破坏时可以恢复数据库。","options":[],"answer":"对","explanation":"答案：对。备份是复制数据库结构、对象和数据，以便故障后恢复。","origin":"《数据库原理及应用》总复习"},{"id":"doc-210","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":79,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"数据恢复就是当数据库出现故障时，将备份的数据库加载到系统，使数据库恢复到备份时的正确状态。","options":[],"answer":"对","explanation":"答案：对。恢复是在故障后加载备份并重做或撤销日志，使数据库回到一致状态。","origin":"《数据库原理及应用》总复习"},{"id":"doc-211","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":80,"title":"判断","kind":"judge","answerKind":"judge","typeName":"判断","stem":"当数据库遭到意外损坏时，可以通过日志文件查询出错原因，还可以通过日志文件进行数据恢复。","options":[],"answer":"对","explanation":"答案：对。日志可用于审计和故障分析，也可配合备份进行重做或撤销恢复。","origin":"《数据库原理及应用》总复习"},{"id":"doc-329","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":106,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\nmysqladmin 命令能否修改普通用户的密码？为什么？","options":[],"answer":"在具备权限和正确认证的前提下可以修改密码；MySQL 8 更推荐使用 ALTER USER。普通用户通常只能修改自己的密码。","explanation":"密码管理受账户权限限制，管理员可管理其他用户，普通用户不能越权修改他人密码。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-330","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":107,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n创建用户的方法有哪几种？","options":[],"answer":"常用方法包括 CREATE USER、具备权限时使用 GRANT 创建账户的旧语法，以及 Navicat 等管理工具。","explanation":"MySQL 8.0 推荐先 CREATE USER，再 GRANT 权限，避免旧式 GRANT 隐式建用户。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-331","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":108,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n如何选择备份数据库的方法？","options":[],"answer":"应综合数据库大小、存储引擎、可停机时间、恢复点目标、恢复时间目标和存储成本，选择逻辑备份、物理备份、全量备份或增量备份。","explanation":"小库和跨版本迁移常用 mysqldump；大库热备和快速恢复通常需要物理备份或专业备份工具。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-332","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":109,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\nmysqldump 生成的文件只能在 MySQL 中使用吗？","options":[],"answer":"标准 SQL 转储文件主要用于 MySQL 或兼容的 MariaDB；其中的语法和数据类型可能不完全兼容其他 DBMS。","explanation":"XML 等导出格式可被其他程序读取，但仍受字段和数据语义限制。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-333","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":110,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n平时通常应该开启哪些日志？","options":[],"answer":"生产环境通常开启错误日志和慢查询日志，有恢复或复制需求时开启二进制日志；通用查询日志开销较大，通常按需临时开启。","explanation":"日志策略需平衡审计价值、磁盘空间和性能开销。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-334","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":111,"title":"SQL 简答","kind":"open","answerKind":"open","typeName":"SQL 简答","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n如何使用二进制日志和慢查询日志？","options":[],"answer":"二进制日志用于复制和基于时间点的重做恢复；慢查询日志用于发现执行时间长的 SQL，再结合执行计划优化索引和语句。","explanation":"二进制日志记录数据变更，慢查询日志记录性能问题，两者用途不同。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-122","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":122,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"要想移除账户，应使用（ ）语句。","options":["DELETE USER","DROP USER","DELETE PRIV","DROP PRIV"],"answer":["B"],"explanation":"正确答案：B。删除数据库账户使用 DROP USER；DELETE 是删除表中数据的 DML 语句。","origin":"《数据库原理及应用》总复习"},{"id":"doc-345","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":122,"title":"MySQL 操作题","kind":"open","answerKind":"open","typeName":"MySQL 操作题","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n创建 aric 用户，密码 abcdef，并授予 gradem 数据库 SELECT、UPDATE、DROP 权限；修改密码、查看权限、收回删除权限并删除用户。","options":[],"answer":"```sql\nCREATE USER 'aric'@'localhost' IDENTIFIED BY 'abcdef';\nGRANT SELECT, UPDATE, DROP ON gradem.* TO 'aric'@'localhost';\n\nALTER USER 'aric'@'localhost' IDENTIFIED BY '123456';\nSHOW GRANTS FOR 'aric'@'localhost';\n\nREVOKE DROP ON gradem.* FROM 'aric'@'localhost';\nDROP USER 'aric'@'localhost';\n```","explanation":"MySQL 8.0 应先 CREATE USER 再 GRANT，不再推荐用 GRANT 隐式创建账户。修改密码使用 ALTER USER，权限核实使用 SHOW GRANTS。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-346","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":123,"title":"MySQL 操作题","kind":"open","answerKind":"open","typeName":"MySQL 操作题","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n创建 exam1 用户并授予全局 SELECT、CREATE、DROP、SUPER 和 GRANT OPTION；创建无密码的 exam2；修改密码、授予和收回权限，最后删除两个用户。","options":[],"answer":"```sql\nCREATE USER 'exam1'@'localhost' IDENTIFIED BY '123456';\nGRANT SELECT, CREATE, DROP, SUPER\nON *.* TO 'exam1'@'localhost'\nWITH GRANT OPTION;\n\nCREATE USER 'exam2'@'localhost';\nALTER USER 'exam2'@'localhost' IDENTIFIED BY '000000';\n\nGRANT CREATE, DROP ON *.* TO 'exam2'@'localhost';\nSHOW GRANTS FOR 'exam2'@'localhost';\n\nREVOKE ALL PRIVILEGES, GRANT OPTION\nFROM 'exam1'@'localhost', 'exam2'@'localhost';\n\nDROP USER 'exam1'@'localhost', 'exam2'@'localhost';\n```","explanation":"全局权限使用 ON *.*，数据库级权限使用 ON 数据库名.*。授予 GRANT OPTION 会让用户可以把自身权限继续授予他人，应谨慎使用。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-124","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":124,"title":"单项选择","kind":"choice","answerKind":"choice","typeName":"单项选择","stem":"使用SELECT将表中数据导出到文件，可以使用哪一子句？（ ）。","options":["TO FILE","INTO FILE","OUTTO FILE","INTO OUTFILE"],"answer":["D"],"explanation":"正确答案：D。MySQL 使用 SELECT ... INTO OUTFILE 将查询结果导出到服务器文件。","origin":"《数据库原理及应用》总复习"},{"id":"doc-347","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":124,"title":"MySQL 操作题","kind":"open","answerKind":"open","typeName":"MySQL 操作题","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n使用图形工具备份 gradem 数据库和 student 表，删除数据库或表后再恢复。","options":[],"answer":"图形工具的备份与恢复最终可使用 mysqldump 和 mysql 客户端完成。完整数据库恢复前需创建目标数据库，表级恢复前需保证目标表存在。","explanation":"备份文件应保存在独立目录并验证可恢复性。恢复前先检查字符集、外键、用户权限和是否存在同名对象。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-348","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":125,"title":"MySQL 操作题","kind":"open","answerKind":"open","typeName":"MySQL 操作题","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n使用 mysqldump 备份 gradem 数据库，以及 course、sc 两张表；再使用 mysql 或 source 命令恢复。","options":[],"answer":"```sql\nmysqldump -u root -p gradem > D:/mysqlbak/gbak.sql\nmysqldump -u root -p gradem course sc > D:/mysqlbak/cs.sql\n\nmysql -u root -p -e \"CREATE DATABASE IF NOT EXISTS gradem\"\nmysql -u root -p gradem < D:/mysqlbak/gbak.sql\n\n-- 登录 MySQL 后也可执行：\nSOURCE D:/mysqlbak/cs.sql;\n```","explanation":"mysqldump 默认生成逻辑 SQL 备份。恢复数据库前需确保目标库存在；恢复表时要保证库和表结构匹配。命令行参数 -p 后不要直接跟密码，以免泄露。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-349","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":126,"title":"MySQL 操作题","kind":"open","answerKind":"open","typeName":"MySQL 操作题","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n使用 SELECT ... INTO OUTFILE 导出 sc 表，再清空 sc 表并用 LOAD DATA INFILE 导回。","options":[],"answer":"```sql\nSELECT * FROM sc\nINTO OUTFILE 'D:/mysqlbak/scbak.txt'\nFIELDS TERMINATED BY ',' ENCLOSED BY '\"' ESCAPED BY '\\\\'\nLINES TERMINATED BY '\\r\\n';\n\nTRUNCATE TABLE sc;\n\nLOAD DATA INFILE 'D:/mysqlbak/scbak.txt'\nINTO TABLE sc\nFIELDS TERMINATED BY ',' ENCLOSED BY '\"' ESCAPED BY '\\\\'\nLINES TERMINATED BY '\\r\\n';\n```","explanation":"INTO OUTFILE 和 LOAD DATA INFILE 需要 FILE 权限及 secure_file_priv 允许的目录。导回前要保证字段顺序、分隔符和字符集一致。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-350","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":127,"title":"MySQL 操作题","kind":"open","answerKind":"open","typeName":"MySQL 操作题","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n开启二进制日志并指定日志目录，查看日志，插入和删除数据后使用二进制日志恢复，最后清理旧日志。","options":[],"answer":"```ini\n# my.ini\n[mysqld]\nlog-bin=D:/mysql/log/mysql-bin\n```","explanation":"修改配置后需重启服务。SHOW BINARY LOGS、SHOW BINLOG EVENTS 和 mysqlbinlog 可查看日志；恢复时把 mysqlbinlog 输出重新导入 MySQL，并用 PURGE BINARY LOGS 清理已确认不再需要的日志。","origin":"《数据库原理及应用》总复习 SQL 练习"},{"id":"doc-351","chapter":14,"chapterTitle":"第十四章 综合 SQL 练习","number":128,"title":"MySQL 操作题","kind":"open","answerKind":"open","typeName":"MySQL 操作题","stem":"已知 gradem 数据库：\nstudent(sno, sname, ssex, sbirthday, saddress, sdept, speciality, classno)；\ncourse(cno, cname)；\nsc(sno, cno, degree)；\nteacher(tno, tname, tsex, tbirthday, sdept)；\nteaching(cno, tno, cterm)。\n\n配置并查看 MySQL 错误日志、通用查询日志和慢查询日志，最后清理日志。","options":[],"answer":"```sql\nSET GLOBAL general_log = ON;\nSET GLOBAL general_log_file = 'D:/mysql/log/general.log';\nSET GLOBAL slow_query_log = ON;\nSET GLOBAL slow_query_log_file = 'D:/mysql/log/slow.log';\nSET GLOBAL long_query_time = 2;\n\nSHOW VARIABLES LIKE 'log_error';\nSHOW VARIABLES LIKE '%log%';\nFLUSH LOGS;\n```","explanation":"错误日志通常由配置项 log_error 指定；通用查询日志记录全部语句，开销较大；慢查询日志记录超过 long_query_time 的语句。日志目录需要 MySQL 服务账户可写。","origin":"《数据库原理及应用》总复习 SQL 练习"}]};
